var e={id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi`,sira:17,kurul:1,ders:`Enfeksiyon Hastalıkları`,konu:`Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi`,ogretim_uyesi:`Dr. Öğr. Üyesi Rüveyda Korkmazer`,tarih:`2026-09-21`,soru_sayisi:204,kazanimlar:[{no:1,metin:`Cinsel yolla bulaşan hastalıklarda (CYBH) etkenleri bakteri, virüs ve parazit olarak sınıflandırabilmek`,sorular:[{id:`k1-17-q01`,kazanim:1,zorluk:`kolay`,soru:`Aşağıdaki CYBH etkenlerinden hangisi paraziter bir etkendir?`,secenekler:{A:`Neisseria gonorrhoeae`,B:`Trichomonas vaginalis`,C:`Chlamydia trachomatis`,D:`HPV`,E:`Haemophilus ducreyi`},dogru:`B`,aciklama:`Paraziter CYBH etkenleri T. vaginalis, Phthirus pubis ve Sarcoptes scabiei'dir.`,sik_aciklamalari:{A:`Bakteridir; bu nedenle doğru seçenek değildir.`,B:`Doğru: kamçılı protozoondur.`,C:`Bakteridir; bu nedenle doğru seçenek değildir.`,D:`Virüstür; bu nedenle doğru seçenek değildir.`,E:`Bakteridir; bu nedenle doğru seçenek değildir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-17-q02`,kazanim:1,zorluk:`orta`,soru:`Aşağıdakilerden hangisi viral CYBH etkenidir?`,secenekler:{A:`Mycoplasma genitalium`,B:`Klebsiella granulomatis`,C:`Molluscum contagiosum`,D:`Treponema pallidum`,E:`Sarcoptes scabiei`},dogru:`C`,aciklama:`Viral etkenler HBV, HPV, CMV, EBV, Molluscum contagiosum, adenovirus ve HCV'dir.`,sik_aciklamalari:{A:`Bakteridir; bu nedenle doğru seçenek değildir.`,B:`Bakteridir; bu nedenle doğru seçenek değildir.`,C:`Doğru: poksvirüs ailesinden viral etkendir.`,D:`Spiroket bakteridir.`,E:`Parazittir; bu nedenle doğru seçenek değildir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-17-q03`,kazanim:1,zorluk:`zor`,soru:`CYBH etkenleri ile grup eşleştirmelerinden hangisi yanlıştır?`,secenekler:{A:`Phthirus pubis – parazit`,B:`Haemophilus ducreyi – bakteri`,C:`Klebsiella granulomatis – bakteri`,D:`CMV – virüs`,E:`Mycoplasma genitalium – virüs`},dogru:`E`,aciklama:`Mycoplasma genitalium bakteriyel bir CYBH etkenidir.`,sik_aciklamalari:{A:`Doğru eşleştirme; bu nedenle doğru seçenek değildir.`,B:`Doğru eşleştirme; bu nedenle doğru seçenek değildir.`,C:`Doğru eşleştirme; bu nedenle doğru seçenek değildir.`,D:`Doğru eşleştirme; bu nedenle doğru seçenek değildir.`,E:`Yanlış eşleştirme (aranan cevap): bakteridir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k01-q04`,kazanim:1,zorluk:`orta`,soru:`27 yaşındaki bir hasta akut başvuru yapan ve laboratuvar-görüntüleme bulguları birlikte değerlendirilen bir olguda hekime başvuruyor. Değerlendirmede "Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya gebelik/doğum sırasında ve sonrasında anneden bebeğe olur." bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "Cinsel yolla bulaşan hastalıklarda (CYBH) etkenleri bakteri, virüs ve parazit olarak sınıflandırabilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya… ilkesinin tam tersi geçerlidir ve Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi ve… gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Bulaş yolları olup "Cinsel yolla bulaşan hastalıklarda (CYBH) etkenleri…" ile ilişkisizdir`,C:`Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya gebelik/doğum sırasında ve sonrasında anneden bebeğe olur. Bu nedenle Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi ve tarama gerektirir.`,D:`Bulgular "Cinsel yolla bulaşan hastalıklarda (CYBH) etkenleri bakteri, virüs ve…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Bulaş yolları" ile açıklanamaz`},dogru:`C`,aciklama:`Robbins/Harrison mantığıyla: Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya gebelik/doğum sırasında ve sonrasında anneden bebeğe olur. Doğrudan sonucu "Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi ve tarama gerektirir." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`,C:`Doğru; Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya gebelik/doğum…`,D:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k01-q05`,kazanim:1,zorluk:`zor`,soru:`Farklı bir hasta hastalığın seyri ve prognozunun değerlendirildiği ayrı bir vakada ele alınıyor. Öyküde "Bulaş yolları" vurgulanıyor ve hekim "Cinsel yolla bulaşan hastalıklarda (CYBH) etkenleri bakteri, virüs ve parazit olarak sınıflandırabilmek" kazanımındaki "Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya gebelik/doğum sırasında ve sonrasında anneden bebeğe olur." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi ve tarama gerektirir. hiçbir koşulda gözlenmez ve Bulaş yolları tek belirleyicidir`,B:`Bu süreçte "Bulaş yolları" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Benzer tabloların tamamı aynı nedene bağlıdır; "Bulaş yolları" ayırıcı tanıda gereksizdir`,D:`Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi ve tarama gerektirir. Çünkü Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya gebelik/doğum…`,E:`Bu olguda izlem gerekmez; "Cinsel yolla bulaşan hastalıklarda (CYBH) etkenleri bakteri, virüs ve…" yalnızca teorik bir bilgidir`},dogru:`D`,aciklama:`Guyton/Robbins bütünlüğünde: Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya gebelik/doğum sırasında ve sonrasında anneden bebeğe olur. sonucu "Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi ve tarama gerektirir." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`,D:`Doğru; Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi ve tarama gerektirir. Çünkü Bulaş…`,E:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k01-q06`,kazanim:1,zorluk:`orta`,soru:`CYBH etken sınıflaması: Etkenler bakteri (N. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Nongonokokal üretrit/servisit tedavisi azitromisin veya doksisiklin içerir`,B:`Direnç nedeniyle güncel antibiyograma göre tedavi planlanmasını sağlar`,C:`Uygun olguda ayaktan tedavi, komplike olguda IV tedavi seçilir`,D:`Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter)`,E:`Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur`},dogru:`D`,aciklama:`Etkenler bakteri (N. Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter) belirlemenin ilk adımıdır. Fizyopatolojik sıra bu yönde ilerlediğinden Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T varlığında Etken grubunu bilmek tedavi ile korunma stratejisini beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt D seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Nongonokokal enfeksiyon sürecine ait bir özelliktir ve cybh etken sınıflaması düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade N. gonorrhoeae kültürü sürecine ait bir özelliktir ve cybh etken sınıflaması düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade PİH yatış endikasyonları sürecine ait bir özelliktir ve cybh etken sınıflaması düzeneğini tanımlamaz.`,D:`Doğru; Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter) belirlemenin ilk adımıdır çünkü Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, düzeneği bu sonucu üretir.`,E:`Yanlış; bu ifade Anogenital siğil sürecine ait bir özelliktir ve cybh etken sınıflaması düzeneğini tanımlamaz.`},bilgi:[1],benzer_cikmis:[`c44fed8f5ee8`,`f68e6427598f`]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k01-q07`,kazanim:1,zorluk:`orta`,soru:`CYBH etken sınıflaması düzeneğinin temel mekanizması aşağıdakilerden hangisinde doğru tanımlanmıştır?`,secenekler:{A:`Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi,`,B:`Reaktif artrit`,C:`Seftriakson 1x250 mg + azitromisin 1 g (standart)`,D:`H. ducreyi etken`,E:`Serum fizyolojik ile direkt bakıda epitel hücrelerine yapışmış, sınırları silinmiş`},dogru:`A`,aciklama:`Etkenler bakteri (N. Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter) belirlemenin ilk adımıdır. Bu ilişki Enfeksiyon Hastalıkları fizyolojisinin temel düzeneklerinden biridir: Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T doğrudan Etken grubunu bilmek tedavi ile korunma stratejisini doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt A seçeneğidir.`,sik_aciklamalari:{A:`Doğru; Etkenler bakteri (N. Bu mekanizma etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, sonucunu doğurur.`,B:`Yanlış; bu ifade Sistemik komplikasyonlar sürecine ait bir özelliktir ve cybh etken sınıflaması düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Gonore kombine tedavisi sürecine ait bir özelliktir ve cybh etken sınıflaması düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Şankroid klinik sürecine ait bir özelliktir ve cybh etken sınıflaması düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Clue cell (SF) sürecine ait bir özelliktir ve cybh etken sınıflaması düzeneğini tanımlamaz.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k01-q08`,kazanim:1,zorluk:`orta`,soru:`Cinsel yolla bulaşan enfeksiyon etkenleri taksonomik ve mikrobiyolojik yapılarına göre sınıflandırıldığında, aşağıdakilerden hangisi PROTOZOON (paraziter) bir patojendir?`,secenekler:{A:`Trichomonas vaginalis`,B:`Chlamydia trachomatis`,C:`Treponema pallidum`,D:`Ureaplasma urealyticum`,E:`Mycoplasma genitalium`},dogru:`A`,aciklama:`Trichomonas vaginalis tek hücreli, kamçılı (flagellat) bir protozoon parazittir ve cinsel yolla bulaşır. Chlamydia trachomatis, Treponema pallidum, Ureaplasma urealyticum ve Mycoplasma genitalium ise prokaryotik bakteriyel etkenlerdir.`,sik_aciklamalari:{A:`Doğrudur; Trichomonas vaginalis kamçılı bir protozoondur (parazit).`,B:`Chlamydia trachomatis zorunlu hücre içi bakteridir.`,C:`Treponema pallidum spiroket grubu bir bakteridir.`,D:`Ureaplasma urealyticum hücre duvarı olmayan bir bakteridir (mikoplazma ailesi).`,E:`Mycoplasma genitalium hücre duvarı bulunmayan bir bakteridir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k01-q09`,kazanim:1,zorluk:`orta`,soru:`Cinsel yolla bulaşan patojenlerden hangisi çift zincirli DNA genomuna sahip, latent kalabilen ve mukokutanöz veziküloülseratif lezyonlar oluşturan bir VİRÜSTÜR?`,secenekler:{A:`Herpes Simplex Virüs tip 2 (HSV-2)`,B:`Neisseria gonorrhoeae`,C:`Haemophilus ducreyi`,D:`Klebsiella granulomatis`,E:`Trichomonas vaginalis`},dogru:`A`,aciklama:`Herpes Simplex Virüs tip 2 (HSV-2), Herpesviridae ailesinde yer alan zarflı, çift zincirli lineer DNA virüsüdür; duyusal gangliyonlarda latent kalır ve veziküloülseratif genital lezyonlar yapar. Diğer seçeneklerden N. gonorrhoeae, H. ducreyi ve K. granulomatis bakteri; T. vaginalis ise parazittir.`,sik_aciklamalari:{A:`Doğrudur; HSV-2 latent kalabilen çift zincirli bir DNA virüsüdür.`,B:`Neisseria gonorrhoeae gram negatif diplokok bir bakteridir.`,C:`Haemophilus ducreyi gram negatif kokobasil bir bakteridir.`,D:`Klebsiella granulomatis gram negatif basil bir bakteridir (Donovanozis etkeni).`,E:`Trichomonas vaginalis kamçılı parazittir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k01-q10`,kazanim:1,zorluk:`zor`,soru:`Sert şankr (primer sifiliz) etkeni olan Treponema pallidum ile yumuşak şankr (şankroid) etkeni olan Haemophilus ducreyi mikrobiyolojik sınıflama ve morfolojik yapı bakımından aşağıdakilerin hangisinde doğru eşleştirilmiştir?`,secenekler:{A:`Treponema pallidum: Spiroket bakteri / Haemophilus ducreyi: Gram-negatif pleomorfik kokobasil bakteri`,B:`Treponema pallidum: Zarfı bulunmayan DNA virüsü / Haemophilus ducreyi: Sporlu anaerob basil`,C:`Treponema pallidum: Hücre duvarı bulunmayan mikoplazma / Haemophilus ducreyi: Kamçılı protozoon`,D:`Treponema pallidum: Zorunlu hücre içi riketsiya / Haemophilus ducreyi: Mayamsı mantar`,E:`Treponema pallidum: Gram-pozitif dallanan basil / Haemophilus ducreyi: Kapsüllü zarflı virüs`},dogru:`A`,aciklama:`Treponema pallidum ince, tirbüşon hareketli bir spiroket bakteridir; karanlık saha mikroskopisiyle görülebilir. Haemophilus ducreyi ise zor üreyen (fastidious), gram-negatif fakültatif anaerob pleomorfik kokobasildir. Her ikisi de bakteridir.`,sik_aciklamalari:{A:`Doğrudur; T. pallidum spiroket, H. ducreyi gram-negatif kokobasil bir bakteridir.`,B:`T. pallidum virüs değildir; H. ducreyi sporlu değildir.`,C:`T. pallidum spirokettir; H. ducreyi protozoon değildir.`,D:`T. pallidum serbest spirokettir (hücre içi zorunlu değildir); H. ducreyi mantar değildir.`,E:`T. pallidum gram-pozitif dallanan basil değildir; H. ducreyi virüs değildir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k01-q11`,kazanim:1,zorluk:`orta`,soru:`Aşağıdaki patojenlerden hangisi cinsel yolla bulaşan ektoparazitler (artropodlar) sınıfında yer alır?`,secenekler:{A:`Phthirus pubis (Kasık biti)`,B:`Gardnerella vaginalis`,C:`Candida albicans`,D:`Cytomegalovirus (CMV)`,E:`Enterobius vermicularis`},dogru:`A`,aciklama:`Phthirus pubis (kasık biti), cinsel temasla geçen bir ektoparazittir (böcek/artropod). Sarcoptes scabiei (uyuz) ile birlikte cinsel yolla bulaşan paraziter artropod enfestasyonlarını oluşturur.`,sik_aciklamalari:{A:`Doğrudur; Phthirus pubis kasık bölgesine yerleşen cinsel yolla bulaşan bir ektoparazittir.`,B:`Gardnerella vaginalis bakteriyel vaginozisle ilişkili bir bakteridir.`,C:`Candida albicans fırsatçı bir maya mantarıdır.`,D:`CMV Herpesviridae ailesinden bir virüstür.`,E:`Enterobius vermicularis kıl kurdudur (nematod), cinsel yolla bulaşmaz (fekal-oral).`},bilgi:[1],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k01-q12`,kazanim:1,zorluk:`zor`,soru:`Genital siğil (kondiloma aküminata) ve serviks karsinomu etyolojisinde rol oynayan İnsan Papilloma Virüsü (HPV) mikrobiyolojik açıdan hangi grupta yer alır?`,secenekler:{A:`Zarfsız, dairesel çift zincirli DNA virüsü`,B:`Zarflı, tek zincirli pozitif polariteli RNA virüsü`,C:`Zarflı, segmenter negatif polariteli RNA virüsü`,D:`Hücre duvarı peptidoglikan içermeyen gram negatif bakteri`,E:`Zorunlu hücre içi amip protozoonu`},dogru:`A`,aciklama:`Human Papillomavirus (HPV), Papillomaviridae ailesinde yer alan, ikozahedral simetrili, zarfsız ve dairesel çift zincirli DNA (dsDNA) genomuna sahip bir virüstür. Tip 6 ve 11 düşük riskli (kondilom), Tip 16 ve 18 ise yüksek onkojenik riskli tiplerdir.`,sik_aciklamalari:{A:`Doğrudur; HPV zarfsız, sirküler çift zincirli DNA virüsüdür.`,B:`Koronavirüs veya Flavivirüs özellikleridir.`,C:`İnfluenza virüsü özellikleridir.`,D:`Chlamydia veya Mycoplasma bakteri özellikleridir.`,E:`Entamoeba gibi amiplerin özelliğidir; HPV protozoon değildir.`},bilgi:[1],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:2,metin:`CYBH'de bulaş yollarını (cinsel yol, kan-kan ürünleri, anneden bebeğe geçiş) açıklayabilmek`,sorular:[{id:`k1-17-q04`,kazanim:2,zorluk:`kolay`,soru:`CYBH'de en sık bulaş yolu hangisidir?`,secenekler:{A:`Vektör ısırığı`,B:`Solunum yolu`,C:`Fekal-oral yol`,D:`Vajinal, anal veya oral mukoza yoluyla cinsel temas`,E:`Deri teması olmadan ortak eşya`},dogru:`D`,aciklama:`Bulaş genellikle mukozal cinsel temasla; ayrıca kan ürünleri ve anneden bebeğe olur.`,sik_aciklamalari:{A:`Vektörle bulaşmaz; bu nedenle doğru seçenek değildir.`,B:`Solunum yolu CYBH bulaş yolu değildir.`,C:`Fekal-oral yol temel yol değildir.`,D:`Doğru: en sık yoldur.`,E:`Temel bulaş yolu değildir.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-17-q05`,kazanim:2,zorluk:`orta`,soru:`Anneden bebeğe geçiş bilgisinin klinik önemi hangisidir?`,secenekler:{A:`Taramaya gerek olmaması`,B:`Hiçbir CYBH anneden bebeğe geçmez`,C:`Yalnızca doğumdan sonra önem taşır`,D:`HBV, HIV ve sifilis gibi enfeksiyonlarda perinatal profilaksi ve tarama gerektirmesi`,E:`Yalnızca trikomonasta geçerli olması`},dogru:`D`,aciklama:`Gebelikte, doğumda ve sonrasında anneden bebeğe bulaş olabilir.`,sik_aciklamalari:{A:`Tarama önemlidir; bu nedenle doğru seçenek değildir.`,B:`Birçok etken anneden bebeğe geçer.`,C:`Gebelik ve doğum sırasında da önemlidir.`,D:`Doğru: perinatal önlemler gereklidir.`,E:`Birçok etken için geçerlidir.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-17-q06`,kazanim:2,zorluk:`zor`,soru:`CYBH bulaş yolları ile ilgili hangisi yanlıştır?`,secenekler:{A:`Kan ve kan ürünleri ile bulaş olabilir`,B:`Gebelik sırasında anneden bebeğe bulaş olabilir`,C:`Doğum sırasında bulaş olabilir`,D:`Oral mukoza yoluyla bulaş olabilir`,E:`CYBH yalnızca vajinal ilişkiyle bulaşır; anal ve oral temas önemsizdir`},dogru:`E`,aciklama:`Bulaş vajinal, anal veya oral mukoza yoluyla olur.`,sik_aciklamalari:{A:`Doğru ifade; bu nedenle doğru seçenek değildir.`,B:`Doğru ifade; bu nedenle doğru seçenek değildir.`,C:`Doğru ifade; bu nedenle doğru seçenek değildir.`,D:`Doğru ifade; bu nedenle doğru seçenek değildir.`,E:`Yanlış ifade (aranan cevap): anal ve oral temas da bulaştırır.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k02-q04`,kazanim:2,zorluk:`orta`,soru:`34 yaşındaki bir hasta ayırıcı tanısı tartışılan ve öyküsü derinleştirilen bir hastada hekime başvuruyor. Değerlendirmede "Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya gebelik/doğum sırasında ve sonrasında anneden bebeğe olur." bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "CYBH'de bulaş yollarını (cinsel yol, kan-kan ürünleri, anneden bebeğe geçiş) açıklayabilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya… ilkesinin tam tersi geçerlidir ve Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi ve… gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Bulaş yolları olup "CYBH'de bulaş yollarını (cinsel yol, kan-kan ürünleri,…" ile ilişkisizdir`,C:`Bulgular "CYBH'de bulaş yollarını (cinsel yol, kan-kan ürünleri, anneden bebeğe…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,D:`Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya gebelik/doğum sırasında ve sonrasında anneden bebeğe olur. Bu nedenle Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi ve tarama gerektirir.`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Bulaş yolları" ile açıklanamaz`},dogru:`D`,aciklama:`Robbins/Harrison mantığıyla: Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya gebelik/doğum sırasında ve sonrasında anneden bebeğe olur. Doğrudan sonucu "Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi ve tarama gerektirir." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`,D:`Doğru; Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya gebelik/doğum…`,E:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k02-q05`,kazanim:2,zorluk:`zor`,soru:`Farklı bir hasta tanısal test sonucunun yorumlandığı bağımsız bir olguda ele alınıyor. Öyküde "Bulaş yolları" vurgulanıyor ve hekim "CYBH'de bulaş yollarını (cinsel yol, kan-kan ürünleri, anneden bebeğe geçiş) açıklayabilmek" kazanımındaki "Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya gebelik/doğum sırasında ve sonrasında anneden bebeğe olur." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi ve tarama gerektirir. hiçbir koşulda gözlenmez ve Bulaş yolları tek belirleyicidir`,B:`Bu süreçte "Bulaş yolları" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Benzer tabloların tamamı aynı nedene bağlıdır; "Bulaş yolları" ayırıcı tanıda gereksizdir`,D:`Bu olguda izlem gerekmez; "CYBH'de bulaş yollarını (cinsel yol, kan-kan ürünleri, anneden bebeğe…" yalnızca teorik bir bilgidir`,E:`Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi ve tarama gerektirir. Çünkü Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya gebelik/doğum…`},dogru:`E`,aciklama:`Guyton/Robbins bütünlüğünde: Bulaş genellikle vajinal, anal veya oral mukoza yoluyla; ayrıca kan ve kan ürünleriyle veya gebelik/doğum sırasında ve sonrasında anneden bebeğe olur. sonucu "Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi ve tarama gerektirir." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Bulaş yolları" bilgisiyle çelişir.`,E:`Doğru; Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi ve tarama gerektirir. Çünkü Bulaş…`},bilgi:[2],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k02-q06`,kazanim:2,zorluk:`orta`,soru:`Bulaş yolları: Bulaş genellikle vajinal, anal veya oral mukoza yoluyla. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`İnfertilite, ektopik gebelik ve kronik pelvik ağrı gibi sekellerle sonuçlanabilir`,B:`Bölgesel lenfadenopati ayırıcı tanısında düşünülmelidir`,C:`İlk atakta ciddi ülserasyon ve nörolojik tutulum olabilir`,D:`serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir`,E:`Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi`},dogru:`E`,aciklama:`Bulaş genellikle vajinal, anal veya oral mukoza yoluyla. Anneden bebeğe geçiş bilgisi (ör. Bu ilişki Enfeksiyon Hastalıkları fizyolojisinin temel düzeneklerinden biridir: Bulaş genellikle vajinal, anal veya oral mukoza doğrudan Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt E seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Pelvik inflamatuvar hastalık sürecine ait bir özelliktir ve bulaş yolları düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Lenfogranüloma venereum sürecine ait bir özelliktir ve bulaş yolları düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Genital herpes sürecine ait bir özelliktir ve bulaş yolları düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Vajinit ve servisit ayrımı sürecine ait bir özelliktir ve bulaş yolları düzeneğini tanımlamaz.`,E:`Doğru; Anneden bebeğe geçiş bilgisi (ör çünkü Bulaş genellikle vajinal, anal veya oral mukoza yoluyla düzeneği bu sonucu üretir.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k02-q07`,kazanim:2,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: CYBH etken sınıflaması mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Metronidazol 2 g tek doz`,B:`Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi,`,C:`Sefoksitin 4x2 g + doksisiklin 2x100 mg veya ampisilin/sulbaktam 4x3`,D:`Bulaş genellikle vajinal, anal veya oral mukoza yoluyla`,E:`Servisit veya üretritte Gram boyamada intraselüler gram negatif diplokokların görülmesi`},dogru:`B`,aciklama:`Enfeksiyon Hastalıkları düzeneğinde Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T bilinir. Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter) belirlemenin ilk adımıdır. Mekanizma bu sırayla işlediği için beklenen sonuç Etken grubunu bilmek tedavi ile korunma stratejisini olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt B seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Trikomoniyazis tedavisi sürecine ait bir özelliktir ve cybh etken sınıflaması düzeneğini tanımlamaz.`,B:`Doğru; Etkenler bakteri (N. Bu mekanizma etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, sonucunu doğurur.`,C:`Yanlış; bu ifade PİH intravenöz rejimleri sürecine ait bir özelliktir ve cybh etken sınıflaması düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Bulaş yolları sürecine ait bir özelliktir ve cybh etken sınıflaması düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Gram negatif diplokoklar sürecine ait bir özelliktir ve cybh etken sınıflaması düzeneğini tanımlamaz.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k02-q08`,kazanim:2,zorluk:`orta`,soru:`Cinsel yolla bulaşan enfeksiyonların geçiş yolları düşünüldüğünde; cinsel temasın yanı sıra parenteral (kan ve kan ürünleri) ve vertikal (anneden bebeğe) geçiş yollarının üçünü birden etkin şekilde kullanan klasik patojen grubu aşağıdakilerden hangisidir?`,secenekler:{A:`HIV, Hepatit B Virüsü (HBV) ve Treponema pallidum`,B:`Trichomonas vaginalis, Phthirus pubis ve Haemophilus ducreyi`,C:`Human Papilloma Virus (HPV tip 6 ve 11)`,D:`Ureaplasma urealyticum ve Mycoplasma hominis`,E:`Gardnerella vaginalis ve Mobiluncus`},dogru:`A`,aciklama:`HIV, Hepatit B virüsü ve Treponema pallidum (sifiliz); hem cinsel temasla (vajinal/anal/oral), hem kan ve kan ürünleri/enfekte iğnelerle (parenteral), hem de transplasental veya doğum eylemi sırasında anneden fetüse/bebeğe (vertikal) yüksek etkinlikle bulaşabilen sistemik patojenlerdir.`,sik_aciklamalari:{A:`Doğrudur; HIV, HBV ve Treponema pallidum cinsel, parenteral ve vertikal yolların tümüyle bulaşır.`,B:`Trichomonas ve kasık biti kandan kana (parenteral) bulaşmaz.`,C:`HPV kandan kana bulaşmaz, epitel temas yoluyla bulaşır.`,D:`Mikoplazmalar sistemik kan nakliyle bulaşan klasik patojenler değildir.`,E:`Gardnerella kandan kana geçiş göstermez.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k02-q09`,kazanim:2,zorluk:`zor`,soru:`Treponema pallidum'un gebelikte anneden bebeğe vertikal geçişi (konjenital sifiliz) ile ilgili aşağıdaki ifadelerden hangisi BİLİMSEL OLARAK DOĞRUDUR?`,secenekler:{A:`Spiroketler plasental bariyeri aşarak 9-10. gebelik haftasından itibaren fetüsü enfekte edebilir ve anne erken sifiliz (primer/sekonder) evresindeyse bulaş riski en yüksektir`,B:`Treponema pallidum sadece doğum kanalından geçerken bulaşır, asla plasentayı geçemez`,C:`Annede geç latent sifiliz olması fetüse bulaş riskini %100'e çıkarır`,D:`Konjenital sifiliz sadece anneye üçüncü trimesterde kan transfüzyonu yapılırsa ortaya çıkar`,E:`Spiroketlerin bebeğe geçişi sezaryen doğumla tamamen engellenebilir`},dogru:`A`,aciklama:`Treponema pallidum transplasental yolla geçer. Özellikle erken gebelik haftalarından (9-10. hafta) itibaren plasentayı aşabilir, ancak karakteristik fötal hasar immün yanıtın geliştiği 4. aydan sonra belirginleşir. Annede spiroketemi düzeyinin en yüksek olduğu primer ve sekonder sifiliz evrelerinde fetüse bulaş riski en yüksektir (%70-100).`,sik_aciklamalari:{A:`Doğrudur; plasental bariyeri aşar ve annenin erken evresinde bulaş riski en yüksektir.`,B:`Yanlıştır; transplasental geçiş ana bulaş yoludur.`,C:`Geç latent evrede spiroketemi azaldığı için bulaş riski düşer.`,D:`Cinsel yolla enfekte olmuş annelerden transplasental geçer, sadece transfüzyonla ilişkili değildir.`,E:`Transplasental geçtiği için sezaryen konjenital sifilizi önlemez.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k02-q10`,kazanim:2,zorluk:`orta`,soru:`Doğum sırasında enfekte annenin doğum kanalından geçerken bebeğe bulaşan ve yenidoğanda ilk 2-5 gün içinde hiperakut pürülan konjonktivite (oftalmiya neonatorum) yol açabilen patojen aşağıdakilerden hangisidir?`,secenekler:{A:`Neisseria gonorrhoeae`,B:`Treponema pallidum`,C:`Hepatit B Virüsü`,D:`Haemophilus ducreyi`,E:`Trichomonas vaginalis`},dogru:`A`,aciklama:`Neisseria gonorrhoeae, vajinal doğum sırasında yenidoğanın göz konjonktivalarına bulaşarak 2-5. günlerde hiperakut, bol cerahatli pürülan oftalmiya neonatoruma ve kornea perforasyonuna yol açabilir. Chlamydia trachomatis ise daha geç (5-14. günlerde) konjonktivit ve interstisyel pnömoni yapar.`,sik_aciklamalari:{A:`Doğrudur; gonokok doğum kanalından bulaşarak hiperakut pürülan neonatal konjonktivit yapar.`,B:`Treponema konjenital sistemik sifiliz yapar.`,C:`Hepatit B neonatal hepatit/kronik taşıyıcılık yapar, pürülan konjonktivit yapmaz.`,D:`H. ducreyi neonatal konjonktivit etkeni değildir.`,E:`T. vaginalis yenidoğanda nadiren geçici vajinit yapabilir, hiperakut konjonktivit yapmaz.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k02-q11`,kazanim:2,zorluk:`zor`,soru:`Genital ülseratif hastalıkların (sifiliz şankrı, şankroid, genital herpes) HIV bulaşı riskini 3 ila 10 kat artırmasının temel immünopatolojik nedeni nedir?`,secenekler:{A:`Mukozal epitel bariyerinin yıkılması ve ülser zemininde HIV için hedef olan aktive CD4+ T hücreleri ve dendritik hücrelerin yoğun şekilde toplanması`,B:`Ülser zeminindeki bakterilerin HIV gp120 proteinini doğrudan sentezlemesi`,C:`Herpes virüsünün HIV'in reverz transkriptaz enzimini yok etmesi`,D:`Şankroid toksinlerinin plazma hücrelerini tümüyle apoptoza uğratması`,E:`Genital ülserin CD8+ T lenfositlerin sayısını sıfırlaması`},dogru:`A`,aciklama:`Genital ülserler iki yönlü olarak HIV bulaşını kolaylaştırır: 1) Koruyucu keratinize ve mukozal bariyeri yıkarak virüsün girişini mekanik olarak kolaylaştırır; 2) Enflamatuar ülser tabanında HIV'in primer hedefi olan aktive CCR5+ CD4+ T lenfositler ve makrofajlar/dendritik hücreler yoğun şekilde toplanır; bu durum virüsün konağa girişini ve yayılımını katlar.`,sik_aciklamalari:{A:`Doğrudur; epitel defekti ve ülser tabanında toplanan aktive CD4+ T lenfositler HIV girişini kolaylaştırır.`,B:`Bakteriler viral yüzey glikoproteini (gp120) sentezlemez.`,C:`Herpes reverz transkriptazı yok etmez, tam tersine HIV ko-enfeksiyonunu kolaylaştırır.`,D:`Plazma hücre apoptozu primer mekanizma değildir.`,E:`CD8+ T hücre sayısı sıfırlanmaz.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k02-q12`,kazanim:2,zorluk:`orta`,soru:`Aşağıdaki cinsel temas biçimlerinden hangisi, mukozanın tek katlı prizmatik epitelle kaplı olması ve mikrotravmalara aşırı duyarlılığı nedeniyle HIV ve diğer CYBH'lerin bulaş riski açısından EN YÜKSEK riskli temas türüdür?`,secenekler:{A:`Alıcı anal ilişki (receptive anal intercourse)`,B:`Verici anal ilişki (insertive anal intercourse)`,C:`Alıcı vajinal ilişki`,D:`Verici vajinal ilişki`,E:`Oral-genital temas (fellatio)`},dogru:`A`,aciklama:`Rektal mukoza tek katlı silindirik epitelden oluşur, vajinadaki gibi çok katlı yassı koruyucu epitel içermez ve doğal kayganlaştırıcı salgısı yoktur. Sürtünme sırasında mikrotravmalar ve mukozal yırtıklar çok kolay oluşur. Bu nedenle alıcı anal cinsel ilişki (receptive anal intercourse) HIV ve diğer CYBH geçişinde en yüksek riske sahiptir.`,sik_aciklamalari:{A:`Doğrudur; rektal tek katlı epitel ve mikroyırtıklar nedeniyle alıcı anal ilişki en yüksek risklidir.`,B:`Verici anal ilişki alıcıya göre daha düşük bulaş riskine sahiptir.`,C:`Vajinal mukozanın çok katlı epitel yapısı anal mukozaya kıyasla daha dirençlidir.`,D:`Verici vajinal ilişkide penil ciltten bulaş riski alıcı vajinaya göre daha düşüktür.`,E:`Oral temas riski anal ve vajinal temasa kıyasla belirgin şekilde daha düşüktür.`},bilgi:[2],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:3,metin:`Vajinal akıntı, üretral akıntı ve genital ülser gibi başlıca klinik sendromları tanıyabilmek`,sorular:[{id:`k1-17-q07`,kazanim:3,zorluk:`kolay`,soru:`Aşağıdakilerden hangisi CYBH'nin başlıca klinik sendromlarından biri değildir?`,secenekler:{A:`Üretral akıntı`,B:`Vajinal akıntı`,C:`Akut otitis media`,D:`Genital ülser`,E:`Anorektal akıntı`},dogru:`C`,aciklama:`CYBH vajinal/üretral/anorektal akıntı, genital ülser ve sistemik belirtilerle kendini gösterir.`,sik_aciklamalari:{A:`Başlıca sendromdur; bu nedenle doğru seçenek değildir.`,B:`Başlıca sendromdur; bu nedenle doğru seçenek değildir.`,C:`Doğru: CYBH sendromu değildir.`,D:`Başlıca sendromdur; bu nedenle doğru seçenek değildir.`,E:`Başlıca sendromdur; bu nedenle doğru seçenek değildir.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-17-q08`,kazanim:3,zorluk:`orta`,soru:`CYBH'de sendromik yaklaşımın avantajı hangisidir?`,secenekler:{A:`Tanı testlerine hiç gerek kalmaması`,B:`Etken bilinmeden klinik sendroma göre tedaviye başlanabilmesi`,C:`Partner tedavisinin gereksizleşmesi`,D:`Antibiyotik direncini tamamen önlemesi`,E:`Yalnızca viral enfeksiyonlarda kullanılması`},dogru:`B`,aciklama:`Sendromik yaklaşım özellikle ülserli hastalıkta etken bilinmeden tedaviye başlamayı sağlar.`,sik_aciklamalari:{A:`Testler tanıyı doğrulamak için gereklidir.`,B:`Doğru: sendromik yaklaşımın avantajıdır.`,C:`Partner tedavisi gereklidir.`,D:`Direnci tamamen önlemez.`,E:`Bakteriyel enfeksiyonlarda da kullanılır.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-17-q09`,kazanim:3,zorluk:`zor`,soru:`Üretrit triadı hangisinde doğru verilmiştir?`,secenekler:{A:`Disparoni, postkoital kanama ve servikal eksuda`,B:`Ateş, döküntü ve artrit`,C:`Hematüri, kolik ve taş`,D:`Üretral irritasyon, kaşıntı ve dizüri`,E:`Vulvar kaşıntı, kokulu akıntı ve ödem`},dogru:`D`,aciklama:`Üretrit triadı üretral irritasyon, kaşıntı ve dizüridir; akut (gonokok) ve subakut/persistan (klamidya) ayrımı yapılır.`,sik_aciklamalari:{A:`Bu servisit bulgularıdır.`,B:`Bu sistemik/reaktif tablodur.`,C:`Bu ürolitiyazis tablosudur.`,D:`Doğru: üretrit triadıdır.`,E:`Bu vajinit bulgularıdır.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k03-q04`,kazanim:3,zorluk:`orta`,soru:`41 yaşındaki bir hasta tedavi yanıtı izlenen ve kliniği yeniden değerlendirilen bir olguda hekime başvuruyor. Değerlendirmede "Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal eksuda/kanama odakları görülür." bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "Vajinal akıntı, üretral akıntı ve genital ülser gibi başlıca klinik sendromları tanıyabilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve… ilkesinin tam tersi geçerlidir ve Hızlı, ucuz bir basamak testi olup BV tanısını destekler. gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Amin kokusu testi (KOH) olup "Vajinal akıntı, üretral akıntı ve genital ülser gibi…" ile ilişkisizdir`,C:`Bulgular "Vajinal akıntı, üretral akıntı ve genital ülser gibi başlıca klinik…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,D:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Vajinit ve servisit ayrımı" ile açıklanamaz`,E:`Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal eksuda/kanama odakları görülür. Bu nedenle Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir.`},dogru:`E`,aciklama:`Robbins/Harrison mantığıyla: Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal eksuda/kanama odakları görülür. Doğrudan sonucu "Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,E:`Doğru; Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal…`},bilgi:[4,5],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k03-q05`,kazanim:3,zorluk:`zor`,soru:`Farklı bir hasta aynı konunun farklı bir yönünü aydınlatmak için ele alınan ikinci bir olguda ele alınıyor. Öyküde "Amin kokusu testi (KOH)" vurgulanıyor ve hekim "Vajinal akıntı, üretral akıntı ve genital ülser gibi başlıca klinik sendromları tanıyabilmek" kazanımındaki "%10 KOH eklenmesiyle ortaya çıkan amin kokusu bakteriyel vajinozis için tipiktir." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Hızlı, ucuz bir basamak testi olup BV tanısını destekler. Çünkü %10 KOH eklenmesiyle ortaya çıkan amin kokusu bakteriyel vajinozis için tipiktir.`,B:`Hızlı, ucuz bir basamak testi olup BV tanısını destekler. hiçbir koşulda gözlenmez ve Vajinit ve servisit ayrımı tek belirleyicidir`,C:`Bu süreçte "Vajinit ve servisit ayrımı" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Amin kokusu testi (KOH)" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Vajinal akıntı, üretral akıntı ve genital ülser gibi başlıca klinik…" yalnızca teorik bir bilgidir`},dogru:`A`,aciklama:`Guyton/Robbins bütünlüğünde: %10 KOH eklenmesiyle ortaya çıkan amin kokusu bakteriyel vajinozis için tipiktir. sonucu "Hızlı, ucuz bir basamak testi olup BV tanısını destekler." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Doğru; Hızlı, ucuz bir basamak testi olup BV tanısını destekler. Çünkü %10 KOH eklenmesiyle ortaya çıkan amin kokusu…`,B:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`},bilgi:[4,5],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k03-q06`,kazanim:3,zorluk:`orta`,soru:`Klinik sendromlar: CYBH vajinal akıntı, üretral akıntı veya yanma, anorektal akıntı, genital ülser ve sistemik belirtilerle kendini gösterir. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Sendromik yaklaşım, etken bilinmeden tedaviye başlamayı (ör. ülserli hastalık) sağlar`,B:`NAAT yüksek duyarlılığıyla ilk seçenek`,C:`Klinik + laboratuvar + görüntüleme kombinasyonu ile tanı konur`,D:`Etkin tek doz tedavi ile lezyon hızla iyileşir`,E:`Tanı doğrulanınca metronidazol tedavisi ve partner tedavisi başlanır`},dogru:`A`,aciklama:`Enfeksiyon Hastalıkları düzeneğinde CYBH vajinal akıntı, üretral akıntı veya yanma, bilinir. Sendromik yaklaşım, etken bilinmeden tedaviye başlamayı (ör. Mekanizma bu sırayla işlediği için beklenen sonuç Sendromik yaklaşım, etken bilinmeden tedaviye başlamayı (ör olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt A seçeneğidir.`,sik_aciklamalari:{A:`Doğru; Sendromik yaklaşım, etken bilinmeden tedaviye başlamayı (ör çünkü CYBH vajinal akıntı, üretral akıntı veya yanma, anorektal düzeneği bu sonucu üretir.`,B:`Yanlış; bu ifade Tanı yöntemleri sürecine ait bir özelliktir ve klinik sendromlar düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade PİH klinik ve laboratuvar sürecine ait bir özelliktir ve klinik sendromlar düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Şankroid tedavisi sürecine ait bir özelliktir ve klinik sendromlar düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Trofozoit (SF) sürecine ait bir özelliktir ve klinik sendromlar düzeneğini tanımlamaz.`},bilgi:[3],benzer_cikmis:[`8dbc99d1f137`,`b2e6e5db71f9`]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k03-q07`,kazanim:3,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Üretral akıntı ve üretrit mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Penisilinaz üretimi (penisilin ve dar spektrumlu sefalosporin hidrolizi), PBP değişimi,`,B:`NAAT ile konur`,C:`Üretral irritasyon, kaşıntı ve dizüri üretrit triadını oluşturur`,D:`Vajinitte vulvar irritasyon ve eksuda ön planda`,E:`Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10-50`},dogru:`C`,aciklama:`Üretral irritasyon, kaşıntı ve dizüri üretrit triadını oluşturur. Yakınmaların süresine göre akut (gonokok) ve subakut/persistan (klamidya) üretrit ayırımı yapılır. Fizyopatolojik sıra bu yönde ilerlediğinden Üretral irritasyon, kaşıntı ve dizüri üretrit triadını varlığında Yakınmaların süresine göre akut (gonokok) ve subakut/persistan beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt C seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Gonokok direnç mekanizmaları sürecine ait bir özelliktir ve üretral akıntı ve üretrit düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Genital herpes tanısı sürecine ait bir özelliktir ve üretral akıntı ve üretrit düzeneğini tanımlamaz.`,C:`Doğru; Üretral irritasyon, kaşıntı ve dizüri üretrit triadını oluşturur. Bu mekanizma yakınmaların süresine göre akut (gonokok) ve subakut/persistan (klamidya) sonucunu doğurur.`,D:`Yanlış; bu ifade Vajinit ve servisit ayrımı sürecine ait bir özelliktir ve üretral akıntı ve üretrit düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Asemptomatik seyir oranları sürecine ait bir özelliktir ve üretral akıntı ve üretrit düzeneğini tanımlamaz.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k03-q08`,kazanim:3,zorluk:`orta`,soru:`Genital bölgede gelişen bir ülserin ağrısız, sert tabanlı, temiz sınırlı ve düzgün kenarlı olması (şankr) ile ağrısız bölgesel lenfadenopatinin eşlik etmesi aşağıdaki klinik sendromlardan hangisine işaret eder?`,secenekler:{A:`Primer Sifiliz`,B:`Şankroid (Ulkus molle)`,C:`Genital Herpes (HSV-2)`,D:`Granüloma İnguinale (Donovanozis)`,E:`Lenfogranüloma Venereum`},dogru:`A`,aciklama:`Primer sifiliz ülseri (sert şankr); tipik olarak tek, ağrısız, indüre (sert) tabanlı, düzgün sınırlı ve eksüdasız temiz tabanlıdır. Eşlik eden bölgesel (inguinal) lenfadenopati de ağrısız ve serttir.`,sik_aciklamalari:{A:`Doğrudur; ağrısız sert tabanlı şankr ve ağrısız LAP primer sifilizin karakteristiğidir.`,B:`Şankroid ülseri son derece ağrılı, yumuşak tabanlı, pürülan kirli tabanlı ve süpüratif ağrılı LAP (bubo) ile seyreder.`,C:`Genital herpes çok sayıda ağrılı vezikül ve erozyonla seyreder.`,D:`Donovanozis ağrısızdır ancak ülser granülasyon dokusuyla kabarık, et rengindedir ve LAP yapmaz (psödobubo yapar).`,E:`LGV'de primer lezyon geçici küçük bir papül/erozyondur; esas tablo ağrılı oluk bulgusu veren lenfadenopatidir.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k03-q09`,kazanim:3,zorluk:`orta`,soru:`24 yaşında bir erkek hasta idrar yaparken şiddetli yanma (disüri) ve penis ucundan kendiliğinden gelen bol miktarda sarı-yeşil, koyu kıvamlı pürülan akıntı şikayetiyle başvuruyor. Bu klinik tablo aşağıdaki sendromlardan hangisiyle tam uyumludur?`,secenekler:{A:`Akut Gonokokal Üretrit`,B:`Kronik Non-spesifik Prostatit`,C:`Primer Genital Herpes`,D:`Bakteriyel Vaginozis`,E:`Primer Sifiliz`},dogru:`A`,aciklama:`Akut gonokokal üretrit (Neisseria gonorrhoeae); 2-7 günlük kısa kuluçka süresinden sonra ani başlayan şiddetli disüri ve üretradan spontan olarak akan bol, koyu kıvamlı, sarı-yeşil pürülan akıntı ile karakterizedir. Nongonokokal üretritte akıntı daha az, müköz ve açık renklidir.`,sik_aciklamalari:{A:`Doğrudur; bol sarı-yeşil pürülan üretral akıntı ve disüri akut gonokokal üretrit için tipiktir.`,B:`Prostatitte pelvik ağrı ve dizüri ön plandadır, bol spontan pürülan akıntı beklenmez.`,C:`Genital herpes veziküloülseratif lezyon yapar, üretral pürülan akıntı yapmaz.`,D:`Bakteriyel vaginozis kadınlarda vajinal akıntı sendromudur.`,E:`Primer sifiliz ülserle seyreder, üretral pürülan akıntı oluşturmaz.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k03-q10`,kazanim:3,zorluk:`zor`,soru:`Vajinal akıntı sendromu ile başvuran bir kadında spekülüm muayenesinde; homojen, gri-beyaz, vajina duvarlarına yapışık akıntı, 'balık kokusu' (pozitif Whiff testi), vajinal pH > 4.5 ve mikroskopide 'clue cell' (ipucu hücresi) saptanıyor. Vajina duvarında enflamatuar eritem ve nötrofil lökosit artışı görülmüyor. Bu sendromik tanı aşağıdakilerden hangisidir?`,secenekler:{A:`Bakteriyel Vaginozis`,B:`Trikomanal Vajinit`,C:`Vulvovajinal Kandidiyazis`,D:`Mukopürülan Servisit`,E:`Atrofik Senil Vaginit`},dogru:`A`,aciklama:`Bakteriyel vaginozis (BV), laktobasillerin azalıp anaerobların (Gardnerella, Prevotella, Mobiluncus) aşırı çoğalmasıyla oluşan disrobiyozisdir. Enflamatuar bir yanıt olmadığı için vajinit değil vaginozis adını alır (nötrofil yoktur). Amsel kriterleri: Homojen gri-beyaz akıntı, pH > 4.5, pozitif Whiff testi (KOH ile balık kokusu) ve >%20 Clue cells (skuamöz hücre sınırlarını silen bakteriler).`,sik_aciklamalari:{A:`Doğrudur; Clue cell, pozitif Whiff testi, yüksek pH ve lökositozsuz akıntı bakteriyel vaginozisin tam tablosudur.`,B:`Trikomoniyaziste belirgin vajinit, çilek serviks ve bol lökosit izlenir.`,C:`Kandidiyaziste peynir kesiği akıntı, kaşıntı ve normal/asidik pH (<4.5) vardır, balık kokusu yoktur.`,D:`Mukopürülan servisitte endoservikal os'tan sarı pürülan eksüda gelir.`,E:`Atrofik vaginit östrojen eksikliğinde kuruluk ve mukozal incelme ile seyreder.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k03-q11`,kazanim:3,zorluk:`orta`,soru:`Jinekolojik muayenede; köpüklü, sarı-yeşil renkli, kötü kokulu bol vajinal akıntı ve servikste punktat kanama odakları ('çilek serviks' / kolpitis makularis) izlenen bir hastada en olası etken ve klinik sendrom aşağıdakilerden hangisidir?`,secenekler:{A:`Trichomonas vaginalis - Trikomanal vajinit`,B:`Candida albicans - Kandidal vulvovajinit`,C:`Gardnerella vaginalis - Bakteriyel vaginozis`,D:`Neisseria gonorrhoeae - Endometrit`,E:`Chlamydia trachomatis - Bartolin apsesi`},dogru:`A`,aciklama:`Köpüklü, bol, sarı-yeşil akıntı ve serviks epitelinde punktat hemoraji odakları ('çilek serviks' / strawberry cervix) Trichomonas vaginalis vajinitinin en karakteristik klinik bulgusudur.`,sik_aciklamalari:{A:`Doğrudur; sarı-yeşil köpüklü akıntı ve çilek serviks Trichomonas vaginalis vajinitine özgüdür.`,B:`Kandidiyaziste çilek serviks görülmez, peynirimsi beyaz plaklar ve şiddetli eritem/kaşıntı görülür.`,C:`Bakteriyel vaginoziste akıntı köpüklü veya sarı-yeşil değildir, çilek serviks oluşmaz.`,D:`Gonore endoservikal mukopürülan akıntı yapar, vajinal köpüklü akıntı ve çilek serviks yapmaz.`,E:`Klamidya asemptomatik veya müköz servisit yapar.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k03-q12`,kazanim:3,zorluk:`orta`,soru:`Genital bölgede eritemli bir taban üzerinde grup yapmış, içi berrak sıvı dolu küçük veziküller ve bu veziküllerin patlamasıyla açığa çıkan son derece ağrılı sığ ülserasyonlar aşağıdaki klinik tablolardan hangisini tanımlar?`,secenekler:{A:`Genital Herpes Simplex virüs enfeksiyonu`,B:`Primer Sifiliz şankrı`,C:`Kondiloma Aküminata`,D:`Molluscum Contagiosum`,E:`Lenfogranüloma Venereum`},dogru:`A`,aciklama:`Genital herpes (özellikle HSV-2), eritemli bir zemin üzerinde grup yapmış multipl ağrılı veziküllerle başlar. Veziküller hızla rüptüre olarak son derece hassas, ağrılı, zımba ile delinmiş gibi sığ ülserlere dönüşür ve kabuklanarak iyileşir.`,sik_aciklamalari:{A:`Doğrudur; grup yapmış ağrılı veziküller ve sığ ülserler genital herpesin tipik prezentasyonudur.`,B:`Sifiliz şankrı vezikülle başlamaz, tek ve ağrısız derin sert ülserdir.`,C:`Kondilomlar ağrısız siğilimsi vejetasyonlardır, vezikül oluşturmaz.`,D:`Molluscum ortası göbekli (umbilike) kubbe şeklinde papüller yapar.`,E:`LGV'de grup vezikül tablosu değil lenf bezi tutulumu ön plandadır.`},bilgi:[3],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:4,metin:`Vajinit ve servisit ayırıcı tanısında muayene bulgularını ve direkt mikroskopi (KOH, serum fizyolojik, Gram) sonuçlarını yorumlayabilmek`,sorular:[{id:`k1-17-q10`,kazanim:4,zorluk:`kolay`,soru:`%10 KOH eklenmesiyle ortaya çıkan amin (balık) kokusu hangi tanıyı destekler?`,secenekler:{A:`Kandidiyazis`,B:`Bakteriyel vajinozis`,C:`Gonore`,D:`Genital herpes`,E:`Şankroid`},dogru:`B`,aciklama:`Amin kokusu testi bakteriyel vajinozis için tipiktir; tanı Amsel kriterleriyle konur.`,sik_aciklamalari:{A:`Kandidada KOH ile maya hücreleri görülür, amin kokusu tipik değildir.`,B:`Doğru: BV'nin tipik bulgusudur.`,C:`Gonorede Gram negatif diplokok görülür.`,D:`Herpeste veziküler lezyonlar görülür.`,E:`Şankroid ülserli hastalıktır.`},bilgi:[5,6],benzer_cikmis:[]},{id:`k1-17-q11`,kazanim:4,zorluk:`orta`,soru:`Serum fizyolojik ile yapılan direkt bakıda hareketli trofozoitler görülmesi hangi tanıyı koydurur?`,secenekler:{A:`Kandidiyazis`,B:`Bakteriyel vajinozis`,C:`Trikomoniyazis`,D:`Klamidya servisiti`,E:`Sifilis`},dogru:`C`,aciklama:`Hareketli trofozoitler trikomoniyazis tanısını koydurur; metronidazol ve partner tedavisi başlanır.`,sik_aciklamalari:{A:`Kandidada maya hücreleri görülür.`,B:`BV'de clue cell görülür.`,C:`Doğru: trikomonas tanısıdır.`,D:`Klamidya direkt bakıda gösterilmez.`,E:`Sifilis direkt bakıda trofozoit vermez.`},bilgi:[7],benzer_cikmis:[`e28693ffa242`]},{id:`k1-17-q12`,kazanim:4,zorluk:`zor`,soru:`Vajinit ve servisit ayrımı ile ilgili hangisi doğrudur?`,secenekler:{A:`Vajinitte vulvar irritasyon görülmez`,B:`Vajinitte postkoital kanama tipiktir`,C:`Servisit hiçbir zaman PİH'e ilerlemez`,D:`Servisitte disparoni, postkoital kanama ve servikal eksuda/kanama odakları görülür; servikal akıntı üst genital enfeksiyon açısından daha risklidir`,E:`İkisi klinik olarak ayırt edilemez`},dogru:`D`,aciklama:`Vajinitte vulvar irritasyon ve eksuda; servisitte disparoni, postkoital kanama ve servikal eksuda ön plandadır.`,sik_aciklamalari:{A:`Vajinitte vulvar irritasyon ön plandadır.`,B:`Postkoital kanama servisite özgüdür.`,C:`Servisit PİH'e ilerleyebilir.`,D:`Doğru: ayırıcı bulgular doğrudur.`,E:`Klinik olarak ayırt edilebilir.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k04-q04`,kazanim:4,zorluk:`orta`,soru:`48 yaşındaki bir hasta tarama sırasında saptanan ve ileri incelemeye alınan bir kişide hekime başvuruyor. Değerlendirmede "Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal eksuda/kanama odakları görülür." bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "Vajinit ve servisit ayırıcı tanısında muayene bulgularını ve direkt mikroskopi (KOH, serum fizyolojik, Gram)…" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal eksuda/kanama odakları görülür. Bu nedenle Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir.`,B:`Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve… ilkesinin tam tersi geçerlidir ve Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha… gözlenmez`,C:`Bu tablodan sorumlu temel mekanizma Vajinit ve servisit ayrımı olup "Vajinit ve servisit ayırıcı tanısında muayene bulgularını…" ile ilişkisizdir`,D:`Bulgular "Vajinit ve servisit ayırıcı tanısında muayene bulgularını ve direkt…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Vajinit ve servisit ayrımı" ile açıklanamaz`},dogru:`A`,aciklama:`Robbins/Harrison mantığıyla: Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal eksuda/kanama odakları görülür. Doğrudan sonucu "Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Doğru; Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal…`,B:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k04-q05`,kazanim:4,zorluk:`zor`,soru:`Farklı bir hasta komplikasyon gelişen ve mekanizması sorgulanan başka bir hastada ele alınıyor. Öyküde "Vajinit ve servisit ayrımı" vurgulanıyor ve hekim "Vajinit ve servisit ayırıcı tanısında muayene bulgularını ve direkt mikroskopi (KOH, serum fizyolojik, Gram)…" kazanımındaki "Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal eksuda/kanama odakları görülür." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir. hiçbir koşulda gözlenmez ve Vajinit ve servisit ayrımı tek belirleyicidir`,B:`Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir. Çünkü Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal…`,C:`Bu süreçte "Vajinit ve servisit ayrımı" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Vajinit ve servisit ayrımı" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Vajinit ve servisit ayırıcı tanısında muayene bulgularını ve direkt…" yalnızca teorik bir bilgidir`},dogru:`B`,aciklama:`Guyton/Robbins bütünlüğünde: Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal eksuda/kanama odakları görülür. sonucu "Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,B:`Doğru; Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir. Çünkü Vajinitte vulvar…`,C:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k04-q06`,kazanim:4,zorluk:`orta`,soru:`Maya (KOH/Gram): %10 KOH veya Gram boyama ile tomurcuklanan maya hücreleri kandidiyazisi gösterir. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Gebede uygun ilaç seçimi fetal güvenliği korur`,B:`Kandidiyazis vajinitin non-CYBH nedenleri arasında olup tedavisi antifungal ilaçlardır`,C:`Etiyolojik ipucu (insertif anal seks, cerrahi öykü) tedaviyi yönlendirir`,D:`Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi`,E:`Nongonokokal üretrit/servisit tedavisi azitromisin veya doksisiklin içerir`},dogru:`B`,aciklama:`%10 KOH veya Gram boyama ile tomurcuklanan maya hücreleri kandidiyazisi gösterir. Kandidiyazis vajinitin non-CYBH nedenleri arasında olup tedavisi antifungal ilaçlardır. Fizyopatolojik sıra bu yönde ilerlediğinden %10 KOH veya Gram boyama ile tomurcuklanan varlığında Kandidiyazis vajinitin non-CYBH nedenleri arasında olup tedavisi beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt B seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Klamidya tedavisi sürecine ait bir özelliktir ve maya (koh/gram) düzeneğini tanımlamaz.`,B:`Doğru; Kandidiyazis vajinitin non-CYBH nedenleri arasında olup tedavisi antifungal ilaçlardır çünkü %10 KOH veya Gram boyama ile tomurcuklanan maya düzeneği bu sonucu üretir.`,C:`Yanlış; bu ifade Epididimoorşit tedavisi sürecine ait bir özelliktir ve maya (koh/gram) düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Bulaş yolları sürecine ait bir özelliktir ve maya (koh/gram) düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Nongonokokal enfeksiyon sürecine ait bir özelliktir ve maya (koh/gram) düzeneğini tanımlamaz.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k04-q07`,kazanim:4,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Clue cell (SF) mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Tuboovaryan abse, gebelik, bulantı-kusma ve ateş yüksekliği, oral tedaviye yanıtsızlık`,B:`Kondiloma akuminata`,C:`%10 KOH veya Gram boyama ile tomurcuklanan maya hücreleri kandidiyazisi`,D:`Serum fizyolojik ile direkt bakıda epitel hücrelerine yapışmış, sınırları silinmiş`,E:`Reaktif artrit`},dogru:`D`,aciklama:`Serum fizyolojik ile direkt bakıda epitel hücrelerine yapışmış, sınırları silinmiş hücreler (clue cell) bakteriyel vajinozisi gösterir. BV tanısı Amsel kriterleriyle konur. Bu ilişki Enfeksiyon Hastalıkları fizyolojisinin temel düzeneklerinden biridir: Serum fizyolojik ile direkt bakıda epitel hücrelerine doğrudan BV tanısı Amsel kriterleriyle konur doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt D seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade PİH yatış endikasyonları sürecine ait bir özelliktir ve clue cell (sf) düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Anogenital siğil sürecine ait bir özelliktir ve clue cell (sf) düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Maya (KOH/Gram) sürecine ait bir özelliktir ve clue cell (sf) düzeneğini tanımlamaz.`,D:`Doğru; Serum fizyolojik ile direkt bakıda epitel hücrelerine yapışmış, sınırları silinmiş hücreler (clue cell) bakteriyel vajinozisi gösterir. Bu mekanizma bv tanısı amsel kriterleriyle konur sonucunu doğurur.`,E:`Yanlış; bu ifade Sistemik komplikasyonlar sürecine ait bir özelliktir ve clue cell (sf) düzeneğini tanımlamaz.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k04-q08`,kazanim:4,zorluk:`orta`,soru:`Vajinal akıntı şikayeti olan bir kadından alınan sürüntüye %10 KOH (potasyum hidroksit) damlatıldığında balık kokusuna benzer amin kokusunun açığa çıkması (Whiff testi pozitifliği), aşağıdaki patolojilerden hangisinin tanısını güçlü şekilde destekler?`,secenekler:{A:`Bakteriyel vaginozis`,B:`Vulvovajinal kandidiyazis`,C:`Atrofik vaginit`,D:`Genital herpes`,E:`Primer sifiliz`},dogru:`A`,aciklama:`Whiff (koku) testi, vajinal akıntıya %10 KOH eklenmesiyle aminlerin (putresin, kadaverin, trimetilamin) alkali ortamda gaz haline geçip tipik 'bozulmuş balık kokusu' vermesidir. Bakteriyel vaginozis tanısında Amsel kriterlerinden biridir. (Trichomonas enfeksiyonunda da pozitifleşebilir ancak BV için tanısal kriterdir).`,sik_aciklamalari:{A:`Doğrudur; Whiff testi pozitifliği bakteriyel vaginozis için Amsel kriteridir.`,B:`Kandidiyaziste Whiff testi negatiftir; koku oluşmaz.`,C:`Atrofik vaginitte amin kokusu oluşmaz.`,D:`Genital herpes viral lezyondur, amin kokusu testiyle ilişkisizdir.`,E:`Primer sifiliz sert şankrla gider, Whiff testiyle tanı konmaz.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k04-q09`,kazanim:4,zorluk:`orta`,soru:`Taze serum fizyolojik (salin) ıslak preparat mikroskopisinde; skuamöz epitel hücre sınırlarının bakteriyel agregatlarla kaplanıp tamamen belirsizleştiği hücreler ('Clue cell' / İpucu hücresi) görülmüştür. Bu mikroskopik bulgu aşağıdaki durumlardan hangisi için patognomoniktir?`,secenekler:{A:`Bakteriyel vaginozis`,B:`Kandidal vajinit`,C:`Gonokokal servisit`,D:`Klamidya servisiti`,E:`Genital tüberküloz`},dogru:`A`,aciklama:`Clue cells (ipucu hücreleri), vajinal skuamöz epitel hücrelerinin yüzeyinin sayısız kokobasil (Gardnerella ve anaeroblar) ile kaplanması sonucu hücre sınırlarının 'buzlu cam' gibi görünmesi ve kaybolmasıdır. Bakteriyel vaginozisin en güvenilir tanısal göstergesidir.`,sik_aciklamalari:{A:`Doğrudur; clue cell bakteriyel vaginozisin mikroskopik en karakteristik bulgusudur.`,B:`Kandidiyaziste psödohif ve tomurcuklanan maya hücreleri görülür.`,C:`Gonokokal servisitte nötrofil içinde gram-negatif diplokoklar aranır.`,D:`Klamidya hücre içi bakteridir, direkt ışık mikroskopisinde epitel kaplaması yapmaz.`,E:`Genital tüberküloz kazeöz granülomlarla seyreder.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k04-q10`,kazanim:4,zorluk:`orta`,soru:`Yoğun vajinal kaşıntı ve beyaz, süt kesiği kıvamında akıntısı olan bir hastanın %10 KOH preparatında psödohifler ve tomurcuklanan maya hücreleri (blastosporlar) izleniyor. Vajinal pH ölçümü 4.0 (normal) saptanıyor. Bu hastada kesin tanı aşağıdakilerden hangisidir?`,secenekler:{A:`Vulvovajinal kandidiyazis`,B:`Bakteriyel vaginozis`,C:`Trikomanal vajinit`,D:`Gonokokal üretrit`,E:`Sitolitik vaginozis`},dogru:`A`,aciklama:`%10 KOH epitel hücrelerini eriterek mantar elemanlarının netleşmesini sağlar. Psödohif ve blastosporların görülmesi Candida albicans (veya diğer Candida türleri) enfeksiyonunu kanıtlar. Kandidiyaziste vajinal pH tipik olarak normal asidik aralıktadır (< 4.5); oysa BV ve Trichomonas'ta pH > 4.5'tir.`,sik_aciklamalari:{A:`Doğrudur; süt kesiği akıntı, normal pH (<4.5), KOH'ta psödohif ve maya kandidiyazis tanısı koydurur.`,B:`BV'de pH > 4.5'tir, clue cell vardır ve psödohif görülmez.`,C:`Trikomoniyaziste pH > 4.5'tir ve hareketli kamçılı trofozoitler izlenir.`,D:`Gonore endoservikal enfeksiyondur.`,E:`Sitolitik vaginoziste aşırı laktobasil ve çıplak nükleuslar izlenir, maya görülmez.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k04-q11`,kazanim:4,zorluk:`zor`,soru:`Taze vajinal salin preparatında lökositlerden biraz daha büyük, oval-armut biçimli ve karakteristik titreşimli/dönme hareketi (motilite) gösteren kamçılı mikroorganizmaların saptanması hangi patojenin kesin tanısını koydurur?`,secenekler:{A:`Trichomonas vaginalis`,B:`Gardnerella vaginalis`,C:`Candida glabrata`,D:`Treponema pallidum`,E:`Chlamydia trachomatis`},dogru:`A`,aciklama:`Trichomonas vaginalis trofozoit formunda tek hücreli kamçılı bir protozoondur. Taze salin preparatında mikroskop altında tipik dalgalı membran hareketi ve dönme-titreme hareketiyle (jerky motility) kolayca tanınır. Mikroorganizma kuruduğunda hareketi durduğu için taze preparat incelenmesi şarttır.`,sik_aciklamalari:{A:`Doğrudur; taze preparatta titreşimli kamçı hareketi Trichomonas vaginalis'e aittir.`,B:`Gardnerella hareketsiz bakteridir.`,C:`Candida glabrata hareketsiz mayadır (psödohif de oluşturmaz).`,D:`Treponema tirbüşon hareketli spirokettir, rutin salin ışık mikroskopisinde görülmez (karanlık saha gerekir).`,E:`Klamidya hücre içi bakteridir, ışık mikroskopisinde serbest motilite göstermez.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k04-q12`,kazanim:4,zorluk:`zor`,soru:`Servisit ile vajinitin ayırıcı tanısında spekülüm muayenesinde saptanan aşağıdaki bulgulardan hangisi lezyonun vajinada değil SERVİKSTE (servisit) olduğunu kesinleştirir?`,secenekler:{A:`Endoservikal os'tan sarı-yeşil mukopürülan eksüda gelişi ve pamuklu çubukla temas edildiğinde servikste kolay kanama (frajilite)`,B:`Vajina arka forniksinde gri homojen sıvı birikmesi`,C:`İntroitus çevresinde vulvar ödem ve fissürler`,D:`Vajina lateral duvarında beyaz süzme peynir plakları`,E:`Vajinal pH'nın 5.0 olarak ölçülmesi`},dogru:`A`,aciklama:`Servisit, serviksin kolumnar ve skuamokolumnar bileşkesinin enflamasyonudur (primer etkenler N. gonorrhoeae ve C. trachomatis). Tanı kriterleri: 1) Endoservikal kanaldan mukopürülan sarı eksüda gelişi; 2) Endoservikal sürüntü çubuğunun hafif temasıyla serviksin kolayca kanaması (frajilite / ektropion kanaması). Vajinit bulguları ise vajina duvarında ve fornikste toplanır.`,sik_aciklamalari:{A:`Doğrudur; endoservikal mukopürülan akıntı ve servikal frajilite servisitin kesin göstergeleridir.`,B:`Vajina forniksindeki birikim vajinit/vaginozis bulgusudur.`,C:`Vulvar ödem vulvovajinit bulgusudur.`,D:`Vajina duvarındaki peynirimsi plaklar vajinit (kandidiyazis) bulgusudur.`,E:`pH vajina ortamına aittir, servikal salgının pH'sı fizyolojik olarak zaten alkalendir.`},bilgi:[4],benzer_cikmis:[]}],ilgili_cikmis:[{id:`e28693ffa242`,soru:`Tıbbi Patoloji Tıbbi Patoloji Cinsel Yolla Bulaşan Hastalıklar Hangisi servikovajinal yayma sitolojisinde direkt olarak tesbit edilebilir?`,secenekler:{A:`Treponema pallidum`,B:`Neisseria gonorrhoeae`,C:`HerpesSimpleks`,D:`Trichomonas vaginalis`,E:`Chlamydiatrachomatis`},cevap:`B`}]},{no:5,metin:`Üretrit etkenlerini ve nongonokokal üretrit kavramını açıklayabilmek`,sorular:[{id:`k1-17-q13`,kazanim:5,zorluk:`kolay`,soru:`Gram boyamada gram negatif diplokok saptanmayan üretrit/servisitte en olası etken hangisidir?`,secenekler:{A:`Neisseria gonorrhoeae`,B:`Chlamydia trachomatis`,C:`Treponema pallidum`,D:`Candida albicans`,E:`HPV`},dogru:`B`,aciklama:`Nongonokokal üretrit/servisitte en olası etken C. trachomatis'tir; üretritte M. genitalium da etkendir.`,sik_aciklamalari:{A:`Gonokok Gram boyamada diplokok olarak görülür.`,B:`Doğru: nongonokokal enfeksiyonun en sık etkenidir.`,C:`Sifilis ülser yapar.`,D:`Kandida vajinit yapar.`,E:`HPV siğil yapar; bu nedenle doğru seçenek değildir.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-17-q14`,kazanim:5,zorluk:`orta`,soru:`Nongonokokal üretrit/servisitin tedavisinde kullanılan ilaçlar hangileridir?`,secenekler:{A:`Flukonazol`,B:`Penisilin G`,C:`Azitromisin veya doksisiklin`,D:`Asiklovir`,E:`Metronidazol tek başına`},dogru:`C`,aciklama:`Nongonokokal üretrit/servisit tedavisi azitromisin veya doksisiklin içerir.`,sik_aciklamalari:{A:`Flukonazol antifungaldir.`,B:`Penisilin sifilis tedavisidir.`,C:`Doğru: önerilen ilaçlardır.`,D:`Asiklovir antiviraldir.`,E:`Metronidazol trikomonas ve BV tedavisidir.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-17-q15`,kazanim:5,zorluk:`zor`,soru:`Üretrit etkenleri ve klinik seyir eşleştirmelerinden hangisi doğrudur?`,secenekler:{A:`Akut üretrit – klamidya; persistan üretrit – gonokok`,B:`Akut üretrit – gonokok; subakut/persistan üretrit – klamidya`,C:`T. vaginalis en sık üretrit etkenidir`,D:`M. genitalium üretrit yapmaz`,E:`Gram negatif diplokok klamidyayı gösterir`},dogru:`B`,aciklama:`Yakınma süresine göre akut (gonokok) ve subakut/persistan (klamidya) üretrit ayrımı yapılır.`,sik_aciklamalari:{A:`Eşleştirme terstir; bu nedenle doğru seçenek değildir.`,B:`Doğru: klinik ayrım doğrudur.`,C:`T. vaginalis nadiren üretrit yapar.`,D:`M. genitalium üretrit etkenidir.`,E:`Gram negatif diplokok gonokoku gösterir.`},bilgi:[10,11],benzer_cikmis:[`d3-b-032`]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k05-q04`,kazanim:5,zorluk:`orta`,soru:`55 yaşındaki bir hasta yıllardır süren yakınmalarla başvuran ve fizik muayenede tipik bulguları saptanan bir hastada hekime başvuruyor. Değerlendirmede "Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium, enterik bakteriler), virüs (HBV, HPV, CMV, EBV, Molluscum contagiosum,…" bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "Üretrit etkenlerini ve nongonokokal üretrit kavramını açıklayabilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M.… ilkesinin tam tersi geçerlidir ve Yakınmaların süresine göre akut (gonokok) ve subakut/persistan (klamidya)… gözlenmez`,B:`Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium, enterik bakteriler), virüs (HBV, HPV, CMV,… Bu nedenle Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter) belirlemenin ilk adımıdır.`,C:`Bu tablodan sorumlu temel mekanizma Üretral akıntı ve üretrit olup "Üretrit etkenlerini ve nongonokokal üretrit kavramını…" ile ilişkisizdir`,D:`Bulgular "Üretrit etkenlerini ve nongonokokal üretrit kavramını açıklayabilmek" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "CYBH etken sınıflaması" ile açıklanamaz`},dogru:`B`,aciklama:`Robbins/Harrison mantığıyla: Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium, enterik bakteriler), virüs (HBV, HPV, CMV, EBV,… Doğrudan sonucu "Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter) belirlemenin ilk adımıdır." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,B:`Doğru; Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium,…`,C:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`},bilgi:[1,9],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k05-q05`,kazanim:5,zorluk:`zor`,soru:`Farklı bir hasta tedavi seçeneğinin tartışıldığı farklı bir klinik senaryoda ele alınıyor. Öyküde "Üretral akıntı ve üretrit" vurgulanıyor ve hekim "Üretrit etkenlerini ve nongonokokal üretrit kavramını açıklayabilmek" kazanımındaki "Üretral irritasyon, kaşıntı ve dizüri üretrit triadını oluşturur; gram (-) diplokok gonoreyi gösterir, nadiren T. vaginalis üretrit yapar." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Yakınmaların süresine göre akut (gonokok) ve subakut/persistan (klamidya) üretrit ayırımı yapılır. hiçbir koşulda gözlenmez ve CYBH etken sınıflaması tek belirleyicidir`,B:`Bu süreçte "CYBH etken sınıflaması" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Yakınmaların süresine göre akut (gonokok) ve subakut/persistan (klamidya) üretrit ayırımı yapılır. Çünkü Üretral irritasyon, kaşıntı ve dizüri üretrit triadını oluşturur; gram (-) diplokok gonoreyi gösterir,…`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Üretral akıntı ve üretrit" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Üretrit etkenlerini ve nongonokokal üretrit kavramını açıklayabilmek" yalnızca teorik bir bilgidir`},dogru:`C`,aciklama:`Guyton/Robbins bütünlüğünde: Üretral irritasyon, kaşıntı ve dizüri üretrit triadını oluşturur; gram (-) diplokok gonoreyi gösterir, nadiren T. vaginalis üretrit yapar. sonucu "Yakınmaların süresine göre akut (gonokok) ve subakut/persistan (klamidya) üretrit ayırımı yapılır." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,C:`Doğru; Yakınmaların süresine göre akut (gonokok) ve subakut/persistan (klamidya) üretrit ayırımı yapılır. Çünkü…`,D:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`},bilgi:[10,11],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k05-q06`,kazanim:5,zorluk:`orta`,soru:`Nongonokokal enfeksiyon: Gram (-) diplokok saptanmayan servisit/üretritte en olası etken Chlamydia trachomatis'tir. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Alerji durumunda etkin alternatif şemalar mevcuttur`,B:`Ağrılı ülser + negatif sifilis ve HSV testleri şankroidi destekler`,C:`Nongonokokal üretrit/servisit tedavisi azitromisin veya doksisiklin içerir`,D:`Hızlı, ucuz bir basamak testi olup BV tanısını destekler`,E:`İnfertilite, ektopik gebelik ve kronik pelvik ağrı gibi sekellerle sonuçlanabilir`},dogru:`C`,aciklama:`Gram (-) diplokok saptanmayan servisit/üretritte en olası etken Chlamydia trachomatis'tir. Nongonokokal üretrit/servisit tedavisi azitromisin veya doksisiklin içerir. Bu ilişki Enfeksiyon Hastalıkları fizyolojisinin temel düzeneklerinden biridir: Gram (-) diplokok saptanmayan servisit/üretritte en olası doğrudan Nongonokokal üretrit/servisit tedavisi azitromisin veya doksisiklin içerir doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt C seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Gonore kombine tedavisi sürecine ait bir özelliktir ve nongonokokal enfeksiyon düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Şankroid klinik sürecine ait bir özelliktir ve nongonokokal enfeksiyon düzeneğini tanımlamaz.`,C:`Doğru; Nongonokokal üretrit/servisit tedavisi azitromisin veya doksisiklin içerir çünkü Gram (-) diplokok saptanmayan servisit/üretritte en olası etken düzeneği bu sonucu üretir.`,D:`Yanlış; bu ifade Amin kokusu testi (KOH) sürecine ait bir özelliktir ve nongonokokal enfeksiyon düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Pelvik inflamatuvar hastalık sürecine ait bir özelliktir ve nongonokokal enfeksiyon düzeneğini tanımlamaz.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k05-q07`,kazanim:5,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Üretral akıntı ve üretrit mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Ağrılı veziküler/ülseratif lezyonlar`,B:`CYBH vajinal akıntı, üretral akıntı veya yanma, anorektal akıntı, genital`,C:`Gram (-) diplokok saptanmayan servisit/üretritte en olası etken Chlamydia trachomatis'tir`,D:`Metronidazol 2 g tek doz`,E:`Üretral irritasyon, kaşıntı ve dizüri üretrit triadını oluşturur`},dogru:`E`,aciklama:`Enfeksiyon Hastalıkları düzeneğinde Üretral irritasyon, kaşıntı ve dizüri üretrit triadını bilinir. Yakınmaların süresine göre akut (gonokok) ve subakut/persistan (klamidya) üretrit ayırımı yapılır. Mekanizma bu sırayla işlediği için beklenen sonuç Yakınmaların süresine göre akut (gonokok) ve subakut/persistan olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt E seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Genital herpes sürecine ait bir özelliktir ve üretral akıntı ve üretrit düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Klinik sendromlar sürecine ait bir özelliktir ve üretral akıntı ve üretrit düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Nongonokokal enfeksiyon sürecine ait bir özelliktir ve üretral akıntı ve üretrit düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Trikomoniyazis tedavisi sürecine ait bir özelliktir ve üretral akıntı ve üretrit düzeneğini tanımlamaz.`,E:`Doğru; Üretral irritasyon, kaşıntı ve dizüri üretrit triadını oluşturur. Bu mekanizma yakınmaların süresine göre akut (gonokok) ve subakut/persistan (klamidya) sonucunu doğurur.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k05-q08`,kazanim:5,zorluk:`orta`,soru:`Erkeklerde gelişen Nongonokokal Üretrit (NGÜ) tablolarının en sık bakteriyel etkeni aşağıdakilerden hangisidir?`,secenekler:{A:`Chlamydia trachomatis (özellikle D-K serovarları)`,B:`Neisseria meningitidis`,C:`Treponema pallidum`,D:`Haemophilus ducreyi`,E:`Klebsiella granulomatis`},dogru:`A`,aciklama:`Nongonokokal üretrit (NGÜ), gonokok dışı etkenlerin yol açtığı üretrittir. NGÜ vakalarının %20-50'sinden sorumlu en yaygın etken Chlamydia trachomatis (D-K serotipleri)'dir. İkinci en sık etken Mycoplasma genitalium'dur.`,sik_aciklamalari:{A:`Doğrudur; C. trachomatis nongonokokal üretritin en sık (%20-50) etkenidir.`,B:`N. meningitidis nadir üretrit etkenidir.`,C:`T. pallidum şankr yapar, klasik üretrit etkeni değildir.`,D:`H. ducreyi şankroid (ağrılı ülser) yapar.`,E:`K. granulomatis donovanozis yapar.`},bilgi:[5],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k05-q09`,kazanim:5,zorluk:`zor`,soru:`Doksisiklin tedavisine dirençli nongonokokal üretrit olgularında giderek artan sıklıkta saptanan, hücre duvarı bulunmayan ve makrolid direnci (23S rRNA mutasyonları) yüksek olan bakteriyel etken aşağıdakilerden hangisidir?`,secenekler:{A:`Mycoplasma genitalium`,B:`Escherichia coli`,C:`Staphylococcus saprophyticus`,D:`Enterococcus faecalis`,E:`Pseudomonas aeruginosa`},dogru:`A`,aciklama:`Mycoplasma genitalium, NGÜ'nün Chlamydia'dan sonraki en önemli ikinci etkenidir (%15-25). Hücre duvarı olmadığı için beta-laktamlar etkisizdir; doksisikline yanıtı düşüktür (%30-40) ve makrolidlere (azitromisin) karşı hızla 23S rRNA nokta mutasyonlarıyla direnç geliştirmektedir (dirençli vakalarda moksifloksasin kullanılır).`,sik_aciklamalari:{A:`Doğrudur; M. genitalium doksisiklin direnci ve makrolid mutasyonlarıyla NGÜ tedavisinde kritik bir etkendir.`,B:`E. coli klasik üriner sistem enfeksiyonu yapar, CYBH üretriti değildir.`,C:`S. saprophyticus genç kadınlarda sistit etkenidir.`,D:`Enterokoklar hastane kökenli İYE etkenidir.`,E:`Pseudomonas üretrit etkeni değildir.`},bilgi:[5],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k05-q10`,kazanim:5,zorluk:`orta`,soru:`Gonokokal üretrit (GÜ) ile Nongonokokal üretrit (NGÜ) klinik özellikleri bakımından karşılaştırıldığında aşağıdakilerden hangisi DOĞRUDUR?`,secenekler:{A:`Gonokokal üretritte inkübasyon süresi daha kısa (2-7 gün) ve akıntı bol sarı pürülandır; NGÜ'de ise inkübasyon daha uzun (1-3 hafta) ve akıntı daha az, mükoid/serözdür`,B:`NGÜ'de akıntı daima bol yeşil ve kendiliğinden fışkırır tarzdadır`,C:`Gonokokal üretritte inkübasyon süresi 30 gündür`,D:`NGÜ hastalarında asla disüri görülmez`,E:`Gonokokal üretrit etkeni hücre duvarı bulunmayan bir mikoplazmadır`},dogru:`A`,aciklama:`Gonorede semptomlar ani ve gürültülüdür: İnkübasyon 2-7 gün, akıntı bol, kıvamlı ve pürülandır. Nongonokokal üretritte (klamidya/mikoplazma) ise inkübasyon uzundur (7-21 gün), semptomlar daha siliktir, akıntı az miktarda, berrak, müköz veya serözdür; sıklıkla sadece sabahları üretral kuruluk veya iç çamaşırında lekelenme şeklinde fark edilir.`,sik_aciklamalari:{A:`Doğrudur; gonore kısa inkübasyon ve bol pürülan akıntı; NGÜ uzun inkübasyon ve az mükoid akıntı ile seyreder.`,B:`Bol fışkıran pürülan akıntı gonoreye özgüdür.`,C:`Gonore inkübasyonu kısadır (2-7 gün).`,D:`NGÜ'de hafif/orta derecede disüri sık görülür.`,E:`Gonore etkeni gram-negatif diplokoktur (peptidoglikan içerir).`},bilgi:[5],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k05-q11`,kazanim:5,zorluk:`orta`,soru:`Erkek hastada üretral akıntıdan yapılan Gram boyamada lökositler görülmüş ancak polimorfnükleer lökositlerin İÇİNDE gram-negatif diplokok SAPTANAMAMIŞTIR. Bu laboratuvar bulgusu aşağıdaki tanılardan hangisini doğrudan koydurur?`,secenekler:{A:`Nongonokokal üretrit (NGÜ)`,B:`Gonokokal üretrit`,C:`Primer sifiliz`,D:`Lenfogranüloma venereum`,E:`Kondiloma aküminata`},dogru:`A`,aciklama:`Üretral yaymada her sahada ≥ 5 (veya ≥ 2) nötrofil lökosit saptanması üretriti kanıtlar. Eğer lökositlerin içinde hücre içi gram-negatif kahve çekirdeği şeklinde diplokoklar (intrasellüler GND) görülmezse tablo mikrobiyolojik olarak 'Nongonokokal Üretrit' olarak tanımlanır.`,sik_aciklamalari:{A:`Doğrudur; lökosit varlığı + intrasellüler diplokok yokluğu = Nongonokokal üretrit.`,B:`Gonokokal üretritte lökosit içi gram-negatif diplokoklar gösterilir.`,C:`Primer sifiliz ülseratif lezyondur, Gram boyamayla üretrit tanısı konmaz.`,D:`LGV lenf bezi tutulumu yapar.`,E:`Kondilom HPV kaynaklı siğildir.`},bilgi:[5],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k05-q12`,kazanim:5,zorluk:`zor`,soru:`Nongonokokal üretritin nadir görülen ve cinsel temas yoluyla bulaşan paraziter ve viral etkenleri aşağıdakilerin hangisinde doğru verilmiştir?`,secenekler:{A:`Trichomonas vaginalis ve Herpes Simplex Virüs (HSV)`,B:`Giardia lamblia ve Rotavirüs`,C:`Entamoeba histolytica ve Hepatit A Virüsü`,D:`Ascaris lumbricoides ve Kuduz Virüsü`,E:`Toxoplasma gondii ve İnfluenza Virüsü`},dogru:`A`,aciklama:`Nongonokokal üretrit olgularının büyük kısmı C. trachomatis ve M. genitalium kaynaklıdır. Geriye kalan %5-10'luk kısımda ise paraziter etken olarak Trichomonas vaginalis (özellikle erkeklerde asemptomatik/üretrit), viral etken olarak ise Herpes Simplex Virüs (HSV-1 veya HSV-2) ve Adenovirüs rol oynar.`,sik_aciklamalari:{A:`Doğrudur; T. vaginalis ve HSV nongonokokal üretritin paraziter ve viral etkenleridir.`,B:`Giardia ve Rotavirüs gastrointestinal patojenlerdir.`,C:`Amipli dizanteri ve fekal-oral bulaşan etkenlerdir.`,D:`Ascaris bağırsak solucanı, Kuduz zoonotik virüstür.`,E:`Toxoplasma ve İnfluenza üretrit etkeni değildir.`},bilgi:[5],benzer_cikmis:[]}],ilgili_cikmis:[{id:`d3-b-032`,soru:`Otuz beş yaşında erkek hasta, 1 haftadır devam eden penis ucundan sarı renkli akıntı ve idrarda yanma şikâyeti ile polikliniğe başvuruyor. Hastanın üretral akıntı örneğinin Gram boyamasında her sahada 3 tane PMNL ve bu lökositlerin içinde gram negatif diplokoklar görülüyor. Bu olguda düşünülecek en olası klinik tablo ve etken mikroorganizma aşağıdakilerden hangisidir?`,secenekler:{A:`Epididimoorşit – Streptococcus pneumoniae`,B:`Prostatit – Chlamydia trachomatis`,C:`Üretrit – Neisseria gonorrhoeae`,D:`Epididimoorşit – Mycoplasma genitalium`,E:`Üretrit – Treponema pallidum`},cevap:`C`}]},{no:6,metin:`Ürogenital enfeksiyonlarda asemptomatik seyir oranlarını cinsiyetlere göre karşılaştırabilmek`,sorular:[{id:`k1-17-q16`,kazanim:6,zorluk:`kolay`,soru:`Kadınlarda asemptomatik seyretme oranı en yüksek olan ürogenital enfeksiyon hangisidir?`,secenekler:{A:`Genital herpes`,B:`Gonore`,C:`Trikomoniyazis`,D:`Klamidya (%90'a varan)`,E:`Şankroid`},dogru:`D`,aciklama:`Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10–50 oranında asemptomatiktir.`,sik_aciklamalari:{A:`Bu derste oran verilmemiştir.`,B:`%50'ye varan oranda asemptomatiktir.`,C:`%10–50 oranında asemptomatiktir.`,D:`Doğru: en yüksek asemptomatik oran klamidyadadır.`,E:`Ağrılı ülserle seyreder.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-17-q17`,kazanim:6,zorluk:`orta`,soru:`Erkeklerde klamidya enfeksiyonunun asemptomatik seyir oranı yaklaşık ne kadardır?`,secenekler:{A:`%100`,B:`%1`,C:`%50'ye varan`,D:`%5`,E:`Erkeklerde hiç asemptomatik değildir`},dogru:`C`,aciklama:`Erkekte klamidya %50'ye varan oranda asemptomatiktir.`,sik_aciklamalari:{A:`Tüm olgular asemptomatik değildir.`,B:`Çok düşüktür; bu nedenle doğru seçenek değildir.`,C:`Doğru: verilen orandır.`,D:`Gerçek oranın altındadır.`,E:`Erkekte de asemptomatik seyir sıktır.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-17-q18`,kazanim:6,zorluk:`zor`,soru:`Asemptomatik CYBH'lerin halk sağlığı açısından önemi hangisidir?`,secenekler:{A:`Yalnızca erkeklerde görülmeleri`,B:`Hiçbir komplikasyon yapmamaları`,C:`Kendiliğinden kalıcı bağışıklık oluşturmaları`,D:`Tarama gerektirmemeleri`,E:`Bulaşı sürdürmeleri ve PİH gibi komplikasyonlara yol açmaları nedeniyle taramanın önemli olması`},dogru:`E`,aciklama:`Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi komplikasyonlara yol açar.`,sik_aciklamalari:{A:`Her iki cinsiyette görülür.`,B:`Komplikasyon yapabilirler.`,C:`Kalıcı bağışıklık oluşmaz.`,D:`Tarama önemlidir; bu nedenle doğru seçenek değildir.`,E:`Doğru: taramanın gerekçesidir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k06-q04`,kazanim:6,zorluk:`orta`,soru:`62 yaşındaki bir hasta akut başvuru yapan ve laboratuvar-görüntüleme bulguları birlikte değerlendirilen bir olguda hekime başvuruyor. Değerlendirmede "Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10-50; erkekte klamidya %50'ye varan oranda asemptomatiktir." bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "Ürogenital enfeksiyonlarda asemptomatik seyir oranlarını cinsiyetlere göre karşılaştırabilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10-50; erkekte klamidya %50'ye… ilkesinin tam tersi geçerlidir ve Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi komplikasyonlara yol açar;… gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Asemptomatik seyir oranları olup "Ürogenital enfeksiyonlarda asemptomatik seyir oranlarını…" ile ilişkisizdir`,C:`Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10-50; erkekte klamidya %50'ye varan oranda asemptomatiktir. Bu nedenle Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi komplikasyonlara yol açar; tarama önemlidir.`,D:`Bulgular "Ürogenital enfeksiyonlarda asemptomatik seyir oranlarını cinsiyetlere…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Asemptomatik seyir oranları" ile açıklanamaz`},dogru:`C`,aciklama:`Robbins/Harrison mantığıyla: Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10-50; erkekte klamidya %50'ye varan oranda asemptomatiktir. Doğrudan sonucu "Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi komplikasyonlara yol açar; tarama önemlidir." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Asemptomatik seyir oranları" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Asemptomatik seyir oranları" bilgisiyle çelişir.`,C:`Doğru; Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10-50; erkekte klamidya %50'ye varan…`,D:`Yanlış; ders paketindeki "Asemptomatik seyir oranları" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Asemptomatik seyir oranları" bilgisiyle çelişir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k06-q05`,kazanim:6,zorluk:`zor`,soru:`Farklı bir hasta hastalığın seyri ve prognozunun değerlendirildiği ayrı bir vakada ele alınıyor. Öyküde "Asemptomatik seyir oranları" vurgulanıyor ve hekim "Ürogenital enfeksiyonlarda asemptomatik seyir oranlarını cinsiyetlere göre karşılaştırabilmek" kazanımındaki "Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10-50; erkekte klamidya %50'ye varan oranda asemptomatiktir." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi komplikasyonlara yol açar; tarama önemlidir. hiçbir koşulda gözlenmez ve Asemptomatik seyir oranları tek belirleyicidir`,B:`Bu süreçte "Asemptomatik seyir oranları" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Benzer tabloların tamamı aynı nedene bağlıdır; "Asemptomatik seyir oranları" ayırıcı tanıda gereksizdir`,D:`Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi komplikasyonlara yol açar; tarama önemlidir. Çünkü Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10-50; erkekte klamidya %50'ye varan…`,E:`Bu olguda izlem gerekmez; "Ürogenital enfeksiyonlarda asemptomatik seyir oranlarını cinsiyetlere…" yalnızca teorik bir bilgidir`},dogru:`D`,aciklama:`Guyton/Robbins bütünlüğünde: Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10-50; erkekte klamidya %50'ye varan oranda asemptomatiktir. sonucu "Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi komplikasyonlara yol açar; tarama önemlidir." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Asemptomatik seyir oranları" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Asemptomatik seyir oranları" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Asemptomatik seyir oranları" bilgisiyle çelişir.`,D:`Doğru; Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi komplikasyonlara yol açar; tarama önemlidir. Çünkü Kadında…`,E:`Yanlış; ders paketindeki "Asemptomatik seyir oranları" bilgisiyle çelişir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k06-q06`,kazanim:6,zorluk:`orta`,soru:`Asemptomatik seyir oranları: Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10-50. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Uygun süre tedavi ile komplikasyon (abse, infertilite) riski azalır`,B:`Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter)`,C:`Kandidiyazis vajinitin non-CYBH nedenleri arasında olup tedavisi antifungal ilaçlardır`,D:`Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi komplikasyonlara yol açar`,E:`NAAT yüksek duyarlılığıyla ilk seçenek`},dogru:`D`,aciklama:`Enfeksiyon Hastalıkları düzeneğinde Kadında klamidya %90'a varan, gonore %50'ye varan, bilinir. Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi komplikasyonlara yol açar. Mekanizma bu sırayla işlediği için beklenen sonuç Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt D seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade PİH intravenöz rejimleri sürecine ait bir özelliktir ve asemptomatik seyir oranları düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade CYBH etken sınıflaması sürecine ait bir özelliktir ve asemptomatik seyir oranları düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Maya (KOH/Gram) sürecine ait bir özelliktir ve asemptomatik seyir oranları düzeneğini tanımlamaz.`,D:`Doğru; Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi komplikasyonlara yol açar çünkü Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis düzeneği bu sonucu üretir.`,E:`Yanlış; bu ifade Tanı yöntemleri sürecine ait bir özelliktir ve asemptomatik seyir oranları düzeneğini tanımlamaz.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k06-q07`,kazanim:6,zorluk:`orta`,soru:`Asemptomatik seyir oranları düzeneğinin temel mekanizması aşağıdakilerden hangisinde doğru tanımlanmıştır?`,secenekler:{A:`Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10-50`,B:`Azitromisin 1 g tek doz veya seftriakson 1x250 mg tek`,C:`Serum fizyolojik ile direkt bakıda epitel hücrelerine yapışmış, sınırları silinmiş`,D:`Skrotal ağrı-ödem ve ağrılı ejakülasyon ile seyreder`,E:`Penisilinaz üretimi (penisilin ve dar spektrumlu sefalosporin hidrolizi), PBP değişimi,`},dogru:`A`,aciklama:`Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10-50. Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi komplikasyonlara yol açar. Fizyopatolojik sıra bu yönde ilerlediğinden Kadında klamidya %90'a varan, gonore %50'ye varan, varlığında Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt A seçeneğidir.`,sik_aciklamalari:{A:`Doğru; Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10-50. Bu mekanizma sessiz enfeksiyonlar bulaşı sürdürür ve pi̇h gibi komplikasyonlara sonucunu doğurur.`,B:`Yanlış; bu ifade Şankroid tedavisi sürecine ait bir özelliktir ve asemptomatik seyir oranları düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Clue cell (SF) sürecine ait bir özelliktir ve asemptomatik seyir oranları düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Epididimit/prostatit sürecine ait bir özelliktir ve asemptomatik seyir oranları düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Gonokok direnç mekanizmaları sürecine ait bir özelliktir ve asemptomatik seyir oranları düzeneğini tanımlamaz.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k06-q08`,kazanim:6,zorluk:`orta`,soru:`Chlamydia trachomatis ürogenital enfeksiyonlarının klinik seyri cinsiyetler arasında karşılaştırıldığında, asemptomatik kalma oranları ile ilgili aşağıdaki ifadelerden hangisi DOĞRUDUR?`,secenekler:{A:`Kadınların yaklaşık %70-80'inde, erkeklerin ise yaklaşık %50'sinde asemptomatik seyreder`,B:`Erkeklerin %99'unda asemptomatik seyrederken kadınların tamamında şiddetli ağrı yapar`,C:`Hem erkeklerde hem kadınlarda %100 oranında şiddetli pürülan akıntıya yol açar`,D:`Kadınlarda asemptomatik form hiç görülmez, daima peritonit yapar`,E:`Erkeklerde asemptomatik klamidya enfeksiyonu tıbben imkansızdır`},dogru:`A`,aciklama:`Chlamydia trachomatis bu özelliği nedeniyle 'sessiz enfeksiyon' olarak bilinir. Enfekte kadınların yaklaşık %70-85'i tamamen asemptomatiktir; erkeklerin de yaklaşık %50'si asemptomatik seyreder. Bu durum fark edilmeden bulaşmanın ve kadınlarda sessizce pelvik inflamatuvar hastalık (PİH) ile infertilite gelişmesinin ana nedenidir.`,sik_aciklamalari:{A:`Doğrudur; kadınların %70-80'i, erkeklerin yaklaşık %50'si asemptomatiktir.`,B:`Erkeklerde %99 asemptomatik değildir, %50 civarındadır.`,C:`Chlamydia asemptomatik seyriyle ünlüdür, her zaman pürülan akıntı yapmaz.`,D:`Kadınlarda çoğunlukla asemptomatiktir.`,E:`Erkeklerde asemptomatik klamidya oldukça yaygındır.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k06-q09`,kazanim:6,zorluk:`orta`,soru:`Neisseria gonorrhoeae enfeksiyonunda erkek ve kadınların semptomatik olma sıklığı karşılaştırıldığında aşağıdakilerden hangisi DOĞRUDUR?`,secenekler:{A:`Erkeklerin %90-95'i akut semptomatiktir (şiddetli akıntı/disüri); kadınların ise %50'den fazlası asemptomatik veya silik semptomludur`,B:`Erkeklerin %95'i tamamen asemptomatiktir`,C:`Kadınların %100'ü semptomatiktir, erkekler ise sadece taşıyıcıdır`,D:`Her iki cinste de asemptomatik seyir oranı %1'in altındadır`,E:`Gonore kadınlarda hiçbir zaman asemptomatik kalamaz`},dogru:`A`,aciklama:`Gonore erkeklerde son derece belirgin ve gürültülüdür; enfekte erkeklerin %90-95'inde şiddetli disüri ve pürülan akıntı gelişir, hızla doktora başvururlar. Buna karşın kadınlarda primer tutulum yeri olan endoservikal kanal duyusal innervasyonu az olduğu için kadınların en az %50'sinde enfeksiyon asemptomatik veya silik semptomlu kalır ve sessiz rezervuar oluşturur.`,sik_aciklamalari:{A:`Doğrudur; erkeklerin %90-95'i semptomatik iken kadınların %50'sinden fazlası asemptomatiktir.`,B:`Erkekler çoğunlukla semptomatiktir (%90-95).`,C:`Tam tersine erkekler semptomatik, kadınlar sıklıkla asemptomatiktir.`,D:`Kadınlarda asemptomatik oran %50'nin üzerindedir.`,E:`Kadınlarda asemptomatik seyir çok sıktır.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k06-q10`,kazanim:6,zorluk:`zor`,soru:`Kadınlarda klamidya ve gonore enfeksiyonlarının yüksek oranda asemptomatik seyretmesinin uzun vadeli en yıkıcı klinik sonucu aşağıdakilerden hangisidir?`,secenekler:{A:`Fark edilmeyen asendan enfeksiyon sonucu sessiz pelvik inflamatuvar hastalık (PİH), tubal hasar, ektopik gebelik ve tubal faktör infertilitesi gelişimi`,B:`Böbreklerde glomerülonefrit ve diyaliz ihtiyacı`,C:`Kemik iliğinde aplazi ve pansitopeni`,D:`Karaciğerde dev adenom gelişimi`,E:`Akut sol ventrikül hipertrofisi`},dogru:`A`,aciklama:`Asemptomatik kalan servikal klamidya ve gonokok enfeksiyonları tedavi edilmediğinde mikroorganizmalar endoserviksten yukarıya, endometriuma ve tuba uterinalara (fallop tüpleri) asendan yolla yayılır. Sessizce gelişen kronik salpenjit ve tubal fibrozis/obstrüksiyon; kadında infertilite (kısırlık), ektopik (dış) gebelik ve kronik pelvik ağrının en önemli önlenebilir nedenidir.`,sik_aciklamalari:{A:`Doğrudur; sessiz asendan enfeksiyon tubal tıkanıklığa, infertiliteye ve ektopik gebeliğe yol açar.`,B:`Klasik tubal hasarın sonucu primer glomerülonefrit değildir.`,C:`Kemik iliği aplazisi yapmaz.`,D:`Karaciğer adenomu oral kontraseptifle ilişkilidir, klamidya ile değil.`,E:`Sol ventrikül hipertrofisi hipertansiyon sonucudur.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k06-q11`,kazanim:6,zorluk:`orta`,soru:`Trichomonas vaginalis enfeksiyonunun erkeklerdeki klinik seyri ile ilgili aşağıdaki ifadelerden hangisi DOĞRUDUR?`,secenekler:{A:`Erkeklerin büyük çoğunluğunda (>%70-80) tamamen asemptomatiktir ve erkekler asemptomatik rezervuar görevi görür`,B:`Erkeklerin tamamında penis kangrenine yol açar`,C:`Erkeklerde asla enfeksiyon oluşturamaz, sadece kadınlara özgüdür`,D:`Erkeklerde her zaman masif testis nekrozu yapar`,E:`Sadece idrar tahlilinde silendir görülmesiyle semptom verir`},dogru:`A`,aciklama:`Trichomonas vaginalis enfeksiyonu kadınlarda belirgin vulvovajinit yaparken, erkeklerde enfekte bireylerin %70-80'den fazlasında tamamen asemptomatiktir. Erkekler enfeksiyonu fark etmeden cinsel partnerlerine bulaştıran sessiz bir taşıyıcı/rezervuar görevi görürler. Bu nedenle kadın hasta tedavi edilirken erkek partnerin de asemptomatik olsa bile eş zamanlı tedavi edilmesi şarttır.`,sik_aciklamalari:{A:`Doğrudur; erkeklerde çoğunlukla asemptomatiktir ve bulaş kaynağı oluşturur.`,B:`Penis kangreni yapmaz.`,C:`Erkek üretrasında ve prostatında kolonize olabilir.`,D:`Testis nekrozu yapmaz.`,E:`Sessiz seyreder, idrar silendiri oluşturmaz.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k06-q12`,kazanim:6,zorluk:`zor`,soru:`Dünya Sağlık Örgütü (DSÖ) ve CDC rehberlerinde cinsel yönden aktif genç kadınlarda her yıl asemptomatik Chlamydia trachomatis taramasının önerilmesinin temel epidemiyolojik gerekçesi nedir?`,secenekler:{A:`Enfeksiyonun kadınlarda büyük oranda asemptomatik seyretmesi ve erken tanı/tedavi edilmezse kalıcı tubal infertiliteye yol açması`,B:`Klamidyanın doğrudan serviks karsinomuna yol açan ana onkovirüs olması`,C:`Klamidya bakterisinin sadece kan nakliyle bulaşabilmesi`,D:`Klamidya enfeksiyonunun antibiyotiklerle hiçbir şekilde tedavi edilememesi`,E:`Tüm kadınlarda doğumdan hemen sonra kendiliğinden yok olması`},dogru:`A`,aciklama:`Chlamydia trachomatis genç kadınlarda çok yaygındır ve %70-80 oranında hiçbir klinik belirti vermez. Asemptomatik taşıyıcılık fark edilmediğinde tüplere yayılarak sessiz tubal fibrozis ve infertilite yapar. Yıllık tarama programlarıyla bu sessiz vakalar yakalanıp tek doz/kısa süreli antibiyotikle tedavi edilerek kadınlarda kısırlık ve ektopik gebelik engellenir.`,sik_aciklamalari:{A:`Doğrudur; yüksek asemptomatik oran ve tubal infertilite riski taramanın ana gerekçesidir.`,B:`Serviks kanseri etkeni HPV'dir, klamidya değildir.`,C:`Klamidya cinsel yolla bulaşır.`,D:`Klamidya doksisiklin veya azitromisin ile çok kolay tedavi edilir.`,E:`Kendiliğinden hemen yok olmaz, kronikleşerek hasar verir.`},bilgi:[6],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:7,metin:`CYBH komplikasyonlarını (pelvik inflamatuvar hastalık, epididimoorşit, sistemik komplikasyonlar) tanımlayabilmek`,sorular:[{id:`k1-17-q19`,kazanim:7,zorluk:`kolay`,soru:`Pelvik inflamatuvar hastalığın (PİH) kapsamına aşağıdakilerden hangisi girmez?`,secenekler:{A:`Endometrit`,B:`Sistit`,C:`Salpenjit`,D:`Tuboovaryan abse`,E:`Pelvik peritonit`},dogru:`B`,aciklama:`PİH endometrit, salpenjit, ooforit, tuboovaryan abse ve pelvik peritoniti kapsar.`,sik_aciklamalari:{A:`PİH kapsamındadır; bu nedenle doğru seçenek değildir.`,B:`Doğru: sistit alt üriner enfeksiyondur.`,C:`PİH kapsamındadır; bu nedenle doğru seçenek değildir.`,D:`PİH kapsamındadır; bu nedenle doğru seçenek değildir.`,E:`PİH kapsamındadır; bu nedenle doğru seçenek değildir.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-17-q20`,kazanim:7,zorluk:`orta`,soru:`Disemine gonokok enfeksiyonunun sistemik komplikasyonları hangileridir?`,secenekler:{A:`Pnömoni ve plevrit`,B:`Menenjit ve ensefalit`,C:`Gonokoksik artrit ve perihepatit`,D:`Nefrolitiyazis`,E:`Hipotiroidi`},dogru:`C`,aciklama:`Sistemik komplikasyonlar reaktif artrit, gonokoksik artrit ve perihepatittir.`,sik_aciklamalari:{A:`Bu derste verilen komplikasyonlar değildir.`,B:`Bu derste verilen komplikasyonlar değildir.`,C:`Doğru: tipik sistemik komplikasyonlardır.`,D:`İlgisizdir; bu nedenle doğru seçenek değildir.`,E:`İlgisizdir; bu nedenle doğru seçenek değildir.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-17-q21`,kazanim:7,zorluk:`zor`,soru:`Ateşli skrotal ağrı ve ödemle başvuran erkekte epididimit düşünülürken ayırıcı tanıda yer alması gerekenler hangileridir?`,secenekler:{A:`Akut sistit`,B:`Yalnızca hidrosel`,C:`Yalnızca varikosel`,D:`Torsiyon, infarkt, abse ve nekrotizan fasiit`,E:`Böbrek taşı`},dogru:`D`,aciklama:`Epididimit/prostatit skrotal ağrı-ödem ve ağrılı ejakülasyonla seyreder; ateşte torsiyon, infarkt, abse ve nekrotizan fasiit ayırıcı tanıdadır.`,sik_aciklamalari:{A:`Sistit skrotal ağrı yapmaz.`,B:`Hidrosel ağrısızdır.`,C:`Varikosel akut ateşli tablo yapmaz.`,D:`Doğru: ayırıcı tanıda yer alanlardır.`,E:`Taş genellikle skrotal ödem yapmaz.`},bilgi:[14],benzer_cikmis:[`7854c9c91611`]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k07-q04`,kazanim:7,zorluk:`orta`,soru:`69 yaşındaki bir hasta ayırıcı tanısı tartışılan ve öyküsü derinleştirilen bir hastada hekime başvuruyor. Değerlendirmede "Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium, enterik bakteriler), virüs (HBV, HPV, CMV, EBV, Molluscum contagiosum,…" bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "CYBH komplikasyonlarını (pelvik inflamatuvar hastalık, epididimoorşit, sistemik komplikasyonlar) tanımlayabilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M.… ilkesinin tam tersi geçerlidir ve Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral,… gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma CYBH etken sınıflaması olup "CYBH komplikasyonlarını (pelvik inflamatuvar hastalık,…" ile ilişkisizdir`,C:`Bulgular "CYBH komplikasyonlarını (pelvik inflamatuvar hastalık,…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,D:`Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium, enterik bakteriler), virüs (HBV, HPV, CMV,… Bu nedenle Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter) belirlemenin ilk adımıdır.`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "CYBH etken sınıflaması" ile açıklanamaz`},dogru:`D`,aciklama:`Robbins/Harrison mantığıyla: Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium, enterik bakteriler), virüs (HBV, HPV, CMV, EBV,… Doğrudan sonucu "Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter) belirlemenin ilk adımıdır." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,D:`Doğru; Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium,…`,E:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k07-q05`,kazanim:7,zorluk:`zor`,soru:`Farklı bir hasta tanısal test sonucunun yorumlandığı bağımsız bir olguda ele alınıyor. Öyküde "CYBH etken sınıflaması" vurgulanıyor ve hekim "CYBH komplikasyonlarını (pelvik inflamatuvar hastalık, epididimoorşit, sistemik komplikasyonlar) tanımlayabilmek" kazanımındaki "Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium, enterik bakteriler), virüs (HBV, HPV, CMV, EBV,…" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter) belirlemenin ilk adımıdır. hiçbir koşulda gözlenmez ve CYBH etken sınıflaması tek belirleyicidir`,B:`Bu süreçte "CYBH etken sınıflaması" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Benzer tabloların tamamı aynı nedene bağlıdır; "CYBH etken sınıflaması" ayırıcı tanıda gereksizdir`,D:`Bu olguda izlem gerekmez; "CYBH komplikasyonlarını (pelvik inflamatuvar hastalık,…" yalnızca teorik bir bilgidir`,E:`Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter) belirlemenin ilk adımıdır. Çünkü Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium,…`},dogru:`E`,aciklama:`Guyton/Robbins bütünlüğünde: Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium, enterik bakteriler), virüs (HBV, HPV, CMV, EBV,… sonucu "Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter) belirlemenin ilk adımıdır." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,E:`Doğru; Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter) belirlemenin ilk…`},bilgi:[1],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k07-q06`,kazanim:7,zorluk:`orta`,soru:`Pelvik inflamatuvar hastalık: PİH endometrit, salpenjit, ooforit, tuboovaryan abse ve pelvik peritoniti kapsar. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Tedavi ilk atak ve tekrarlayan ataklar için ayrı planlanır`,B:`serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir`,C:`Yakınmaların süresine göre akut (gonokok) ve subakut/persistan (klamidya) üretrit ayırımı`,D:`Gebede uygun ilaç seçimi fetal güvenliği korur`,E:`İnfertilite, ektopik gebelik ve kronik pelvik ağrı gibi sekellerle sonuçlanabilir`},dogru:`E`,aciklama:`PİH endometrit, salpenjit, ooforit, tuboovaryan abse ve pelvik peritoniti kapsar. İnfertilite, ektopik gebelik ve kronik pelvik ağrı gibi sekellerle sonuçlanabilir. Fizyopatolojik sıra bu yönde ilerlediğinden PİH endometrit, salpenjit, ooforit, tuboovaryan abse ve varlığında İnfertilite, ektopik gebelik ve kronik pelvik ağrı beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt E seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Genital herpes tanısı sürecine ait bir özelliktir ve pelvik inflamatuvar hastalık düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Vajinit ve servisit ayrımı sürecine ait bir özelliktir ve pelvik inflamatuvar hastalık düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Üretral akıntı ve üretrit sürecine ait bir özelliktir ve pelvik inflamatuvar hastalık düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Klamidya tedavisi sürecine ait bir özelliktir ve pelvik inflamatuvar hastalık düzeneğini tanımlamaz.`,E:`Doğru; İnfertilite, ektopik gebelik ve kronik pelvik ağrı gibi sekellerle sonuçlanabilir çünkü PİH endometrit, salpenjit, ooforit, tuboovaryan abse ve pelvik düzeneği bu sonucu üretir.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k07-q07`,kazanim:7,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Sistemik komplikasyonlar mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Bulaş genellikle vajinal, anal veya oral mukoza yoluyla`,B:`Reaktif artrit`,C:`Servisit veya üretritte Gram boyamada intraselüler gram negatif diplokokların görülmesi`,D:`Hasta başı ekim ve %10 CO2'li ortam gerekir`,E:`Tuboovaryan abse, gebelik, bulantı-kusma ve ateş yüksekliği, oral tedaviye yanıtsızlık`},dogru:`B`,aciklama:`Reaktif artrit. Genital yakınması olmayan eklem/ağrı tablosunda CYBH akla getirilmelidir. Bu ilişki Enfeksiyon Hastalıkları fizyolojisinin temel düzeneklerinden biridir: Reaktif artrit doğrudan Genital yakınması olmayan eklem/ağrı tablosunda CYBH akla doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt B seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Bulaş yolları sürecine ait bir özelliktir ve sistemik komplikasyonlar düzeneğini tanımlamaz.`,B:`Doğru; Reaktif artrit. Bu mekanizma genital yakınması olmayan eklem/ağrı tablosunda cybh akla getirilmelidir sonucunu doğurur.`,C:`Yanlış; bu ifade Gram negatif diplokoklar sürecine ait bir özelliktir ve sistemik komplikasyonlar düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade N. gonorrhoeae kültürü sürecine ait bir özelliktir ve sistemik komplikasyonlar düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade PİH yatış endikasyonları sürecine ait bir özelliktir ve sistemik komplikasyonlar düzeneğini tanımlamaz.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k07-q08`,kazanim:7,zorluk:`orta`,soru:`Pelvik İnflamatuvar Hastalık (PİH) zemininde gelişen ve karaciğer kapsülü ile parietal periton arasında karakteristik 'keman teli' (violin-string) tarzında fibröz yapışıklıklar oluşturan perihepatit tablosuna ne ad verilir?`,secenekler:{A:`Fitz-Hugh-Curtis sendromu`,B:`Waterhouse-Friderichsen sendromu`,C:`Reiter (Reaktif Artrit) sendromu`,D:`Budd-Chiari sendromu`,E:`Lemierre sendromu`},dogru:`A`,aciklama:`Fitz-Hugh-Curtis sendromu, PİH'in (özellikle Chlamydia trachomatis ve Neisseria gonorrhoeae enfeksiyonlarının) bir komplikasyonu olarak mikroorganizmaların parakolik oluktan yukarı çıkarak karaciğer kapsülü çevresinde enflamasyon (perihepatit) yapmasıdır. İyileşme evresinde karaciğer kapsülü ile ön karın duvarı arasında tipik 'keman teli' fibröz yapışıklıklar oluşur; sağ üst kadran ağrısıyla kolesistiti taklit edebilir.`,sik_aciklamalari:{A:`Doğrudur; PİH'e sekonder gelişen keman teli perihepatit tablosu Fitz-Hugh-Curtis sendromudur.`,B:`Meningokoksemide bilateral adrenal bez kanaması ve akut yetmezliğidir.`,C:`Üretrit/servisit sonrası gelişen artrit, konjonktivit ve üretrit triadıdır.`,D:`Hepatik venlerin trombozudur.`,E:`Fusobacterium necrophorum enfeksiyonuna sekonder internal juguler ven septik tromboflebitidir.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k07-q09`,kazanim:7,zorluk:`zor`,soru:`Dissemine Gonokokal Enfeksiyon (DGE) tablosunda gonokokların mukozadan kana karışarak sistemik yayılım göstermesi sonucunda ortaya çıkan klasik klinik triad aşağıdakilerden hangisidir?`,secenekler:{A:`Tenosinovit, poliartralji (veya göçücü artrit) ve akral yerleşimli püstüler/hemorajik deri lezyonları`,B:`Menenjit, glomerulonefrit ve splenomegali`,C:`Katarakt, sağırlık ve patent duktus arteriozus`,D:`Pankreatit, parotit ve orşit`,E:`Hemolitik anemi, trombositopeni ve akut böbrek yetmezliği`},dogru:`A`,aciklama:`Dissemine Gonokokal Enfeksiyon (DGE); gonokokların bakteriyemi yapmasıyla özellikle komplet eksikliği (C5-C9) olan bireylerde veya menstruasyon dönemindeki kadınlarda gelişir. Klasik klinik tablosu: 1) Tenosinovit (özellikle el bileği, ayak bileği tendon kılıflarında); 2) Göçücü asimetrik poliartralji veya süpüratif monoartrit; 3) Ekstremite distalinde az sayıda eritemli zemin üzerinde püstüler veya hemorajik nekrotik deri lezyonlarıdır.`,sik_aciklamalari:{A:`Doğrudur; tenosinovit, poliartralji ve püstüler/nekrotik deri döküntüleri DGE'nin klasik triadıdır.`,B:`Meningokoksemi veya bakteriyel endokardit komplikasyonlarıdır.`,C:`Konjenital kızamıkçık triadıdır (Gregg triadı).`,D:`Kabakulak virüsü komplikasyonlarıdır.`,E:`Hemolitik üremik sendrom (HÜS) triadıdır.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k07-q10`,kazanim:7,zorluk:`orta`,soru:`Cinsel yönden aktif 35 yaş altı genç bir erkek hastada tek taraflı skrotal ağrı, şişlik ve epididim duyarlılığı ile karakterize akut epididimite en sık yol açan iki CYBH etkeni aşağıdakilerden hangisidir?`,secenekler:{A:`Chlamydia trachomatis ve Neisseria gonorrhoeae`,B:`Escherichia coli ve Pseudomonas aeruginosa`,C:`Treponema pallidum ve Herpes Simplex Virüs`,D:`Haemophilus ducreyi ve Trichomonas vaginalis`,E:`Klebsiella pneumoniae ve Proteus mirabilis`},dogru:`A`,aciklama:`35 yaş altı cinsel olarak aktif erkeklerde akut epididimite yol açan en yaygın mikroorganizmalar cinsel yolla bulaşan patojenler olan Chlamydia trachomatis ve Neisseria gonorrhoeae'dir. Buna karşılık 35 yaş üstü erkeklerde epididimit genellikle üriner obstrüksiyona bağlı koliform enterik bakterilerle (E. coli) gelişir.`,sik_aciklamalari:{A:`Doğrudur; 35 yaş altı erkeklerde epididimite en sık C. trachomatis ve N. gonorrhoeae neden olur.`,B:`E. coli ve Pseudomonas 35 yaş üstü üriner obstrüksiyon zeminindeki epididimitlerin ana etkenleridir.`,C:`Treponema ve HSV primer akut epididimit etkeni değildir.`,D:`H. ducreyi şankroid yapar, epididimit yapmaz.`,E:`Enterik bakteriler yaşlı erkeklerde ön plandadır.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k07-q11`,kazanim:7,zorluk:`zor`,soru:`Chlamydia trachomatis genital enfeksiyonu sonrasında HLA-B27 pozitif bireylerde gelişebilen 'Reaktif Artrit' (Reiter sendromu) klinik tablosunu oluşturan üç temel bulgu aşağıdakilerin hangisinde eksiksiz verilmiştir?`,secenekler:{A:`Üretrit/Servisit, Konjonktivit (veya Üveit) ve Asimetrik Oligoartrit`,B:`Orşit, Pankreatit ve Trombositopeni`,C:`Menenjit, Eritema nodozum ve Pulmoner kavite`,D:`Aort yetmezliği, Nefrit ve Alopesi`,E:`Perikardit, Özofajit ve Anemi`},dogru:`A`,aciklama:`Reaktif artrit (Reiter sendromu), genetik olarak yatkın (özellikle HLA-B27 pozitif) bireylerde ürogenital (C. trachomatis) veya gastrointestinal (Salmonella, Shigella, Yersinia, Campylobacter) enfeksiyonlardan 1-4 hafta sonra ortaya çıkan otoimmün bir tablodur. Klasik triadı: 1) Nongonokokal üretrit (veya servisit); 2) Konjonktivit veya anterior üveit; 3) Özellikle alt ekstremite büyük eklemlerini tutan asimetrik oligoartrittir ('göremiyorum, işeyemiyorum, dizlerimin üstüne çöremiyorum').`,sik_aciklamalari:{A:`Doğrudur; üretrit, konjonktivit ve asimetrik artrit reaktif artritin klasik triadıdır.`,B:`Kabakulak ve hematolojik bulguların karışımıdır.`,C:`Tüberküloz veya sarkoidoz bulgularıdır.`,D:`Sifiliz veya SLE bulgularıdır.`,E:`Reaktif artrite özgü triad değildir.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k07-q12`,kazanim:7,zorluk:`orta`,soru:`Tedavi edilmeyen veya geç tedavi edilen pelvik inflamatuvar hastalık geçiren bir kadında en sık görülen KRONİK sekeller aşağıdakilerden hangisinde birlikte verilmiştir?`,secenekler:{A:`Kronik pelvik ağrı, tubal faktör infertilitesi ve ektopik (dış) gebelik riski artışı`,B:`Over karsinomu ve serviks sarkomu`,C:`Vajinal agenezi ve Mayer-Rokitansky sendromu`,D:`Polikistik over sendromu ve hirsutizm`,E:`Tip 1 diabetes mellitus ve tiroidit`},dogru:`A`,aciklama:`PİH sırasında gelişen tubal enflamasyon ve iyileşirken oluşan nedbe dokusu tubal mukozanın siliyer aktivitesini bozar ve lümeni daraltır/tıkar. Bunun sonucunda: 1) Tubal faktör infertilitesi (kısırlık); 2) Döllenmiş yumurtanın rahme ulaşamaması nedeniyle ektopik gebelik (risk 6-10 kat artar); 3) Pelvik yapışıklıklara bağlı kronik pelvik ağrı gelişir.`,sik_aciklamalari:{A:`Doğrudur; tubal hasar kısırlık, dış gebelik ve kronik ağrıya yol açar.`,B:`PİH over kanseri veya serviks sarkomu nedeni değildir.`,C:`Mayer-Rokitansky konjenital embriyolojik bir malformasyondur.`,D:`PKOS hormonal/endokrin bir bozukluktur, enfeksiyon sekeli değildir.`,E:`Otoimmün endokrin bozukluklardır, PİH ile ilgisi yoktur.`},bilgi:[7],benzer_cikmis:[]}],ilgili_cikmis:[{id:`7854c9c91611`,soru:`Akut enfeksiyöz orşit tablosuyla gelen genç bir erkekte yapılması gereken en önemli ayırıcı tanı hangisidir?`,secenekler:{A:`Testis torsiyonu`,B:`Varikorsel`,C:`Tüberküloz orşiti`,D:`Hidrosel`,E:`Akut epididimit`},cevap:`A`}]},{no:8,metin:`CYBH tanısında direkt bakı, nükleik asit amplifikasyon testleri (NAAT) ve kültürün yerini bilmek`,sorular:[{id:`k1-17-q22`,kazanim:8,zorluk:`kolay`,soru:`CYBH tanısında yüksek duyarlılığı nedeniyle ilk seçenek kabul edilen yöntem hangisidir?`,secenekler:{A:`Ultrasonografi`,B:`Kültür`,C:`Direkt bakı`,D:`Serum biyokimyası`,E:`Nükleik asit amplifikasyon testleri (NAAT)`},dogru:`E`,aciklama:`NAAT yüksek duyarlılıkla ilk seçenektir; kültür direnç takibinde gereklidir.`,sik_aciklamalari:{A:`USG CYBH tanısı koydurmaz.`,B:`Kültür direnç takibi için gereklidir.`,C:`Direkt bakı hızlıdır ama duyarlılığı sınırlıdır.`,D:`Biyokimya tanı koydurmaz.`,E:`Doğru: ilk seçenektir.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-17-q23`,kazanim:8,zorluk:`orta`,soru:`Genital herpes tanısında kullanılan yöntem hangisidir?`,secenekler:{A:`Gram boyama`,B:`KOH preparatı`,C:`NAAT; klinik şüphede HSV-2'ye spesifik antikor`,D:`Amin kokusu testi`,E:`Karanlık alan mikroskopisi`},dogru:`C`,aciklama:`Genital herpes tanısı NAAT ile konur; klinik şüphede HSV-2 spesifik antikor bakılır.`,sik_aciklamalari:{A:`Gram boyama bakteriyel etkenler içindir.`,B:`KOH mantar ve BV için kullanılır.`,C:`Doğru: tanı yöntemidir.`,D:`Amin testi BV içindir.`,E:`Karanlık alan mikroskopisi sifilis için kullanılır.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-17-q24`,kazanim:8,zorluk:`zor`,soru:`CYBH tanı yöntemlerinin yeri ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`NAAT yüksek duyarlılıklıdır`,B:`Kültür antibiyotik direnç takibini sağlar`,C:`Direkt bakı hızlı ve ucuz bir ilk basamak olabilir`,D:`Şankroidde kesin tanı kültürle konur`,E:`Kültür, NAAT'a göre her zaman daha duyarlıdır ve ilk seçenektir`},dogru:`E`,aciklama:`NAAT duyarlılığı yüksek olduğundan ilk seçenektir; kültür esas olarak direnç takibinde değerlidir.`,sik_aciklamalari:{A:`Doğru ifade; bu nedenle doğru seçenek değildir.`,B:`Doğru ifade; bu nedenle doğru seçenek değildir.`,C:`Doğru ifade; bu nedenle doğru seçenek değildir.`,D:`Doğru ifade; bu nedenle doğru seçenek değildir.`,E:`Yanlış ifade (aranan cevap): NAAT ilk seçenektir.`},bilgi:[16,17,29],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k08-q04`,kazanim:8,zorluk:`orta`,soru:`26 yaşındaki bir hasta tedavi yanıtı izlenen ve kliniği yeniden değerlendirilen bir olguda hekime başvuruyor. Değerlendirmede "Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium, enterik bakteriler), virüs (HBV, HPV, CMV, EBV, Molluscum contagiosum,…" bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "CYBH tanısında direkt bakı, nükleik asit amplifikasyon testleri (NAAT) ve kültürün yerini bilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M.… ilkesinin tam tersi geçerlidir ve Kandidiyazis vajinitin non-CYBH nedenleri arasında olup tedavisi antifungal… gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Maya (KOH/Gram) olup "CYBH tanısında direkt bakı, nükleik asit amplifikasyon…" ile ilişkisizdir`,C:`Bulgular "CYBH tanısında direkt bakı, nükleik asit amplifikasyon testleri…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,D:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "CYBH etken sınıflaması" ile açıklanamaz`,E:`Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium, enterik bakteriler), virüs (HBV, HPV, CMV,… Bu nedenle Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter) belirlemenin ilk adımıdır.`},dogru:`E`,aciklama:`Robbins/Harrison mantığıyla: Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium, enterik bakteriler), virüs (HBV, HPV, CMV, EBV,… Doğrudan sonucu "Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter) belirlemenin ilk adımıdır." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,E:`Doğru; Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi, K. granulomatis, M. genitalium,…`},bilgi:[1,5],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k08-q05`,kazanim:8,zorluk:`zor`,soru:`Farklı bir hasta aynı konunun farklı bir yönünü aydınlatmak için ele alınan ikinci bir olguda ele alınıyor. Öyküde "Maya (KOH/Gram)" vurgulanıyor ve hekim "CYBH tanısında direkt bakı, nükleik asit amplifikasyon testleri (NAAT) ve kültürün yerini bilmek" kazanımındaki "%10 KOH veya Gram boyama ile tomurcuklanan maya hücreleri kandidiyazisi gösterir." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Kandidiyazis vajinitin non-CYBH nedenleri arasında olup tedavisi antifungal ilaçlardır. Çünkü %10 KOH veya Gram boyama ile tomurcuklanan maya hücreleri kandidiyazisi gösterir.`,B:`Kandidiyazis vajinitin non-CYBH nedenleri arasında olup tedavisi antifungal ilaçlardır. hiçbir koşulda gözlenmez ve CYBH etken sınıflaması tek belirleyicidir`,C:`Bu süreçte "CYBH etken sınıflaması" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Maya (KOH/Gram)" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "CYBH tanısında direkt bakı, nükleik asit amplifikasyon testleri…" yalnızca teorik bir bilgidir`},dogru:`A`,aciklama:`Guyton/Robbins bütünlüğünde: %10 KOH veya Gram boyama ile tomurcuklanan maya hücreleri kandidiyazisi gösterir. sonucu "Kandidiyazis vajinitin non-CYBH nedenleri arasında olup tedavisi antifungal ilaçlardır." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Doğru; Kandidiyazis vajinitin non-CYBH nedenleri arasında olup tedavisi antifungal ilaçlardır. Çünkü %10 KOH veya…`,B:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "CYBH etken sınıflaması" bilgisiyle çelişir.`},bilgi:[6,8],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k08-q06`,kazanim:8,zorluk:`orta`,soru:`Tanı yöntemleri: Direkt bakı, nükleik asit amplifikasyon testleri (NAAT) ve kültür kullanılır. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`NAAT yüksek duyarlılığıyla ilk seçenek`,B:`Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur`,C:`Tanı doğrulanınca metronidazol tedavisi ve partner tedavisi başlanır`,D:`Ateş yüksekliğinde torsiyon, infarkt, abse ve nekrotizan fasiit ayırıcı tanıya`,E:`Alerji durumunda etkin alternatif şemalar mevcuttur`},dogru:`A`,aciklama:`Direkt bakı, nükleik asit amplifikasyon testleri (NAAT) ve kültür kullanılır. NAAT yüksek duyarlılığıyla ilk seçenek. Bu ilişki Enfeksiyon Hastalıkları fizyolojisinin temel düzeneklerinden biridir: Direkt bakı, nükleik asit amplifikasyon testleri (NAAT) doğrudan NAAT yüksek duyarlılığıyla ilk seçenek doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt A seçeneğidir.`,sik_aciklamalari:{A:`Doğru; NAAT yüksek duyarlılığıyla ilk seçenek çünkü Direkt bakı, nükleik asit amplifikasyon testleri (NAAT) ve düzeneği bu sonucu üretir.`,B:`Yanlış; bu ifade Anogenital siğil sürecine ait bir özelliktir ve tanı yöntemleri düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Trofozoit (SF) sürecine ait bir özelliktir ve tanı yöntemleri düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Epididimit/prostatit sürecine ait bir özelliktir ve tanı yöntemleri düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Gonore kombine tedavisi sürecine ait bir özelliktir ve tanı yöntemleri düzeneğini tanımlamaz.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k08-q07`,kazanim:8,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Anogenital siğil mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`%10 KOH eklenmesiyle ortaya çıkan amin kokusu bakteriyel vajinozis için`,B:`Kadında klamidya %90'a varan, gonore %50'ye varan, trikomoniyazis %10-50`,C:`Kondiloma akuminata`,D:`Azitromisin 1 g tek doz`,E:`Seftriakson 1x250 mg tek doz + levofloksasin 1x500 mg 10`},dogru:`C`,aciklama:`Enfeksiyon Hastalıkları düzeneğinde Kondiloma akuminata bilinir. Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur. Mekanizma bu sırayla işlediği için beklenen sonuç Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt C seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Amin kokusu testi (KOH) sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Asemptomatik seyir oranları sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,C:`Doğru; Kondiloma akuminata. Bu mekanizma tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif sonucunu doğurur.`,D:`Yanlış; bu ifade Klamidya tedavisi sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Epididimoorşit tedavisi sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k08-q08`,kazanim:8,zorluk:`orta`,soru:`Günümüzde Chlamydia trachomatis ve Neisseria gonorrhoeae ürogenital enfeksiyonlarının tanısında en yüksek duyarlılık (sensitivite) ve özgüllüğe (spesifite) sahip olduğu için altın standart kabul edilen tanı yöntemi aşağıdakilerden hangisidir?`,secenekler:{A:`Nükleik Asit Amplifikasyon Testleri (NAAT / PCR)`,B:`Karanlık saha mikroskopisi`,C:`Direkt Giemsa boyaması`,D:`Kompleman birleşme testi`,E:`Kanda lökosit formül sayımı`},dogru:`A`,aciklama:`Nükleik Asit Amplifikasyon Testleri (NAAT; PCR, TMA, SDA vb.), Chlamydia trachomatis ve Neisseria gonorrhoeae enfeksiyonlarının tanısında en yüksek duyarlılık (>%95-98) ve özgüllüğe sahip altın standart yöntemdir. Üstelik invaziv olmayan ilk idrar (first-catch urine) veya kendi kendine alınan vajinal sürüntü örneklerinde bile mükemmel sonuç verir.`,sik_aciklamalari:{A:`Doğrudur; NAAT günümüzde klamidya ve gonore tanısında altın standart yöntemdir.`,B:`Karanlık saha mikroskopisi sadece Treponema pallidum tanısında kullanılır.`,C:`Giemsa boyaması klamidya için çok düşük duyarlılığa sahiptir.`,D:`Serolojik testler aktif mukozal ürogenital enfeksiyonu ayırt etmede yetersizdir.`,E:`Lökosit formülü spesifik etkeni göstermez.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k08-q09`,kazanim:8,zorluk:`zor`,soru:`Akut pürülan üretral akıntısı olan SEMPTOMATİK bir ERKEK hastada, gonore tanısında üretral sürüntünün Gram boyamasının tanısal değeri ile KADINLARDA servikal sürüntünün Gram boyamasının değeri karşılaştırıldığında aşağıdakilerden hangisi DOĞRUDUR?`,secenekler:{A:`Semptomatik erkek üretral akıntısında lökosit içi Gram-negatif diplokok görülmesi %95'in üzerinde duyarlılık ve özgüllükle tanı koydurur; kadınlarda ise endoservikal Gram boyamanın duyarlılığı oldukça düşüktür (%50 civarı)`,B:`Kadınlarda Gram boyama %100 tanı koydururken erkeklerde tanı değeri yoktur`,C:`Erkeklerde Gram boyamada gonokoklar daima hücre dışı Gram-pozitif zincirler halinde görülür`,D:`Kadınlarda vajinal floradaki Lactobacillus türleri mikroskopta gonokok sanıldığı için test asla uygulanamaz`,E:`Gram boyama hem erkekte hem kadında %100 geçersizdir, sadece seroloji kullanılır`},dogru:`A`,aciklama:`Erkeklerde semptomatik gonokokal üretrit akıntısında nötrofiller içinde Gram-negatif kahve çekirdeği şeklinde diplokokların (intrasellüler GND) görülmesi %95-99 sensitivite ve spesifisiteye sahiptir ve ek test beklemeden tedaviye başlanabilir. Kadınlarda ise endoservikal floranın karmaşıklığı ve kommensal Neisseria/Moraxella türleri nedeniyle Gram boyamanın duyarlılığı sadece %30-50'dir; bu nedenle kadınlarda Gram boyama negatif olsa bile NAAT veya kültür şarttır.`,sik_aciklamalari:{A:`Doğrudur; erkekte çok yüksek doğrulukla tanı koydurur, kadında duyarlılığı düşüktür.`,B:`Tam tersine erkekte tanı değeri çok yüksektir, kadında düşüktür.`,C:`Gonokoklar Gram-negatiftir, Gram-pozitif zincir yapmaz.`,D:`Laktobasiller büyük Gram-pozitif basillerdir, diplokokla karışmaz.`,E:`Gram boyama semptomatik erkekte en hızlı ve ucuz tanı aracıdır.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k08-q10`,kazanim:8,zorluk:`orta`,soru:`Erkek ve kadınlarda NAAT yöntemiyle Chlamydia ve Gonore taranırken, invaziv sürüntü çubuğu ALMAKSIZIN kullanılabilecek en uygun ve duyarlı idrar örneği aşağıdakilerden hangisidir?`,secenekler:{A:`En az 1-2 saattir idrar yapmamış hastadan alınan İLK idrar akımı (first-catch urine, ilk 10-20 mL)`,B:`Klasik orta akım idrarı (midstream urine)`,C:`24 saatlik toplanmış idrar`,D:`Sabah idrarının sadece son damlaları`,E:`Kateterle mesaneden aspire edilen steril idrar`},dogru:`A`,aciklama:`Ürogenital klamidya ve gonore taramasında NAAT için erkeklerde (ve arzu edildiğinde kadınlarda) üretral epitel hücrelerini ve eksüdayı yıkayıp toplayabilmek için 'ilk idrar' (first-catch / first-void urine: ilk 10-20 mL) örneği alınır. Hastanın son idrarından sonra en az 1-2 saat geçmiş olması hücre konsantrasyonunu artırmak için önerilir. Orta akım idrarı üretrayı yıkadıktan sonra mesaneyi temsil ettiği için CYBH taramasında önerilmez.`,sik_aciklamalari:{A:`Doğrudur; üretral döküntüyü yakalamak için ilk idrar (first-catch, ilk 10-20 mL) örneği kullanılır.`,B:`Orta akım idrarı klasik idrar yolu enfeksiyonu (sistit/piyelonefrit) için kullanılır, CYBH'de duyarlılığı düşüktür.`,C:`24 saatlik idrar protein/metabolit takibindedir.`,D:`Son damlalar üretral patojenleri seyreltir.`,E:`Kateterizasyon invazivdir ve CYBH taramasında yeri yoktur.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k08-q11`,kazanim:8,zorluk:`orta`,soru:`Primer sifiliz şüphesi olan bir hastada sert şankr tabanından alınan seröz eksüdanın incelenmesinde hareketli Treponema pallidum spiroketlerini canlı olarak gösteren direkt mikroskopi yöntemi aşağıdakilerden hangisidir?`,secenekler:{A:`Karanlık saha mikroskopisi (Darkfield microscopy)`,B:`Standart Wright-Giemsa boyaması`,C:`Ziehl-Neelsen asidorezistan boyaması`,D:`Çini mürekkebi mikroskopisi`,E:`Alüminyum hidroksit presipitasyonu`},dogru:`A`,aciklama:`Treponema pallidum çok ince (yaklaşık 0.15 mikron çapında) bir spiroket olduğu için standart ışık mikroskobunun çözünürlük sınırının altındadır ve normal boyalarla görülemez. Şankr eksüdasından hazırlanan taze preparatta karanlık saha mikroskopisi (veya direkt floresan antikor / DFA-TP) kullanılarak karakteristik tirbüşon hareketi gösteren spiroketler direkt olarak tespit edilir.`,sik_aciklamalari:{A:`Doğrudur; şankrdan spiroketlerin tespiti karanlık saha mikroskopisi ile yapılır.`,B:`Giemsa ile T. pallidum rutin görülemez.`,C:`Ziehl-Neelsen mikobakteriler (tüberküloz) içindir.`,D:`Çini mürekkebi Cryptococcus neoformans kapsülünü göstermek içindir.`,E:`Alüminyum hidroksit aşı adjuvanıdır, mikroskopi yöntemi değildir.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k08-q12`,kazanim:8,zorluk:`zor`,soru:`NAAT testlerinin yaygınlaşmasına rağmen, Neisseria gonorrhoeae enfeksiyonunda bakteriyel KÜLTÜRÜN vazgeçilmez olmasının EN ÖNEMLİ klinik ve epidemiyolojik nedeni nedir?`,secenekler:{A:`Antibiyotik duyarlılık testinin (antibiyogram) yapılabilmesi ve antimikrobiyal direnç sürveyansının sağlanması`,B:`Kültürün NAAT'tan 10 kat daha hızlı sonuç vermesi`,C:`Kültürün canlı olmayan bakterileri de üretebilmesi`,D:`NAAT testinin gonokoklar için yalancı pozitiflik oranının %90 olması`,E:`Kültür için özel besiyerine hiç ihtiyaç duyulmaması`},dogru:`A`,aciklama:`NAAT testleri bakterinin DNA/RNA'sını saptar ancak canlı bakteri üretmediği için disk difüzyon veya E-test ile in vitro antibiyotik duyarlılık testi (antibiyogram) yapılmasına olanak sağlamaz. Gonokokların hızla çoklu ilaç direnci (sefalosporin, azitromisin, siprofloksasin direnci) geliştirmesi nedeniyle, tedavi başarısızlığı şüphesinde veya direnç takibinde kültür ve antibiyogram vazgeçilmezdir.`,sik_aciklamalari:{A:`Doğrudur; antibiyotik duyarlılık testi (antibiyogram) sadece canlı bakteri üreten kültürle yapılabilir.`,B:`Kültür 24-48 saat sürer, NAAT ise birkaç saatte sonuç verebilir.`,C:`Kültür sadece canlı bakterileri üretir; ölü bakterileri üretemez.`,D:`NAAT testlerinin özgüllüğü %99'un üzerindedir.`,E:`Gonore kültürü oldukça zor üreyen bir bakteridir, Thayer-Martin gibi zenginleştirilmiş özel besiyerleri gerektirir.`},bilgi:[8],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:9,metin:`Neisseria gonorrhoeae kültürünün özel koşullarını ve antibiyogram avantajını açıklayabilmek`,sorular:[{id:`k1-17-q25`,kazanim:9,zorluk:`kolay`,soru:`Neisseria gonorrhoeae kültürünün en önemli avantajı hangisidir?`,secenekler:{A:`En yüksek duyarlılığa sahip olması`,B:`Sonucun dakikalar içinde çıkması`,C:`Özel koşul gerektirmemesi`,D:`Antibiyogram yapılabilmesi`,E:`Viral etkenleri de göstermesi`},dogru:`D`,aciklama:`Kültürle antibiyogram yapılarak dirence göre tedavi planlanır.`,sik_aciklamalari:{A:`NAAT daha duyarlıdır.`,B:`Kültür zaman alır; bu nedenle doğru seçenek değildir.`,C:`Özel koşullar gerekir.`,D:`Doğru: kültürün avantajıdır.`,E:`Bakteri kültürüdür; bu nedenle doğru seçenek değildir.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-17-q26`,kazanim:9,zorluk:`orta`,soru:`N. gonorrhoeae kültürü için gerekli özel koşullar hangileridir?`,secenekler:{A:`Örneğin dondurulup ertesi hafta ekilmesi`,B:`Hasta başı ekim ve %10 CO2'li ortam`,C:`Anaerob ortam ve oda ısısı`,D:`Yalnızca kanlı agar ve aerob ortam, gecikmeli ekim`,E:`Özel koşul gerekmez`},dogru:`B`,aciklama:`Gonokok hassas bir bakteridir; hasta başı ekim ve CO2'li ortam gerektirir.`,sik_aciklamalari:{A:`Dondurma bakteriyi öldürebilir.`,B:`Doğru: kültür koşullarıdır.`,C:`Anaerob ortam uygun değildir.`,D:`Gecikme üremeyi engeller.`,E:`Özel koşul gerekir; bu nedenle doğru seçenek değildir.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-17-q27`,kazanim:9,zorluk:`zor`,soru:`Gonore tedavisinde güncel antibiyograma göre tedavi planlanmasının gerekçesi hangisidir?`,secenekler:{A:`Tedavinin gereksiz olması`,B:`Gonokokun hiç direnç geliştirmemesi`,C:`Antibiyotiklerin gonoreyi etkilememesi`,D:`Gonorenin viral etiyolojisi`,E:`Gonokokta penisilinaz, PBP değişimi, tetrasiklin ve kinolon direnci gibi gelişen direnç mekanizmaları`},dogru:`E`,aciklama:`Direnç gelişimi nedeniyle kültür ve antibiyogram tedavi seçimine rehberlik eder.`,sik_aciklamalari:{A:`Tedavi gereklidir; bu nedenle doğru seçenek değildir.`,B:`Direnç gelişir; bu nedenle doğru seçenek değildir.`,C:`Uygun antibiyotiklerle tedavi edilir.`,D:`Bakteriyeldir; bu nedenle doğru seçenek değildir.`,E:`Doğru: direnç mekanizmalarıdır.`},bilgi:[17,21],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k09-q04`,kazanim:9,zorluk:`orta`,soru:`33 yaşındaki bir hasta tarama sırasında saptanan ve ileri incelemeye alınan bir kişide hekime başvuruyor. Değerlendirmede "Reaktif artrit; disemine gonokok enfeksiyonuna bağlı gonokoksik artrit ve perihepatit görülebilir." bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "Neisseria gonorrhoeae kültürünün özel koşullarını ve antibiyogram avantajını açıklayabilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Reaktif artrit; disemine gonokok enfeksiyonuna bağlı gonokoksik artrit ve perihepatit görülebilir. Bu nedenle Genital yakınması olmayan eklem/ağrı tablosunda CYBH akla getirilmelidir.`,B:`Reaktif artrit; disemine gonokok enfeksiyonuna bağlı gonokoksik artrit ve perihepatit görülebilir. ilkesinin tam tersi geçerlidir ve NAAT yüksek duyarlılığıyla ilk seçenek; kültür ise direnç takibinde gereklidir. gözlenmez`,C:`Bu tablodan sorumlu temel mekanizma Tanı yöntemleri olup "Neisseria gonorrhoeae kültürünün özel koşullarını ve…" ile ilişkisizdir`,D:`Bulgular "Neisseria gonorrhoeae kültürünün özel koşullarını ve antibiyogram…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Sistemik komplikasyonlar" ile açıklanamaz`},dogru:`A`,aciklama:`Robbins/Harrison mantığıyla: Reaktif artrit; disemine gonokok enfeksiyonuna bağlı gonokoksik artrit ve perihepatit görülebilir. Doğrudan sonucu "Genital yakınması olmayan eklem/ağrı tablosunda CYBH akla getirilmelidir." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Doğru; Reaktif artrit; disemine gonokok enfeksiyonuna bağlı gonokoksik artrit ve perihepatit görülebilir. Bu nedenle…`,B:`Yanlış; ders paketindeki "Sistemik komplikasyonlar" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Sistemik komplikasyonlar" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Sistemik komplikasyonlar" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Sistemik komplikasyonlar" bilgisiyle çelişir.`},bilgi:[15,16],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k09-q05`,kazanim:9,zorluk:`zor`,soru:`Farklı bir hasta komplikasyon gelişen ve mekanizması sorgulanan başka bir hastada ele alınıyor. Öyküde "Tanı yöntemleri" vurgulanıyor ve hekim "Neisseria gonorrhoeae kültürünün özel koşullarını ve antibiyogram avantajını açıklayabilmek" kazanımındaki "Direkt bakı, nükleik asit amplifikasyon testleri (NAAT) ve kültür kullanılır." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`NAAT yüksek duyarlılığıyla ilk seçenek; kültür ise direnç takibinde gereklidir. hiçbir koşulda gözlenmez ve Sistemik komplikasyonlar tek belirleyicidir`,B:`NAAT yüksek duyarlılığıyla ilk seçenek; kültür ise direnç takibinde gereklidir. Çünkü Direkt bakı, nükleik asit amplifikasyon testleri (NAAT) ve kültür kullanılır.`,C:`Bu süreçte "Sistemik komplikasyonlar" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Tanı yöntemleri" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Neisseria gonorrhoeae kültürünün özel koşullarını ve antibiyogram…" yalnızca teorik bir bilgidir`},dogru:`B`,aciklama:`Guyton/Robbins bütünlüğünde: Direkt bakı, nükleik asit amplifikasyon testleri (NAAT) ve kültür kullanılır. sonucu "NAAT yüksek duyarlılığıyla ilk seçenek; kültür ise direnç takibinde gereklidir." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Sistemik komplikasyonlar" bilgisiyle çelişir.`,B:`Doğru; NAAT yüksek duyarlılığıyla ilk seçenek; kültür ise direnç takibinde gereklidir. Çünkü Direkt bakı, nükleik…`,C:`Yanlış; ders paketindeki "Sistemik komplikasyonlar" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Sistemik komplikasyonlar" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Sistemik komplikasyonlar" bilgisiyle çelişir.`},bilgi:[15,16],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k09-q06`,kazanim:9,zorluk:`orta`,soru:`N. gonorrhoeae kültürü: Hasta başı ekim ve %10 CO2'li ortam gerekir. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Sendromik yaklaşım, etken bilinmeden tedaviye başlamayı (ör. ülserli hastalık) sağlar`,B:`Direnç nedeniyle güncel antibiyograma göre tedavi planlanmasını sağlar`,C:`Nongonokokal üretrit/servisit tedavisi azitromisin veya doksisiklin içerir`,D:`Partnerin eş zamanlı tedavisi ile reenfeksiyon önlenir`,E:`Uygun süre tedavi ile komplikasyon (abse, infertilite) riski azalır`},dogru:`B`,aciklama:`Enfeksiyon Hastalıkları düzeneğinde Hasta başı ekim ve %10 CO2'li ortam bilinir. Direnç nedeniyle güncel antibiyograma göre tedavi planlanmasını sağlar. Mekanizma bu sırayla işlediği için beklenen sonuç Direnç nedeniyle güncel antibiyograma göre tedavi planlanmasını olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt B seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Klinik sendromlar sürecine ait bir özelliktir ve n. gonorrhoeae kültürü düzeneğini tanımlamaz.`,B:`Doğru; Direnç nedeniyle güncel antibiyograma göre tedavi planlanmasını sağlar çünkü Hasta başı ekim ve %10 CO2'li ortam gerekir düzeneği bu sonucu üretir.`,C:`Yanlış; bu ifade Nongonokokal enfeksiyon sürecine ait bir özelliktir ve n. gonorrhoeae kültürü düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Trikomoniyazis tedavisi sürecine ait bir özelliktir ve n. gonorrhoeae kültürü düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade PİH intravenöz rejimleri sürecine ait bir özelliktir ve n. gonorrhoeae kültürü düzeneğini tanımlamaz.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k09-q07`,kazanim:9,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Bulaş yolları mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Servisit veya üretritte Gram boyamada intraselüler gram negatif diplokokların görülmesi`,B:`Direkt bakı, nükleik asit amplifikasyon testleri (NAAT) ve kültür kullanılır`,C:`Vajinal akıntı, disparoni, intermenstrüel kanama, pelvik ağrı, ateş`,D:`Bulaş genellikle vajinal, anal veya oral mukoza yoluyla`,E:`Azitromisin 1 g tek doz veya seftriakson 1x250 mg tek`},dogru:`D`,aciklama:`Bulaş genellikle vajinal, anal veya oral mukoza yoluyla. Anneden bebeğe geçiş bilgisi (ör. Fizyopatolojik sıra bu yönde ilerlediğinden Bulaş genellikle vajinal, anal veya oral mukoza varlığında Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt D seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Gram negatif diplokoklar sürecine ait bir özelliktir ve bulaş yolları düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Tanı yöntemleri sürecine ait bir özelliktir ve bulaş yolları düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade PİH klinik ve laboratuvar sürecine ait bir özelliktir ve bulaş yolları düzeneğini tanımlamaz.`,D:`Doğru; Bulaş genellikle vajinal, anal veya oral mukoza yoluyla. Bu mekanizma anneden bebeğe geçiş bilgisi (ör. hbv, hiv, sifilis) sonucunu doğurur.`,E:`Yanlış; bu ifade Şankroid tedavisi sürecine ait bir özelliktir ve bulaş yolları düzeneğini tanımlamaz.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k09-q08`,kazanim:9,zorluk:`orta`,soru:`Neisseria gonorrhoeae bakterisinin klinik örneklerden izolasyonu için kullanılan, çikolata agar temelli olan ve normal floradaki diğer bakteri ve mantarların üremesini engelleyen antibiyotikler içeren selektif besiyeri aşağıdakilerden hangisidir?`,secenekler:{A:`Thayer-Martin besiyeri`,B:`Löwenstein-Jensen besiyeri`,C:`Sabouraud dekstroz agar`,D:`MacConkey agar`,E:`Tiyoglikolatlı sıvı besiyeri`},dogru:`A`,aciklama:`Neisseria gonorrhoeae zor üreyen (fastidious) bir mikroorganizmadır. Genital örneklerdeki zengin florayı baskılamak ve sadece gonokokların üremesine izin vermek için vankomisin (Gram+ ları baskılar), kolistin (Gram- basilleri baskılar), nistatin (mantarları baskılar) ve trimetoprim (Proteus yayılımını baskılar) içeren modifiye Thayer-Martin (veya New York City) selektif besiyeri kullanılır.`,sik_aciklamalari:{A:`Doğrudur; Thayer-Martin besiyeri gonokok izolasyonunda kullanılan klasik selektif besiyeridir.`,B:`Löwenstein-Jensen mikobakteriler (Mycobacterium tuberculosis) içindir.`,C:`Sabouraud agar mantar izolasyonu içindir.`,D:`MacConkey agar enterik gram negatif basiller içindir (gonokok üremez).`,E:`Tiyoglikolat genel anaerob kültür besiyeridir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k09-q09`,kazanim:9,zorluk:`zor`,soru:`Modifiye Thayer-Martin besiyerine eklenen Vankomisin, Kolistin, Nistatin ve Trimetoprim antibiyotiklerinin besiyerindeki selektif görevleri ile ilgili aşağıdaki eşleştirmelerden hangisi DOĞRUDUR?`,secenekler:{A:`Vankomisin: Gram-pozitif bakterileri inhibe eder / Kolistin: Diğer Gram-negatif basilleri inhibe eder / Nistatin: Mantarları inhibe eder / Trimetoprim: Proteus yayılımını önler`,B:`Vankomisin: Mantarları öldürür / Nistatin: Gram-negatifleri öldürür`,C:`Kolistin: Sadece virüsleri inaktive eder`,D:`Trimetoprim: Gonokokların hareketini hızlandırır`,E:`Vankomisin: Gonokokların bölünmesini stimüle eder`},dogru:`A`,aciklama:`Thayer-Martin besiyerinde: Vankomisin Gram-pozitif bakterileri, Kolistin diğer Gram-negatif basilleri, Nistatin Candida gibi mantarları, Trimetoprim ise Proteus türlerinin besiyeri yüzeyinde swarming (yayılma) yapmasını inhibe eder. Bu sayede sadece dirençli olan Neisseria türleri ürer.`,sik_aciklamalari:{A:`Doğrudur; bu dörtlü kombinasyon flora elemanlarını seçici olarak baskılar.`,B:`Vankomisin mantara değil Gram-pozitif bakterilere etkilidir.`,C:`Kolistin antibakteriyeldir, antivirütik değildir.`,D:`Trimetoprim folat sentez inhibitörüdür, Proteus swarming'ini engeller.`,E:`Vankomisin hücre duvarı sentezini bozan bir antibiyotiktir, stimülatör değildir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k09-q10`,kazanim:9,zorluk:`orta`,soru:`Neisseria gonorrhoeae kültürünün inkübasyonu sırasında optimal üremenin sağlanabilmesi için gerekli olan atmosferik çevre koşulu aşağıdakilerden hangisidir?`,secenekler:{A:`35-37 °C sıcaklıkta %3-7 CO2 içeren nemli atmosfer (kapnofilik ortam)`,B:`Tamamen oksijensiz saf anaerobik kavanoz ortamı`,C:`42 °C'de hiperbarik saf oksijen ortamı`,D:`0-4 °C buzdolabı koşullarında karanlık ortam`,E:`50 °C'de kuru sıcak hava fırını`},dogru:`A`,aciklama:`Neisseria gonorrhoeae kapnofilik bir bakteridir; yani üremek için karbondioksit ile zenginleştirilmiş ortama ihtiyaç duyar. İdeal üreme koşulları 35-37 °C sıcaklık, %3-7 (veya %5-10) CO2 içeren nemli atmosferdir (mum kavanozu veya CO2 inkübatörü). Oda havasında veya anaerobik ortamda üremez veya zayıf ürer.`,sik_aciklamalari:{A:`Doğrudur; 35-37 °C ve %3-7 CO2 (kapnofilik nemli ortam) gonokok üremesi için şarttır.`,B:`Gonokok zorunlu aerobtut, kesin anaerobik ortamda üremez.`,C:`42 °C ve saf oksijen bakteriyi öldürür.`,D:`Soğuk ve kuruluk gonokokları hızla inaktive eder.`,E:`50 °C kuru hava bakteriyi sterilize eder.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k09-q11`,kazanim:9,zorluk:`orta`,soru:`Gonore şüphesiyle hastadan alınan üretral veya servikal sürüntü örneğinin laboratuvara ulaştırılması sürecinde gonokokların canlılığını korumak için aşağıdakilerden hangisi YAPILMALIDIR?`,secenekler:{A:`Örnek kurumaya ve soğuğa karşı korunmalı, Stuart veya Amies gibi uygun transport besiyerinde bekletilmeden hızla ekilmelidir`,B:`Örnek derhal -20 °C derin dondurucuya konmalıdır`,C:`Sürüntü pamuklu çubukla açık havada güneşte 2 saat kurutulmalıdır`,D:`Örnek saf alkol içine daldırılarak gönderilmelidir`,E:`Sürüntü alındıktan sonra 24 saat oda havasında çıplak bekletilmelidir`},dogru:`A`,aciklama:`Neisseria gonorrhoeae kurumaya, soğuğa ve pH değişikliklerine karşı aşırı derecede hassastır (labildir). Örnek alındıktan sonra asla buzdolabına konmamalı ve kurumasına izin verilmemelidir. Mümkünse doğrudan hasta başında besiyerine ekilmeli veya Stuart/Amies taşıma besiyeri kullanılarak en kısa sürede laboratuvara ulaştırılmalıdır.`,sik_aciklamalari:{A:`Doğrudur; gonokoklar hassas olduğundan transport besiyeriyle hızla ekilmeli, soğuk ve kuruluktan korunmalıdır.`,B:`Dondurucu bakteriyi öldürür.`,C:`Kuruluk bakteriyi dakikalar içinde inaktive eder.`,D:`Alkol bakteriyi fikse eder ve öldürür.`,E:`Oda havasında kuruyan örnekte kültür üremez.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k09-q12`,kazanim:9,zorluk:`zor`,soru:`Kültürde üreyen Neisseria gonorrhoeae suşunun laboratuvarda ön tanımlamasında kullanılan iki temel biyokimyasal özellik aşağıdakilerin hangisinde DOĞRU verilmiştir?`,secenekler:{A:`Oksidaz pozitifliği ve karbonhidrat fermantasyonunda sadece GLUKOZU fermente etmesi (maltoz ve sükrozu fermente etmemesi)`,B:`Katalaz negatifliği ve sadece LAKTOZU fermente etmesi`,C:`Oksidaz negatifliği ve koagülaz pozitifliği`,D:`Üreaz pozitifliği ve indol üretimi`,E:`Eskülin hidrolizi ve PYR pozitifliği`},dogru:`A`,aciklama:`Neisseria cinsinin tüm üyeleri gibi N. gonorrhoeae da oksidaz pozitif ve katalaz pozitiftir. Tür düzeyinde ayırt etmede karbonhidrat oksidasyon/fermantasyon testleri kullanılır: Neisseria gonorrhoeae sadece Glukozu kullanır (Glukoz +, Maltoz -, Sükroz -). Neisseria meningitidis ise hem Glukoz hem Maltozu kullanır (Glukoz +, Maltoz +).`,sik_aciklamalari:{A:`Doğrudur; oksidaz pozitiftir ve karbonhidratlardan sadece glukozu okside eder.`,B:`Neisseria laktozu fermente etmez; katalaz pozitiftir.`,C:`Oksidaz pozitiftir; koagülaz S. aureus'a özgüdür.`,D:`Üreaz Ureaplasma ve Proteus için tipiktir.`,E:`Eskülin ve PYR enterokokların testidir.`},bilgi:[9],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:10,metin:`Trikomoniyazis tedavisini, partner tedavisini ve cinsel perhiz süresini bilmek`,sorular:[{id:`k1-17-q28`,kazanim:10,zorluk:`kolay`,soru:`Trikomoniyazis tedavisinde önerilen rejim hangisidir?`,secenekler:{A:`Flukonazol 150 mg tek doz`,B:`Seftriakson 250 mg tek doz`,C:`Asiklovir 5 gün`,D:`Metronidazol 2 g tek doz`,E:`Penisilin G`},dogru:`D`,aciklama:`Trikomoniyazis tedavisi metronidazol 2 g tek dozdur; gebede de aynıdır.`,sik_aciklamalari:{A:`Kandida tedavisidir.`,B:`Gonore tedavisinin parçasıdır.`,C:`Herpes tedavisidir; bu nedenle doğru seçenek değildir.`,D:`Doğru: önerilen tedavidir.`,E:`Sifilis tedavisidir.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-17-q29`,kazanim:10,zorluk:`orta`,soru:`Trikomoniyazis tedavisinde cinsel perhiz süresi ne kadardır?`,secenekler:{A:`6 ay`,B:`Perhiz gerekmez`,C:`Tedavi süresince ve sonrasında 7 gün`,D:`1 gün`,E:`1 yıl`},dogru:`C`,aciklama:`Partner tedavisi yapılır ve tedavi ile sonrasında 7 gün cinsel perhiz önerilir.`,sik_aciklamalari:{A:`Gereksiz uzunluktadır.`,B:`Perhiz gereklidir; bu nedenle doğru seçenek değildir.`,C:`Doğru: önerilen süredir.`,D:`Yetersizdir; bu nedenle doğru seçenek değildir.`,E:`Gereksiz uzunluktadır.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-17-q30`,kazanim:10,zorluk:`zor`,soru:`Trikomoniyazis tedavisinde partnerin eş zamanlı tedavisinin amacı hangisidir?`,secenekler:{A:`Partnerin hiçbir zaman enfekte olmaması`,B:`İlaç direncinin artırılması`,C:`Tedavi süresinin uzatılması`,D:`Gebelikte tedavinin kontrendike olması`,E:`Reenfeksiyonun önlenmesi`},dogru:`E`,aciklama:`Partner eş zamanlı tedavi edilmezse 'ping-pong' reenfeksiyon gelişir.`,sik_aciklamalari:{A:`Partner sıklıkla enfektedir.`,B:`Direnç artırılması amaç değildir.`,C:`Süre uzatılmaz; bu nedenle doğru seçenek değildir.`,D:`Gebede aynı tedavi uygulanır.`,E:`Doğru: reenfeksiyon önlenir.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k10-q04`,kazanim:10,zorluk:`orta`,soru:`40 yaşındaki bir hasta yıllardır süren yakınmalarla başvuran ve fizik muayenede tipik bulguları saptanan bir hastada hekime başvuruyor. Değerlendirmede "Serum fizyolojik ile direkt bakıda hareketli trofozoitlerin görülmesi trikomoniyazis tanısını koydurur." bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "Trikomoniyazis tedavisini, partner tedavisini ve cinsel perhiz süresini bilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Serum fizyolojik ile direkt bakıda hareketli trofozoitlerin görülmesi trikomoniyazis tanısını… ilkesinin tam tersi geçerlidir ve Partnerin eş zamanlı tedavisi ile reenfeksiyon önlenir. gözlenmez`,B:`Serum fizyolojik ile direkt bakıda hareketli trofozoitlerin görülmesi trikomoniyazis tanısını koydurur. Bu nedenle Tanı doğrulanınca metronidazol tedavisi ve partner tedavisi başlanır.`,C:`Bu tablodan sorumlu temel mekanizma Trikomoniyazis tedavisi olup "Trikomoniyazis tedavisini, partner tedavisini ve cinsel…" ile ilişkisizdir`,D:`Bulgular "Trikomoniyazis tedavisini, partner tedavisini ve cinsel perhiz…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Trofozoit (SF)" ile açıklanamaz`},dogru:`B`,aciklama:`Robbins/Harrison mantığıyla: Serum fizyolojik ile direkt bakıda hareketli trofozoitlerin görülmesi trikomoniyazis tanısını koydurur. Doğrudan sonucu "Tanı doğrulanınca metronidazol tedavisi ve partner tedavisi başlanır." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Trofozoit (SF)" bilgisiyle çelişir.`,B:`Doğru; Serum fizyolojik ile direkt bakıda hareketli trofozoitlerin görülmesi trikomoniyazis tanısını koydurur. Bu…`,C:`Yanlış; ders paketindeki "Trofozoit (SF)" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Trofozoit (SF)" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Trofozoit (SF)" bilgisiyle çelişir.`},bilgi:[7,18],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k10-q05`,kazanim:10,zorluk:`zor`,soru:`Farklı bir hasta tedavi seçeneğinin tartışıldığı farklı bir klinik senaryoda ele alınıyor. Öyküde "Trikomoniyazis tedavisi" vurgulanıyor ve hekim "Trikomoniyazis tedavisini, partner tedavisini ve cinsel perhiz süresini bilmek" kazanımındaki "Metronidazol 2 g tek doz; gebede de aynı; partner tedavisi; tedavi ve sonrasında 7 gün cinsel perhiz." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Partnerin eş zamanlı tedavisi ile reenfeksiyon önlenir. hiçbir koşulda gözlenmez ve Trofozoit (SF) tek belirleyicidir`,B:`Bu süreçte "Trofozoit (SF)" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Partnerin eş zamanlı tedavisi ile reenfeksiyon önlenir. Çünkü Metronidazol 2 g tek doz; gebede de aynı; partner tedavisi; tedavi ve sonrasında 7 gün cinsel perhiz.`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Trikomoniyazis tedavisi" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Trikomoniyazis tedavisini, partner tedavisini ve cinsel perhiz…" yalnızca teorik bir bilgidir`},dogru:`C`,aciklama:`Guyton/Robbins bütünlüğünde: Metronidazol 2 g tek doz; gebede de aynı; partner tedavisi; tedavi ve sonrasında 7 gün cinsel perhiz. sonucu "Partnerin eş zamanlı tedavisi ile reenfeksiyon önlenir." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Trofozoit (SF)" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Trofozoit (SF)" bilgisiyle çelişir.`,C:`Doğru; Partnerin eş zamanlı tedavisi ile reenfeksiyon önlenir. Çünkü Metronidazol 2 g tek doz; gebede de aynı;…`,D:`Yanlış; ders paketindeki "Trofozoit (SF)" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Trofozoit (SF)" bilgisiyle çelişir.`},bilgi:[7,18],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k10-q06`,kazanim:10,zorluk:`orta`,soru:`Trikomoniyazis tedavisi: Metronidazol 2 g tek doz. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`BV tanısı Amsel kriterleriyle konur`,B:`İnfertilite, ektopik gebelik ve kronik pelvik ağrı gibi sekellerle sonuçlanabilir`,C:`Partnerin eş zamanlı tedavisi ile reenfeksiyon önlenir`,D:`Direnç nedeniyle monoterapi yerine kombine tedavi zorunludur`,E:`Tedavi ilk atak ve tekrarlayan ataklar için ayrı planlanır`},dogru:`C`,aciklama:`Metronidazol 2 g tek doz. Partnerin eş zamanlı tedavisi ile reenfeksiyon önlenir. Fizyopatolojik sıra bu yönde ilerlediğinden Metronidazol 2 g tek doz varlığında Partnerin eş zamanlı tedavisi ile reenfeksiyon önlenir beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt C seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Clue cell (SF) sürecine ait bir özelliktir ve trikomoniyazis tedavisi düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Pelvik inflamatuvar hastalık sürecine ait bir özelliktir ve trikomoniyazis tedavisi düzeneğini tanımlamaz.`,C:`Doğru; Partnerin eş zamanlı tedavisi ile reenfeksiyon önlenir çünkü Metronidazol 2 g tek doz düzeneği bu sonucu üretir.`,D:`Yanlış; bu ifade Gonokok direnç mekanizmaları sürecine ait bir özelliktir ve trikomoniyazis tedavisi düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Genital herpes tanısı sürecine ait bir özelliktir ve trikomoniyazis tedavisi düzeneğini tanımlamaz.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k10-q07`,kazanim:10,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Anogenital siğil mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Üretral irritasyon, kaşıntı ve dizüri üretrit triadını oluşturur`,B:`Metronidazol 2 g tek doz`,C:`Sefoksitin 4x2 g + doksisiklin 2x100 mg veya ampisilin/sulbaktam 4x3`,D:`Bulaş genellikle vajinal, anal veya oral mukoza yoluyla`,E:`Kondiloma akuminata`},dogru:`E`,aciklama:`Kondiloma akuminata. Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur. Bu ilişki Enfeksiyon Hastalıkları fizyolojisinin temel düzeneklerinden biridir: Kondiloma akuminata doğrudan Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt E seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Üretral akıntı ve üretrit sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Trikomoniyazis tedavisi sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade PİH intravenöz rejimleri sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Bulaş yolları sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,E:`Doğru; Kondiloma akuminata. Bu mekanizma tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif sonucunu doğurur.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k10-q08`,kazanim:10,zorluk:`orta`,soru:`Trichomonas vaginalis enfeksiyonu saptanan gebe olmayan bir kadın hastada güncel CDC ve DSÖ rehberlerine göre önerilen İLK SEÇENEK standart tedavi rejimi aşağıdakilerden hangisidir?`,secenekler:{A:`Metronidazol 2x500 mg oral yoldan 7 gün`,B:`Siprofloksasin 500 mg tek doz`,C:`Azitromisin 1 g oral tek doz`,D:`Seftriakson 500 mg IM tek doz`,E:`Doksisiklin 2x100 mg oral 14 gün`},dogru:`A`,aciklama:`CDC güncel rehberlerinde kadınlarda trikomoniyazis tedavisinde metronidazol 2x500 mg oral 7 gün rejiminin, eski tek doz 2 g metronidazol rejimine kıyasla kür oranlarını belirgin artırdığı gösterilmiş ve ilk seçenek olarak 7 günlük tedavi (Metronidazol 2x500 mg/gün 7 gün) önerilmiştir (Alternatif olarak tinidazol 2 g tek doz).`,sik_aciklamalari:{A:`Doğrudur; kadınlarda güncel standart rejim Metronidazol 2x500 mg oral 7 gündür.`,B:`Siprofloksasin florokinolondur, parazitlere etkisizdir.`,C:`Azitromisin klamidya ilacıdır, trikomonasa etkisizdir.`,D:`Seftriakson gonore ilacıdır.`,E:`Doksisiklin klamidya/mikoplazma ilacıdır.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k10-q09`,kazanim:10,zorluk:`orta`,soru:`Trikomoniyazis tanısı konulan bir hastanın tedavisinde cinsel partnerin yönetimi ile ilgili aşağıdaki kurallardan hangisi KESİNLİKLE uygulanmalıdır?`,secenekler:{A:`Cinsel partner asemptomatik olsa dahi mutlaka eş zamanlı olarak tedavi edilmelidir`,B:`Cinsel partner sadece üretral akıntısı varsa tedaviye alınmalıdır`,C:`Cinsel partnerin tedavi edilmesine gerek yoktur, hastalık sadece kadınlarda bulaşıcıdır`,D:`Partner tedavisinde sadece topikal nistatin krem yeterlidir`,E:`Partner ancak 6 ay sonra antikor testi pozitif çıkarsa tedavi edilmelidir`},dogru:`A`,aciklama:`Trichomonas vaginalis'te erkek partnerler çoğunlukla asemptomatik taşıyıcıdır. İndeks vaka tedavi edilse bile tedavi edilmeyen partner hastalığı tekrar bulaştırır ('ping-pong' enfeksiyonu). Bu nedenle cinsel partnerler semptomu olsun ya da olmasın MUTLAKA eş zamanlı olarak tedavi edilmelidir.`,sik_aciklamalari:{A:`Doğrudur; re-enfeksiyonu önlemek için asemptomatik partner de eş zamanlı tedavi edilmelidir.`,B:`Erkeklerin %70-80'i asemptomatiktir; sadece semptomatik olanları tedavi etmek tedaviyi başarısız kılar.`,C:`Erkekler taşıyıcıdır ve bulaştırıcıdır.`,D:`Nistatin mantar ilacıdır, trikomonasa etkisizdir.`,E:`Seroloji beklenmez, epidemiyolojik tedavi esastır.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k10-q10`,kazanim:10,zorluk:`orta`,soru:`Trikomoniyazis tedavisi alan bir hasta ve partneri, tedavinin tamamlanması ve yeniden bulaşmanın (re-enfeksiyon) engellenmesi için ne kadar süreyle cinsel ilişkiden kaçınmalıdır (cinsel perhiz)?`,secenekler:{A:`Hem hasta hem de partneri tedaviyi tamamlayana ve semptomlar tamamen gerileyene kadar (en az 7 gün)`,B:`İlk hapı içtikten sonraki 1 saat boyunca`,C:`Tedavinin başlamasından itibaren tam 6 ay boyunca`,D:`Cinsel perhize gerek yoktur, tedavi sırasında prezervatifsiz ilişki serbesttir`,E:`Sadece kadın adet görene kadar`},dogru:`A`,aciklama:`CYBH kılavuzlarına göre trikomoniyazis tedavisi alan bireyler ve partnerleri, tüm ilaç dozları bitene ve her iki partnerin de semptomları tamamen kaybolana kadar cinsel perhize uymalıdır (7 günlük rejimde 7 gün; tek doz tedavide en az 7 gün cinsel ilişkiden kaçınılmalıdır).`,sik_aciklamalari:{A:`Doğrudur; tedavi tamamlanana ve semptomlar geçene kadar (en az 7 gün) cinsel ilişki yasaklanmalıdır.`,B:`1 saatlik süre yetersizdir, ilaç doku seviyesine ulaşıp paraziti temizlemelidir.`,C:`6 aylık süre gereksiz derecede uzundur.`,D:`Perhiz yapılmazsa enfeksiyon devam eder.`,E:`Menstrüasyonla ilişkili bir kural değildir.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k10-q11`,kazanim:10,zorluk:`zor`,soru:`Metronidazol veya Tinidazol tedavisi alan bir hastanın tedavi süresince ve tedavi bittikten sonra en az 24-72 saat boyunca ALKOL TÜKETMEMESİ gerektiğinin farmakolojik nedeni nedir?`,secenekler:{A:`Asetaldehit dehidrogenaz enzim inhibisyonu sonucu gelişen disülfiram benzeri reaksiyon (bulantı, kusma, yüzde kızarma, taşikardi, hipotansiyon)`,B:`Sitokrom P450 indüksiyonu ile ilacın dakikalar içinde idrarla atılması`,C:`Alkolün metronidazol ile kimyasal birleşerek böbrek taşları oluşturması`,D:`Alkolün Trichomonas trofozoitlerini antibiyotiklere karşı hiperdirençli hale getirmesi`,E:`GABA reseptör blokajı ile irreversibl koma gelişimi`},dogru:`A`,aciklama:`Metronidazol ve tinidazol, karaciğerde etanol metabolizmasında görev alan 'asetaldehit dehidrogenaz' enzimini inhibe eder. Alkol alındığında toksik ara ürün olan asetaldehit birikir ve 'disülfiram benzeri reaksiyon' (şiddetli bulantı, kusma, taşikardi, yüzde ani flushing/kızarma, terleme, zonklayıcı baş ağrısı ve hipotansiyon) ortaya çıkar. Bu nedenle metronidazol bittikten sonra en az 24 saat, tinidazol bittikten sonra en az 72 saat alkol alınmamalıdır.`,sik_aciklamalari:{A:`Doğrudur; asetaldehit dehidrogenaz inhibisyonu sonucu disülfiram benzeri reaksiyon gelişir.`,B:`Primer sorun asetaldehit birikimidir, CYP indüksiyonu değildir.`,C:`Böbrek taşı oluşturmaz.`,D:`Parazit direnci mekanizması değildir.`,E:`GABA blokaj koması değildir.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k10-q12`,kazanim:10,zorluk:`orta`,soru:`Gebelikte saptanan semptomatik Trichomonas vaginalis enfeksiyonunun tedavisinde güvenlik profili kanıtlanmış yaklaşım aşağıdakilerden hangisidir?`,secenekler:{A:`Gebeliğin tüm trimesterlerinde oral metronidazol güvenle kullanılabilir`,B:`Metronidazol gebelikte kesin kontrendikedir, sadece doğumdan sonra tedavi verilir`,C:`Gebelikte sadece yüksek doz siprofloksasin verilir`,D:`Gebelere sadece doksisiklin verilmelidir`,E:`Hiçbir tedavi verilmez, sadece vajinal asetik asit lavajı yapılır`},dogru:`A`,aciklama:`Geniş epidemiyolojik çalışmalarda metronidazolün teratojenik veya mutajenik etkisi gösterilmemiştir. CDC ve obstetri cemiyetleri, semptomatik trikomoniyazisi olan gebelerde prematüre eylem ve erken membran rüptürü gibi enfeksiyona bağlı obstetrik riskleri azaltmak amacıyla gebeliğin tüm trimesterlerinde oral metronidazolün güvenle kullanılabileceğini bildirmektedir.`,sik_aciklamalari:{A:`Doğrudur; semptomatik gebelerde metronidazol tüm trimesterlerde güvenle kullanılabilir.`,B:`Kontrendike değildir; tedavi edilmeyen trikomonas erken doğum riski doğurur.`,C:`Siprofloksasin parazite etkisizdir ve gebelikte kıkırdak toksisitesi nedeniyle kaçınılır.`,D:`Doksisiklin gebelikte diş ve kemik gelişimi bozukluğu nedeniyle kontrendikedir.`,E:`Vajinal lavaj enfeksiyonu tedavi etmez, asendan riski artırır.`},bilgi:[10],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:11,metin:`Chlamydia trachomatis enfeksiyonu ve lenfogranüloma venereum tedavisini bilmek`,sorular:[{id:`k1-17-q31`,kazanim:11,zorluk:`kolay`,soru:`Chlamydia trachomatis enfeksiyonunda standart tedavi hangisidir?`,secenekler:{A:`Metronidazol 2 g tek doz`,B:`Azitromisin 1 g tek doz`,C:`Flukonazol`,D:`Asiklovir`,E:`İmikimod`},dogru:`B`,aciklama:`Klamidya tedavisi azitromisin 1 g tek dozdur; alternatif levofloksasin 7 gündür.`,sik_aciklamalari:{A:`Trikomonas tedavisidir.`,B:`Doğru: standart tedavidir.`,C:`Antifungaldir; bu nedenle doğru seçenek değildir.`,D:`Antiviraldir; bu nedenle doğru seçenek değildir.`,E:`Siğil tedavisidir; bu nedenle doğru seçenek değildir.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-17-q32`,kazanim:11,zorluk:`orta`,soru:`Gebe kadında klamidya enfeksiyonunun tedavisi ve izlemi ile ilgili hangisi doğrudur?`,secenekler:{A:`Doksisiklin ilk tercihtir`,B:`Levofloksasin tercih edilir`,C:`Tedavi doğuma kadar ertelenir`,D:`Kontrol gerekmez`,E:`Azitromisin veya eritromisin verilir; 3–4 hafta sonra kontrol yapılır`},dogru:`E`,aciklama:`Gebede fetal güvenlik açısından azitromisin/eritromisin seçilir ve 3–4 hafta sonra kontrol yapılır.`,sik_aciklamalari:{A:`Doksisiklin gebelikte kullanılmaz.`,B:`Kinolonlar gebede kontrendikedir.`,C:`Tedavi ertelenmez; bu nedenle doğru seçenek değildir.`,D:`Kontrol önerilir; bu nedenle doğru seçenek değildir.`,E:`Doğru: gebede tedavi yaklaşımıdır.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-17-q33`,kazanim:11,zorluk:`zor`,soru:`Lenfogranüloma venereumun klinik özellikleri ile ilgili hangisi doğrudur?`,secenekler:{A:`Lenfadenopati yapmaz`,B:`Viral bir enfeksiyondur`,C:`C. trachomatis'e bağlıdır; tek/bilateral lenfadenopati, papül ve herpes benzeri ülserle seyreder ve bölgesel LAP ayırıcı tanısında düşünülmelidir`,D:`Etkeni H. ducreyi'dir`,E:`Yalnızca vajinal akıntıyla seyreder`},dogru:`C`,aciklama:`LGV, C. trachomatis'in özel serovarlarıyla oluşan ve belirgin bölgesel lenfadenopatiyle seyreden bir CYBH'dir.`,sik_aciklamalari:{A:`Belirgin lenfadenopati yapar.`,B:`Bakteriyel etkenlidir.`,C:`Doğru: LGV'nin klinik tablosudur.`,D:`H. ducreyi şankroid etkenidir.`,E:`Ülser ve lenfadenopatiyle seyreder.`},bilgi:[19,20],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k11-q04`,kazanim:11,zorluk:`orta`,soru:`47 yaşındaki bir hasta akut başvuru yapan ve laboratuvar-görüntüleme bulguları birlikte değerlendirilen bir olguda hekime başvuruyor. Değerlendirmede "Azitromisin 1 g tek doz; alternatif levofloksasin 1x500 mg 7 gün; gebede azitromisin/eritromisin ve 3-4 hafta sonra kontrol." bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "Chlamydia trachomatis enfeksiyonu ve lenfogranüloma venereum tedavisini bilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Azitromisin 1 g tek doz; alternatif levofloksasin 1x500 mg 7 gün; gebede azitromisin/eritromisin ve… ilkesinin tam tersi geçerlidir ve Gebede uygun ilaç seçimi fetal güvenliği korur. gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Klamidya tedavisi olup "Chlamydia trachomatis enfeksiyonu ve lenfogranüloma…" ile ilişkisizdir`,C:`Azitromisin 1 g tek doz; alternatif levofloksasin 1x500 mg 7 gün; gebede azitromisin/eritromisin ve 3-4 hafta sonra kontrol. Bu nedenle Gebede uygun ilaç seçimi fetal güvenliği korur.`,D:`Bulgular "Chlamydia trachomatis enfeksiyonu ve lenfogranüloma venereum…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Klamidya tedavisi" ile açıklanamaz`},dogru:`C`,aciklama:`Robbins/Harrison mantığıyla: Azitromisin 1 g tek doz; alternatif levofloksasin 1x500 mg 7 gün; gebede azitromisin/eritromisin ve 3-4 hafta sonra kontrol. Doğrudan sonucu "Gebede uygun ilaç seçimi fetal güvenliği korur." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Klamidya tedavisi" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Klamidya tedavisi" bilgisiyle çelişir.`,C:`Doğru; Azitromisin 1 g tek doz; alternatif levofloksasin 1x500 mg 7 gün; gebede azitromisin/eritromisin ve 3-4 hafta…`,D:`Yanlış; ders paketindeki "Klamidya tedavisi" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Klamidya tedavisi" bilgisiyle çelişir.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k11-q05`,kazanim:11,zorluk:`zor`,soru:`Farklı bir hasta hastalığın seyri ve prognozunun değerlendirildiği ayrı bir vakada ele alınıyor. Öyküde "Klamidya tedavisi" vurgulanıyor ve hekim "Chlamydia trachomatis enfeksiyonu ve lenfogranüloma venereum tedavisini bilmek" kazanımındaki "Azitromisin 1 g tek doz; alternatif levofloksasin 1x500 mg 7 gün; gebede azitromisin/eritromisin ve 3-4 hafta sonra kontrol." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Gebede uygun ilaç seçimi fetal güvenliği korur. hiçbir koşulda gözlenmez ve Klamidya tedavisi tek belirleyicidir`,B:`Bu süreçte "Klamidya tedavisi" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Benzer tabloların tamamı aynı nedene bağlıdır; "Klamidya tedavisi" ayırıcı tanıda gereksizdir`,D:`Gebede uygun ilaç seçimi fetal güvenliği korur. Çünkü Azitromisin 1 g tek doz; alternatif levofloksasin 1x500 mg 7 gün; gebede azitromisin/eritromisin ve 3-4 hafta…`,E:`Bu olguda izlem gerekmez; "Chlamydia trachomatis enfeksiyonu ve lenfogranüloma venereum…" yalnızca teorik bir bilgidir`},dogru:`D`,aciklama:`Guyton/Robbins bütünlüğünde: Azitromisin 1 g tek doz; alternatif levofloksasin 1x500 mg 7 gün; gebede azitromisin/eritromisin ve 3-4 hafta sonra kontrol. sonucu "Gebede uygun ilaç seçimi fetal güvenliği korur." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Klamidya tedavisi" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Klamidya tedavisi" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Klamidya tedavisi" bilgisiyle çelişir.`,D:`Doğru; Gebede uygun ilaç seçimi fetal güvenliği korur. Çünkü Azitromisin 1 g tek doz; alternatif levofloksasin 1x500…`,E:`Yanlış; ders paketindeki "Klamidya tedavisi" bilgisiyle çelişir.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k11-q06`,kazanim:11,zorluk:`orta`,soru:`Klamidya tedavisi: Azitromisin 1 g tek doz. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Gonore düşünülen hastada kombine tedavi (seftriakson + azitromisin) başlanır`,B:`NAAT yüksek duyarlılığıyla ilk seçenek`,C:`Uygun olguda ayaktan tedavi, komplike olguda IV tedavi seçilir`,D:`Gebede uygun ilaç seçimi fetal güvenliği korur`,E:`Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur`},dogru:`D`,aciklama:`Azitromisin 1 g tek doz. Gebede uygun ilaç seçimi fetal güvenliği korur. Bu ilişki Enfeksiyon Hastalıkları fizyolojisinin temel düzeneklerinden biridir: Azitromisin 1 g tek doz doğrudan Gebede uygun ilaç seçimi fetal güvenliği korur doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt D seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Gram negatif diplokoklar sürecine ait bir özelliktir ve klamidya tedavisi düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Tanı yöntemleri sürecine ait bir özelliktir ve klamidya tedavisi düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade PİH yatış endikasyonları sürecine ait bir özelliktir ve klamidya tedavisi düzeneğini tanımlamaz.`,D:`Doğru; Gebede uygun ilaç seçimi fetal güvenliği korur çünkü Azitromisin 1 g tek doz düzeneği bu sonucu üretir.`,E:`Yanlış; bu ifade Anogenital siğil sürecine ait bir özelliktir ve klamidya tedavisi düzeneğini tanımlamaz.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k11-q07`,kazanim:11,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Anogenital siğil mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Kondiloma akuminata`,B:`Skrotal ağrı-ödem ve ağrılı ejakülasyon ile seyreder`,C:`Penisilinaz üretimi (penisilin ve dar spektrumlu sefalosporin hidrolizi), PBP değişimi,`,D:`NAAT ile konur`,E:`%10 KOH eklenmesiyle ortaya çıkan amin kokusu bakteriyel vajinozis için`},dogru:`A`,aciklama:`Enfeksiyon Hastalıkları düzeneğinde Kondiloma akuminata bilinir. Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur. Mekanizma bu sırayla işlediği için beklenen sonuç Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt A seçeneğidir.`,sik_aciklamalari:{A:`Doğru; Kondiloma akuminata. Bu mekanizma tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif sonucunu doğurur.`,B:`Yanlış; bu ifade Epididimit/prostatit sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Gonokok direnç mekanizmaları sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Genital herpes tanısı sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Amin kokusu testi (KOH) sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k11-q08`,kazanim:11,zorluk:`orta`,soru:`Komplike olmayan ürogenital Chlamydia trachomatis enfeksiyonunda (servisit/üretrit) güncel CDC rehberlerinin önerdiği İLK SEÇENEK tedavi aşağıdakilerden hangisidir?`,secenekler:{A:`Doksisiklin 100 mg oral günde 2 kez, 7 gün`,B:`Penisilin G intramusküler tek doz`,C:`Metronidazol 500 mg günde 2 kez, 7 gün`,D:`Siprofloksasin 500 mg tek doz`,E:`Gentamisin tek doz intramusküler`},dogru:`A`,aciklama:`Güncel CDC rehberlerinde ürogenital ve rektal Chlamydia trachomatis enfeksiyonunun ilk seçenek tedavisi Doksisiklin (oral 2x100 mg, 7 gün) olarak güncellenmiştir. Doksisiklin özellikle rektal klamidya tutulumunda azitromisinden belirgin üstün bulunmuştur. Azitromisin 1 g tek doz ise uyum sorunu olan veya gebelik durumunda alternatif olarak yer almaktadır.`,sik_aciklamalari:{A:`Doğrudur; klamidyanın ilk basamak güncel standart tedavisi Doksisiklin 2x100 mg 7 gündür.`,B:`Penisilin G sifiliz ilacıdır; klamidya hücresine etkisizdir.`,C:`Metronidazol anaerob ve trikomonas ilacıdır.`,D:`Siprofloksasin klamidyada tercih edilmez.`,E:`Gentamisin klamidyada standart tedavi değildir.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k11-q09`,kazanim:11,zorluk:`orta`,soru:`Gebelikte saptanan Chlamydia trachomatis ürogenital enfeksiyonunun tedavisinde, doksisiklinin kemik/diş toksisitesi nedeniyle kontrendike olması durumunda İLK SEÇENEK tedavi aşağıdakilerden hangisidir?`,secenekler:{A:`Azitromisin 1 g oral tek doz`,B:`Tetrasiklin 4x500 mg 14 gün`,C:`Siprofloksasin 2x500 mg 7 gün`,D:`Kloramfenikol oral 10 gün`,E:`Streptomisin intramusküler`},dogru:`A`,aciklama:`Tetrasiklinler (doksisiklin dahil) fetal dişlerde sarı-kahverengi kalıcı renk değişikliğine ve kemik gelişiminin baskılanmasına yol açtığı için gebelikte kesinlikle kontrendikedir. Gebelikte klamidya enfeksiyonunun birinci seçenek güvenli tedavisi Azitromisin (1 g oral tek doz) veya alternatif olarak amoksisilindir.`,sik_aciklamalari:{A:`Doğrudur; gebelikte klamidyanın ilk seçenek güvenli tedavisi Azitromisin 1 g tek dozdur.`,B:`Tetrasiklin gebelikte kontrendikedir.`,C:`Florokinolonlar kıkırdak hasarı riskiyle gebelikte kaçınılır.`,D:`Kloramfenikol 'gri bebek sendromu' riski taşır.`,E:`Streptomisin 8. kranial sinir ototoksisitesi riski taşır.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k11-q10`,kazanim:11,zorluk:`zor`,soru:`Chlamydia trachomatis'in L1, L2 ve L3 serovarları tarafından oluşturulan, inguinal ligamentin yukarısında ve aşağısında lenf bezi büyümesiyle karakterize 'oluk bulgusu' (groove sign) ve fistülize bubonlar yapan Lenfogranüloma Venereum (LGV) tedavisinde önerilen rejim aşağıdakilerden hangisidir?`,secenekler:{A:`Doksisiklin 100 mg oral günde 2 kez, tam 21 GÜN`,B:`Doksisiklin 100 mg oral tek doz`,C:`Seftriakson 500 mg tek doz IM`,D:`Penisilin G 2.4 milyon ünite IM tek doz`,E:`Metronidazol 500 mg 3 gün`},dogru:`A`,aciklama:`Lenfogranüloma Venereum (LGV), lenfoid dokuları invaze eden L1-L3 serovarlarıyla oluşur. Derin doku ve lenfatik invazyonu nedeniyle standart 7 günlük tedavi yetersizdir; kılavuzlar Doksisiklin 2x100 mg/gün rejiminin en az 21 GÜN boyunca verilmesini şart koşar. Alternatif olarak eritromisin 4x500 mg 21 gün verilebilir.`,sik_aciklamalari:{A:`Doğrudur; LGV'de lenfatik derin enfeksiyon nedeniyle Doksisiklin 21 GÜN süreyle verilmelidir.`,B:`Tek doz doksisiklin LGV'de tamamen yetersizdir.`,C:`Seftriakson gonore ilacıdır, klamidya hücre içi yapısına etkisizdir.`,D:`Penisilin G sifiliz ilacıdır.`,E:`Metronidazol LGV'ye etkisizdir.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k11-q11`,kazanim:11,zorluk:`zor`,soru:`Chlamydia trachomatis'in hücre biyolojisinde 'Elementer Cisimcik' (EB) ile 'Retiküler Cisimcik' (RB) formlarının özellikleri karşılaştırıldığında aşağıdakilerden hangisi DOĞRUDUR?`,secenekler:{A:`Elementer cisimcik hücre dışı enfeksiyöz formdur; Retiküler cisimcik ise hücre içinde çoğalan (replike olan) metabolik aktif formdur`,B:`Elementer cisimcik hücre içinde bölünür; Retiküler cisimcik hücre dışına dökülür`,C:`Her iki form da hücre dışında spor gibi yüzyıllarca yaşayabilir`,D:`Retiküler cisimcik Gram-pozitif kapsüllü bir bakteridir`,E:`Elementer cisimcik mitokondriye sahip tek bakteri formudur`},dogru:`A`,aciklama:`Chlamydia türleri bifazik yaşam döngüsüne sahiptir: 1) Elementer Cisimcik (EB): Küçük, yoğun, sert çeperli, metabolik olarak inaktif ancak hücre dışında stabil ve ENFEKSİYÖZ formdur; konak hücresine endositozla girer. 2) Retiküler Cisimcik (RB): Hücre içinde fagozomda (inklüzyon) oluşan, metabolik olarak aktif, konak ATP'sini kullanan ve ikiye bölünerek REPLİKE OLAN non-enfeksiyöz formdur.`,sik_aciklamalari:{A:`Doğrudur; Elementer cisimcik enfeksiyöz hücre dışı form, Retiküler cisimcik hücre içi replikatif formdur.`,B:`Tam tersidir; bölünen form retiküler cisimciktir.`,C:`Klamidya hücre dışında uzun süre kalamaz, zorunlu hücre içidir.`,D:`Klamidyalar gram negatif zar yapısına sahiptir.`,E:`Bakterilerde mitokondri bulunmaz.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k11-q12`,kazanim:11,zorluk:`orta`,soru:`Chlamydia trachomatis tedavisinde beta-laktam antibiyotiklerin (örneğin sefalosporinler) KLİNİK OLARAK TERCİH EDİLMEMESİNİN temel farmakolojik/biyolojik nedeni nedir?`,secenekler:{A:`Klamidyanın zorunlu hücre içi patojen olması ve hücre duvarında klasik kalın peptidoglikan tabakasının bulunmayışı nedeniyle hücre içine yüksek konsantrasyonda geçen protein sentez inhibitörlerinin (tetrasiklin/makrolid) gerekmesi`,B:`Klamidyanın aşırı beta-laktamaz salgılayarak tüm beta-laktamları lize etmesi`,C:`Beta-laktamların klamidya sporlarını harekete geçirmesi`,D:`Klamidyanın bir virüs olması`,E:`Beta-laktamların hücre zarlarından tamamen geri emilememesi`},dogru:`A`,aciklama:`Chlamydia trachomatis zorunlu intrasellüler bir bakteridir ve tipik bir peptidoglikan hücre duvarına sahip değildir. Hücre içine penetre olamayan veya hücre duvarı peptidoglikan çapraz bağlarını hedefleyen beta-laktamlar klamidyayı eradike edemez; bu nedenle hücre içine yüksek oranda giren ve 30S/50S ribozomal alt birimleri inhibe eden Doksisiklin veya Azitromisin tercih edilir.`,sik_aciklamalari:{A:`Doğrudur; hücre içi yerleşim ve atipik duvar yapısı nedeniyle hücre içine penetre olan ribozomal inhibitörler gerekir.`,B:`Primer sorun beta-laktamaz değildir; hücre içi yerleşim ve peptidoglikan eksikliğidir.`,C:`Klamidya spor oluşturmaz.`,D:`Klamidya virüs değil bakteridir.`,E:`Beta-laktamlar intrasellüler bakteriyel hedeflere yetersiz kalır.`},bilgi:[11],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:12,metin:`Gonorede antimikrobiyal direnç mekanizmalarını ve kombine tedavi şemalarını açıklayabilmek`,sorular:[{id:`k1-17-q34`,kazanim:12,zorluk:`kolay`,soru:`Gonorenin standart kombine tedavi şeması hangisidir?`,secenekler:{A:`Siprofloksasin tek başına`,B:`Penisilin G tek başına`,C:`Tetrasiklin tek başına`,D:`Seftriakson 250 mg tek doz + azitromisin 1 g`,E:`Metronidazol + flukonazol`},dogru:`D`,aciklama:`Direnç nedeniyle monoterapi yerine kombine tedavi zorunludur.`,sik_aciklamalari:{A:`Kinolon direnci vardır.`,B:`Penisilinaz direnci nedeniyle uygun değildir.`,C:`Tetrasiklin direnci vardır.`,D:`Doğru: standart kombine tedavidir.`,E:`Bu kombinasyon gonore tedavisi değildir.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-17-q35`,kazanim:12,zorluk:`orta`,soru:`Gonokokta antimikrobiyal direnç mekanizmaları arasında aşağıdakilerden hangisi yer almaz?`,secenekler:{A:`Penisilinaz üretimi`,B:`Hücre duvarı olmaması`,C:`Penisilin bağlayan protein (PBP) değişimi`,D:`Tetrasiklin direnci`,E:`Kinolon direnci`},dogru:`B`,aciklama:`Gonokok direnci penisilinaz, PBP değişimi, tetrasiklin ve kinolon direncini kapsar; gonokokun hücre duvarı vardır.`,sik_aciklamalari:{A:`Direnç mekanizmasıdır.`,B:`Doğru: gonokok hücre duvarına sahiptir.`,C:`Direnç mekanizmasıdır.`,D:`Direnç mekanizmasıdır.`,E:`Direnç mekanizmasıdır.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-17-q36`,kazanim:12,zorluk:`zor`,soru:`Sefalosporin alerjisi olan gonoreli hastada önerilen alternatif tedavi hangisidir?`,secenekler:{A:`Tedavi verilmez`,B:`Seftriakson + azitromisin`,C:`Yalnızca penisilin`,D:`Metronidazol`,E:`Gemifloksasin veya gentamisin + azitromisin 2 g`},dogru:`E`,aciklama:`Azitromisin alerjisinde doksisiklin; sefalosporin alerjisinde gemifloksasin veya gentamisin + azitromisin 2 g kullanılır.`,sik_aciklamalari:{A:`Tedavi gereklidir; bu nedenle doğru seçenek değildir.`,B:`Seftriakson sefalosporindir.`,C:`Penisilin direnç nedeniyle uygun değildir.`,D:`Metronidazol gonokoka etkili değildir.`,E:`Doğru: önerilen alternatif şemadır.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k12-q04`,kazanim:12,zorluk:`orta`,soru:`54 yaşındaki bir hasta ayırıcı tanısı tartışılan ve öyküsü derinleştirilen bir hastada hekime başvuruyor. Değerlendirmede "Penisilinaz üretimi (penisilin ve dar spektrumlu sefalosporin hidrolizi), PBP değişimi, tetrasiklin ve kinolon direnci söz konusudur." bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "Gonorede antimikrobiyal direnç mekanizmalarını ve kombine tedavi şemalarını açıklayabilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Penisilinaz üretimi (penisilin ve dar spektrumlu sefalosporin hidrolizi), PBP değişimi, tetrasiklin… ilkesinin tam tersi geçerlidir ve Direnç nedeniyle monoterapi yerine kombine tedavi zorunludur. gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Gonokok direnç mekanizmaları olup "Gonorede antimikrobiyal direnç mekanizmalarını ve kombine…" ile ilişkisizdir`,C:`Bulgular "Gonorede antimikrobiyal direnç mekanizmalarını ve kombine tedavi…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,D:`Penisilinaz üretimi (penisilin ve dar spektrumlu sefalosporin hidrolizi), PBP değişimi, tetrasiklin ve kinolon direnci söz konusudur. Bu nedenle Direnç nedeniyle monoterapi yerine kombine tedavi zorunludur.`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Gonokok direnç mekanizmaları" ile açıklanamaz`},dogru:`D`,aciklama:`Robbins/Harrison mantığıyla: Penisilinaz üretimi (penisilin ve dar spektrumlu sefalosporin hidrolizi), PBP değişimi, tetrasiklin ve kinolon direnci söz konusudur. Doğrudan sonucu "Direnç nedeniyle monoterapi yerine kombine tedavi zorunludur." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Gonokok direnç mekanizmaları" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Gonokok direnç mekanizmaları" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Gonokok direnç mekanizmaları" bilgisiyle çelişir.`,D:`Doğru; Penisilinaz üretimi (penisilin ve dar spektrumlu sefalosporin hidrolizi), PBP değişimi, tetrasiklin ve…`,E:`Yanlış; ders paketindeki "Gonokok direnç mekanizmaları" bilgisiyle çelişir.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k12-q05`,kazanim:12,zorluk:`zor`,soru:`Farklı bir hasta tanısal test sonucunun yorumlandığı bağımsız bir olguda ele alınıyor. Öyküde "Gonokok direnç mekanizmaları" vurgulanıyor ve hekim "Gonorede antimikrobiyal direnç mekanizmalarını ve kombine tedavi şemalarını açıklayabilmek" kazanımındaki "Penisilinaz üretimi (penisilin ve dar spektrumlu sefalosporin hidrolizi), PBP değişimi, tetrasiklin ve kinolon direnci söz konusudur." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Direnç nedeniyle monoterapi yerine kombine tedavi zorunludur. hiçbir koşulda gözlenmez ve Gonokok direnç mekanizmaları tek belirleyicidir`,B:`Bu süreçte "Gonokok direnç mekanizmaları" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Benzer tabloların tamamı aynı nedene bağlıdır; "Gonokok direnç mekanizmaları" ayırıcı tanıda gereksizdir`,D:`Bu olguda izlem gerekmez; "Gonorede antimikrobiyal direnç mekanizmalarını ve kombine tedavi…" yalnızca teorik bir bilgidir`,E:`Direnç nedeniyle monoterapi yerine kombine tedavi zorunludur. Çünkü Penisilinaz üretimi (penisilin ve dar spektrumlu sefalosporin hidrolizi), PBP değişimi, tetrasiklin ve…`},dogru:`E`,aciklama:`Guyton/Robbins bütünlüğünde: Penisilinaz üretimi (penisilin ve dar spektrumlu sefalosporin hidrolizi), PBP değişimi, tetrasiklin ve kinolon direnci söz konusudur. sonucu "Direnç nedeniyle monoterapi yerine kombine tedavi zorunludur." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Gonokok direnç mekanizmaları" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Gonokok direnç mekanizmaları" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Gonokok direnç mekanizmaları" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Gonokok direnç mekanizmaları" bilgisiyle çelişir.`,E:`Doğru; Direnç nedeniyle monoterapi yerine kombine tedavi zorunludur. Çünkü Penisilinaz üretimi (penisilin ve dar…`},bilgi:[21],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k12-q06`,kazanim:12,zorluk:`orta`,soru:`Gonokok direnç mekanizmaları: Penisilinaz üretimi (penisilin ve dar spektrumlu sefalosporin hidrolizi), PBP değişimi, tetrasiklin ve kinolon direnci söz konusudur. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi komplikasyonlara yol açar`,B:`Gebede uygun ilaç seçimi fetal güvenliği korur`,C:`İlk atakta ciddi ülserasyon ve nörolojik tutulum olabilir`,D:`Sendromik yaklaşım, etken bilinmeden tedaviye başlamayı (ör. ülserli hastalık) sağlar`,E:`Direnç nedeniyle monoterapi yerine kombine tedavi zorunludur`},dogru:`E`,aciklama:`Enfeksiyon Hastalıkları düzeneğinde Penisilinaz üretimi (penisilin ve dar spektrumlu sefalosporin bilinir. Direnç nedeniyle monoterapi yerine kombine tedavi zorunludur. Mekanizma bu sırayla işlediği için beklenen sonuç Direnç nedeniyle monoterapi yerine kombine tedavi zorunludur olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt E seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Asemptomatik seyir oranları sürecine ait bir özelliktir ve gonokok direnç mekanizmaları düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Klamidya tedavisi sürecine ait bir özelliktir ve gonokok direnç mekanizmaları düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Genital herpes sürecine ait bir özelliktir ve gonokok direnç mekanizmaları düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Klinik sendromlar sürecine ait bir özelliktir ve gonokok direnç mekanizmaları düzeneğini tanımlamaz.`,E:`Doğru; Direnç nedeniyle monoterapi yerine kombine tedavi zorunludur çünkü Penisilinaz üretimi (penisilin ve dar spektrumlu sefalosporin hidrolizi), düzeneği bu sonucu üretir.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k12-q07`,kazanim:12,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Gonore kombine tedavisi mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Hasta başı ekim ve %10 CO2'li ortam gerekir`,B:`Seftriakson 1x250 mg + azitromisin 1 g (standart)`,C:`Sefoksitin 4x2 g + doksisiklin 2x100 mg veya ampisilin/sulbaktam 4x3`,D:`Etkenler bakteri (N. gonorrhoeae, C. trachomatis, T. pallidum, H. ducreyi,`,E:`%10 KOH veya Gram boyama ile tomurcuklanan maya hücreleri kandidiyazisi`},dogru:`B`,aciklama:`Seftriakson 1x250 mg + azitromisin 1 g (standart). Alerji durumunda etkin alternatif şemalar mevcuttur. Fizyopatolojik sıra bu yönde ilerlediğinden Seftriakson 1x250 mg + azitromisin 1 g varlığında Alerji durumunda etkin alternatif şemalar mevcuttur beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt B seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade N. gonorrhoeae kültürü sürecine ait bir özelliktir ve gonore kombine tedavisi düzeneğini tanımlamaz.`,B:`Doğru; Seftriakson 1x250 mg + azitromisin 1 g (standart). Bu mekanizma alerji durumunda etkin alternatif şemalar mevcuttur sonucunu doğurur.`,C:`Yanlış; bu ifade PİH intravenöz rejimleri sürecine ait bir özelliktir ve gonore kombine tedavisi düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade CYBH etken sınıflaması sürecine ait bir özelliktir ve gonore kombine tedavisi düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Maya (KOH/Gram) sürecine ait bir özelliktir ve gonore kombine tedavisi düzeneğini tanımlamaz.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k12-q08`,kazanim:12,zorluk:`orta`,soru:`Komplike olmayan ürogenital, rektal veya faringeal gonore (Neisseria gonorrhoeae) enfeksiyonunun tedavisinde güncel CDC ve uluslararası rehberlerin önerdiği İLK SEÇENEK standart rejim aşağıdakilerden hangisidir?`,secenekler:{A:`Seftriakson 500 mg intramusküler (IM) tek doz (hastanın kilosu ≥ 150 kg ise 1 gram IM)`,B:`Oral penisilin V 4x500 mg 10 gün`,C:`Siprofloksasin 500 mg tek doz oral`,D:`Ko-trimoksazol 2 tablet tek doz`,E:`Eritromisin 500 mg 7 gün`},dogru:`A`,aciklama:`Gonokoklarda florokinolonlara, penisilinlere ve azitromisine yüksek oranlarda direnç gelişmesi nedeniyle güncel rehberlerde gonore tedavisinde monoterapi olarak yüksek doz parenteral sefalosporin: 'Seftriakson 500 mg IM tek doz' önerilmektedir (vücut ağırlığı ≥ 150 kg ise 1 g IM). Eğer eşlik eden klamidya dışlanamamışsa tedaviye Doksisiklin (2x100 mg 7 gün) eklenir.`,sik_aciklamalari:{A:`Doğrudur; güncel standart tedavi Seftriakson 500 mg tek doz IM'dir.`,B:`Penisilin direnci çok yüksektir, kullanılamaz.`,C:`Florokinolonlara (siprofloksasin) küresel düzeyde yüksek direnç vardır.`,D:`Ko-trimoksazole direnç nedeniyle kullanılamaz.`,E:`Eritromisin gonore tedavisinde yetersizdir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k12-q09`,kazanim:12,zorluk:`zor`,soru:`Neisseria gonorrhoeae'nin üçüncü kuşak sefalosporinlere (seftriakson, sefiksim) karşı azalmış duyarlılık veya direnç geliştirmesinde rol oynayan en önemli moleküler direnç mekanizması aşağıdakilerden hangisidir?`,secenekler:{A:`penA geninde mutasyonlar sonucu penisilin bağlayan protein 2'nin (PBP2) yapısının değişmesi ve afinitesinin düşmesi`,B:`Bakterinin plazmit kaynaklı karbapenemaz enzimi üretmesi`,C:`DNA giraz enziminin tamamen yok olması`,D:`Dış membran lipopolisakkarit tabakasının kapsüle dönüşmesi`,E:`Ribozom 50S alt biriminin metilasyonu`},dogru:`A`,aciklama:`Gonokoklarda sefalosporin direncinin ana mekanizması, penA genindeki mutasyonlar (özellikle mozaik penA alelleri) sonucu sentezlenen PBP2 (Penisilin Bağlayan Protein 2) molekülünün sefalosporinlere bağlanma afinitesinin belirgin azalmasıdır. Beraberinde porB (akış kanalının daralması) ve mtrR (MtrCDE dışa atım pompasının aşırı çalışması) mutasyonları eşlik ederek direnci artırır.`,sik_aciklamalari:{A:`Doğrudur; penA gen mutasyonu ile PBP2 afinite düşüşü sefalosporin direncinin temelidir.`,B:`Gonokoklarda karbapenemaz ana sefalosporin direnç mekanizması değildir.`,C:`DNA giraz (gyrA) mutasyonu florokinolon direncinden sorumludur.`,D:`Lipopolisakkarit kapsüle dönüşmez.`,E:`50S metilasyonu (erm genleri) makrolid direncidir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k12-q10`,kazanim:12,zorluk:`zor`,soru:`Ağır beta-laktam (sefalosporin ve penisilin) anafilaksi öyküsü olan bir gonore hastasında parenteral tedavi için önerilen en uygun alternatif rejim aşağıdakilerden hangisidir?`,secenekler:{A:`Gentamisin 240 mg IM tek doz + Azitromisin 2 g oral tek doz`,B:`Vankomisin 1 g IV infüzyon`,C:`Amoksisilin-klavulanat 1000 mg oral tek doz`,D:`Metronidazol 2 g oral tek doz`,E:`Klindamisin 600 mg IV`},dogru:`A`,aciklama:`Seftriakson alerjisi (özellikle IgE aracılı anafilaksi) durumunda CDC tarafından önerilen kanıtlanmış alternatif rejim: 'Gentamisin 240 mg tek doz IM + Azitromisin 2 g tek doz oral' kombinasyonudur.`,sik_aciklamalari:{A:`Doğrudur; sefalosporin alerjisinde Gentamisin IM + Azitromisin oral kombinasyonu önerilir.`,B:`Vankomisin sadece Gram-pozitiflere etkilidir, gonokoka etkisizdir.`,C:`Amoksisilin bir beta-laktamdır, çapraz reaksiyon verir.`,D:`Metronidazol gonokoka etkisizdir.`,E:`Klindamisin gonorede etkisizdir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k12-q11`,kazanim:12,zorluk:`orta`,soru:`Gonore tanısı konan bir hastaya tedavi verilirken, test sonuçları henüz çıkmamış olsa dahi Chlamydia trachomatis ko-enfeksiyonunun da ampirik olarak kapsama alınmasının (ko-tedavi) epidemiyolojik gerekçesi nedir?`,secenekler:{A:`Gonoreli olguların %20-40'ında Chlamydia trachomatis ile eş zamanlı ko-enfeksiyon bulunması`,B:`Gonokokların klamidya bakterisine dönüşebilmesi`,C:`Seftriaksonun klamidyayı aşırı çoğaltıcı etki göstermesi`,D:`Klamidyanın seftriaksonun emilimini %100 engellemesi`,E:`İki bakterinin plazmitlerini birleştirerek virüs oluşturması`},dogru:`A`,aciklama:`Gonore saptanan hastaların önemli bir bölümünde (%20-40) Chlamydia trachomatis ile eş zamanlı enfeksiyon (ko-enfeksiyon) bulunur. Seftriakson klamidyaya etkili olmadığından, eğer klamidya NAAT testiyle ekarte edilmemişse hastaya seftriaksonun yanında mutlaka klamidya tedavisi (Doksisiklin 2x100 mg 7 gün) eklenir.`,sik_aciklamalari:{A:`Doğrudur; %20-40 ko-enfeksiyon sıklığı nedeniyle klamidya dışlanamadığında birlikte tedavi edilir.`,B:`Bakteriler birbirine dönüşemez.`,C:`Seftriakson klamidyayı çoğaltmaz.`,D:`Emilimi engellemez.`,E:`Bakteri plazmitleri virüs oluşturmaz.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k12-q12`,kazanim:12,zorluk:`zor`,soru:`Faringeal (boğaz) yerleşimli gonore enfeksiyonlarının ürogenital gonoreye kıyasla tedavisi daha zor olup tedavi başarısızlığı riskinin daha yüksek olmasının nedeni nedir?`,secenekler:{A:`Faringeal mukozaya antibiyotik penetrasyonunun daha zayıf olması ve orofaringeal kommensal Neisseria türleriyle direnç genlerinin (mozaik penA) yatay gen transferiyle kolayca paylaşılması`,B:`Farenkste tükürük enzimlerinin seftriaksonu dakikalar içinde parçalaması`,C:`Farenksteki gonokokların spor formuna geçmesi`,D:`Faringeal gonorenin sadece mantarlarla birlikte yaşaması`,E:`Tonsillerin antibiyotikleri tamamen nötralize etmesi`},dogru:`A`,aciklama:`Faringeal gonore genellikle asemptomatiktir ve tedavisi en zor anatomik bölgedir: 1) Farenks mukozasında antibiyotik doku düzeyleri üretraya göre daha düşüktür; 2) Orofarenkste yaşayan kommensal Neisseria türleri (N. lactamica, N. sicca vb.) direnç genleri için zengin bir rezervuardır ve konjugasyon/transformasyon ile gonokoklara direnç genleri aktarılır. Bu nedenle oral sefalosporinler değil, yüksek doz parenteral seftriakson şarttır ve faringeal gonorede kür testi (test of cure) önerilir.`,sik_aciklamalari:{A:`Doğrudur; zayıf penetrasyon ve floradaki Neisseria'lardan direnç gen transferi faringeal tutulumu dirençli kılar.`,B:`Tükürük seftriaksonu parçalamaz, seftriakson sistemik IM yolla verilir.`,C:`Gonokok spor oluşturmaz.`,D:`Mantarlarla zorunlu simbiyoz göstermez.`,E:`Tonsiller antibiyotiği nötralize etmez.`},bilgi:[12],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:13,metin:`Pelvik inflamatuvar hastalıkta hastaneye yatış endikasyonlarını ve intravenöz antibiyotik rejimlerini bilmek`,sorular:[{id:`k1-17-q37`,kazanim:13,zorluk:`kolay`,soru:`Aşağıdakilerden hangisi PİH'de hastaneye yatış endikasyonudur?`,secenekler:{A:`Hafif pelvik ağrı, ateşsiz`,B:`Tuboovaryan abse`,C:`Oral tedaviye iyi yanıt`,D:`Gebelik olmaması`,E:`Bulantı-kusma olmaması`},dogru:`B`,aciklama:`Yatış endikasyonları: tuboovaryan abse, gebelik, bulantı-kusma ve ateş, oral tedaviye yanıtsızlık.`,sik_aciklamalari:{A:`Ayaktan tedavi edilebilir.`,B:`Doğru: yatış endikasyonudur.`,C:`Yatış gerekmez; bu nedenle doğru seçenek değildir.`,D:`Gebelik yatış endikasyonudur, yokluğu değildir.`,E:`Kusma yatış endikasyonudur, yokluğu değildir.`},bilgi:[24],benzer_cikmis:[]},{id:`k1-17-q38`,kazanim:13,zorluk:`orta`,soru:`PİH'de intravenöz tedavi rejimlerinden biri hangisidir?`,secenekler:{A:`Metronidazol 2 g tek doz`,B:`Flukonazol tek doz`,C:`Asiklovir`,D:`Sefoksitin 4x2 g + doksisiklin 2x100 mg`,E:`Penisilin G tek başına`},dogru:`D`,aciklama:`Sefoksitin + doksisiklin veya ampisilin/sulbaktam + doksisiklin; düzelmeden 24–48 saat sonra oral tedaviye geçilip toplam 14 gün tamamlanır.`,sik_aciklamalari:{A:`Trikomonas tedavisidir.`,B:`Antifungaldir; bu nedenle doğru seçenek değildir.`,C:`Antiviraldir; bu nedenle doğru seçenek değildir.`,D:`Doğru: önerilen IV rejimdir.`,E:`PİH için uygun değildir.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-17-q39`,kazanim:13,zorluk:`zor`,soru:`PİH tedavisi ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Klinik düzelmeden 24–48 saat sonra oral doksisikline geçilir`,B:`Abse varlığında klindamisin eklenir`,C:`Toplam tedavi süresi 14 gündür`,D:`Uygun tedavi abse ve infertilite riskini azaltır`,E:`Gebelikte PİH her zaman ayaktan oral tedaviyle yönetilir`},dogru:`E`,aciklama:`Gebelik PİH'de hastaneye yatış endikasyonudur.`,sik_aciklamalari:{A:`Doğru ifade; bu nedenle doğru seçenek değildir.`,B:`Doğru ifade; bu nedenle doğru seçenek değildir.`,C:`Doğru ifade; bu nedenle doğru seçenek değildir.`,D:`Doğru ifade; bu nedenle doğru seçenek değildir.`,E:`Yanlış ifade (aranan cevap): gebelikte yatış gerekir.`},bilgi:[24,25],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k13-q04`,kazanim:13,zorluk:`orta`,soru:`61 yaşındaki bir hasta tedavi yanıtı izlenen ve kliniği yeniden değerlendirilen bir olguda hekime başvuruyor. Değerlendirmede "Seftriakson 1x250 mg + azitromisin 1 g (standart); azitromisin alerjisinde doksisiklin; sefalosporin alerjisinde gemifloksasin veya gentamisin + azitromisin 2 g." bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "Pelvik inflamatuvar hastalıkta hastaneye yatış endikasyonlarını ve intravenöz antibiyotik rejimlerini bilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Seftriakson 1x250 mg + azitromisin 1 g (standart); azitromisin alerjisinde doksisiklin;… ilkesinin tam tersi geçerlidir ve Klinik + laboratuvar + görüntüleme kombinasyonu ile tanı konur. gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma PİH klinik ve laboratuvar olup "Pelvik inflamatuvar hastalıkta hastaneye yatış…" ile ilişkisizdir`,C:`Bulgular "Pelvik inflamatuvar hastalıkta hastaneye yatış endikasyonlarını ve…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,D:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Gonore kombine tedavisi" ile açıklanamaz`,E:`Seftriakson 1x250 mg + azitromisin 1 g (standart); azitromisin alerjisinde doksisiklin; sefalosporin alerjisinde gemifloksasin veya gentamisin +… Bu nedenle Alerji durumunda etkin alternatif şemalar mevcuttur.`},dogru:`E`,aciklama:`Robbins/Harrison mantığıyla: Seftriakson 1x250 mg + azitromisin 1 g (standart); azitromisin alerjisinde doksisiklin; sefalosporin alerjisinde gemifloksasin veya gentamisin + azitromisin 2… Doğrudan sonucu "Alerji durumunda etkin alternatif şemalar mevcuttur." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Gonore kombine tedavisi" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Gonore kombine tedavisi" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Gonore kombine tedavisi" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Gonore kombine tedavisi" bilgisiyle çelişir.`,E:`Doğru; Seftriakson 1x250 mg + azitromisin 1 g (standart); azitromisin alerjisinde doksisiklin; sefalosporin…`},bilgi:[22,23],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k13-q05`,kazanim:13,zorluk:`zor`,soru:`Farklı bir hasta aynı konunun farklı bir yönünü aydınlatmak için ele alınan ikinci bir olguda ele alınıyor. Öyküde "PİH klinik ve laboratuvar" vurgulanıyor ve hekim "Pelvik inflamatuvar hastalıkta hastaneye yatış endikasyonlarını ve intravenöz antibiyotik rejimlerini bilmek" kazanımındaki "Vajinal akıntı, disparoni, intermenstrüel kanama, pelvik ağrı, ateş; uterin/adneksiyel hassasiyet, defans/rebound; akut faz reaktanları ↑; USG/MR'da…" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Klinik + laboratuvar + görüntüleme kombinasyonu ile tanı konur. Çünkü Vajinal akıntı, disparoni, intermenstrüel kanama, pelvik ağrı, ateş; uterin/adneksiyel hassasiyet,…`,B:`Klinik + laboratuvar + görüntüleme kombinasyonu ile tanı konur. hiçbir koşulda gözlenmez ve Gonore kombine tedavisi tek belirleyicidir`,C:`Bu süreçte "Gonore kombine tedavisi" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "PİH klinik ve laboratuvar" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Pelvik inflamatuvar hastalıkta hastaneye yatış endikasyonlarını ve…" yalnızca teorik bir bilgidir`},dogru:`A`,aciklama:`Guyton/Robbins bütünlüğünde: Vajinal akıntı, disparoni, intermenstrüel kanama, pelvik ağrı, ateş; uterin/adneksiyel hassasiyet, defans/rebound; akut faz reaktanları ↑; USG/MR'da… sonucu "Klinik + laboratuvar + görüntüleme kombinasyonu ile tanı konur." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Doğru; Klinik + laboratuvar + görüntüleme kombinasyonu ile tanı konur. Çünkü Vajinal akıntı, disparoni,…`,B:`Yanlış; ders paketindeki "Gonore kombine tedavisi" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Gonore kombine tedavisi" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Gonore kombine tedavisi" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Gonore kombine tedavisi" bilgisiyle çelişir.`},bilgi:[22,23],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k13-q06`,kazanim:13,zorluk:`orta`,soru:`PİH yatış endikasyonları: Tuboovaryan abse, gebelik, bulantı-kusma ve ateş yüksekliği, oral tedaviye yanıtsızlık hastaneye yatışı gerektirir. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Uygun olguda ayaktan tedavi, komplike olguda IV tedavi seçilir`,B:`Genital yakınması olmayan eklem/ağrı tablosunda CYBH akla getirilmelidir`,C:`Alerji durumunda etkin alternatif şemalar mevcuttur`,D:`Etkin tek doz tedavi ile lezyon hızla iyileşir`,E:`BV tanısı Amsel kriterleriyle konur`},dogru:`A`,aciklama:`Tuboovaryan abse, gebelik, bulantı-kusma ve ateş yüksekliği, oral tedaviye yanıtsızlık hastaneye yatışı gerektirir. Uygun olguda ayaktan tedavi, komplike olguda IV tedavi seçilir. Fizyopatolojik sıra bu yönde ilerlediğinden Tuboovaryan abse, gebelik, bulantı-kusma ve ateş yüksekliği, varlığında Uygun olguda ayaktan tedavi, komplike olguda IV beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt A seçeneğidir.`,sik_aciklamalari:{A:`Doğru; Uygun olguda ayaktan tedavi, komplike olguda IV tedavi seçilir çünkü Tuboovaryan abse, gebelik, bulantı-kusma ve ateş yüksekliği, oral düzeneği bu sonucu üretir.`,B:`Yanlış; bu ifade Sistemik komplikasyonlar sürecine ait bir özelliktir ve pi̇h yatış endikasyonları düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Gonore kombine tedavisi sürecine ait bir özelliktir ve pi̇h yatış endikasyonları düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Şankroid tedavisi sürecine ait bir özelliktir ve pi̇h yatış endikasyonları düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Clue cell (SF) sürecine ait bir özelliktir ve pi̇h yatış endikasyonları düzeneğini tanımlamaz.`},bilgi:[24],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k13-q07`,kazanim:13,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: PİH intravenöz rejimleri mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`C. trachomatis D-K serovarları`,B:`NAAT ile konur`,C:`Sefoksitin 4x2 g + doksisiklin 2x100 mg veya ampisilin/sulbaktam 4x3`,D:`Vajinitte vulvar irritasyon ve eksuda ön planda`,E:`Üretral irritasyon, kaşıntı ve dizüri üretrit triadını oluşturur`},dogru:`C`,aciklama:`Sefoksitin 4x2 g + doksisiklin 2x100 mg veya ampisilin/sulbaktam 4x3 g + doksisiklin. Uygun süre tedavi ile komplikasyon (abse, infertilite) riski azalır. Bu ilişki Enfeksiyon Hastalıkları fizyolojisinin temel düzeneklerinden biridir: Sefoksitin 4x2 g + doksisiklin 2x100 mg doğrudan Uygun süre tedavi ile komplikasyon (abse, infertilite) doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt C seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Lenfogranüloma venereum sürecine ait bir özelliktir ve pi̇h intravenöz rejimleri düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Genital herpes tanısı sürecine ait bir özelliktir ve pi̇h intravenöz rejimleri düzeneğini tanımlamaz.`,C:`Doğru; Sefoksitin 4x2 g + doksisiklin 2x100 mg veya ampisilin/sulbaktam 4x3 g + doksisiklin. Bu mekanizma uygun süre tedavi ile komplikasyon (abse, infertilite) riski sonucunu doğurur.`,D:`Yanlış; bu ifade Vajinit ve servisit ayrımı sürecine ait bir özelliktir ve pi̇h intravenöz rejimleri düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Üretral akıntı ve üretrit sürecine ait bir özelliktir ve pi̇h intravenöz rejimleri düzeneğini tanımlamaz.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k13-q08`,kazanim:13,zorluk:`orta`,soru:`Pelvik İnflamatuvar Hastalık (PİH) tanısı konan bir hastada aşağıdakilerden hangisi HASTANEYE YATIŞ VE PARENTERAL TEDAVİ endikasyonlarından biri DEĞİLDİR?`,secenekler:{A:`Sadece hafif vajinal akıntısı olan ve oral tedaviyi rahat tolere edebilen hasta`,B:`Tubo-ovaryen apse (TOA) varlığı veya şüphesi`,C:`Gebelik varlığı`,D:`Oral antibiyotik tedavisini tolere edememe (ağır bulantı-kusma)`,E:`Akut apandisit gibi cerrahi acillerin ekarte edilememesi`},dogru:`A`,aciklama:`PİH'te hastaneye yatış endikasyonları: 1) Akut apandisit gibi cerrahi acillerin ekarte edilememesi, 2) Tubo-ovaryen apse varlığı, 3) Gebelik, 4) Ağır klinik tablo (yüksek ateş, bulantı, kusma, peritonit bulguları), 5) Oral tedaviye uyumsuzluk veya tolere edememe, 6) Ayaktan oral tedaviye 72 saatte klinik yanıt alınamaması. Hafif klinik tablolu ve oral tedaviyi tolere edebilen hastalar ayaktan tedavi edilir.`,sik_aciklamalari:{A:`Doğrudur (yatış endikasyonu değildir); hafif olgular ayaktan oral rejimle izlenebilir.`,B:`Tubo-ovaryen apse kesin parenteral tedavi ve yatış endikasyonudur.`,C:`Gebelik PİH'inde fetal ve maternal riskler nedeniyle yatış şarttır.`,D:`Kusan hasta oral ilaç alamaz, IV tedavi için yatırılır.`,E:`Cerrahi acil şüphesinde hastanede yakın gözlem gerekir.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k13-q09`,kazanim:13,zorluk:`zor`,soru:`Hastaneye yatırılan ve Tubo-ovaryen Apse (TOA) saptanan bir PİH hastasında, anaerobik bakterileri (Bacteroides fragilis vb.) güçlü şekilde kapsamak için paranteral tedavi protokolünde mutlaka yer alması gereken antibiyotik kombinasyonu aşağıdakilerden hangisidir?`,secenekler:{A:`Ampisilin-sulbaktam IV + Doksisiklin oral/IV VEYA Sefotetan/Sefoksitin IV + Doksisiklin VEYA Klindamisin IV + Gentamisin IV`,B:`Sadece oral azitromisin 250 mg tek doz`,C:`Sadece trimetoprim-sulfametoksazol IV`,D:`Amikasin monoterapisi IV`,E:`Oral klaritromisin 500 mg monoterapi`},dogru:`A`,aciklama:`Yatan PİH hastalarında parenteral standart rejimler şunlardır: Rejim 1: Sefotetan (2 g IV 12 saatte bir) veya Sefoksitin (2 g IV 6 saatte bir) + Doksisiklin (100 mg oral/IV 12 saatte bir). Rejim 2: Klindamisin (900 mg IV 8 saatte bir) + Gentamisin (yükleme 2 mg/kg, idame 1.5 mg/kg 8 saatte bir). Rejim 3: Ampisilin-sulbaktam (3 g IV 6 saatte bir) + Doksisiklin (100 mg 12 saatte bir). TOA varlığında anaerob etkinliği artırmak için metronidazol veya klindamisin mutlaka bulunmalıdır.`,sik_aciklamalari:{A:`Doğrudur; bu rejimler gonokok, klamidya ve pelvik anaerobları kapsayan standart yatış rejimleridir.`,B:`Tek doz oral tedavi TOA'da kesinlikle yetersizdir.`,C:`TMP-SMX PİH yatış rejiminde tek başına yer almaz.`,D:`Aminoglikozit monoterapisi anaerob ve klamidyayı kapsamaz.`,E:`Makrolid monoterapisi yetersizdir.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k13-q10`,kazanim:13,zorluk:`orta`,soru:`Ayaktan takip edilecek hafif-orta şiddetteki bir Pelvik İnflamatuvar Hastalık (PİH) vakasında CDC rehberlerince önerilen standart AYAKTAN tedavi rejimi aşağıdakilerden hangisidir?`,secenekler:{A:`Seftriakson 500 mg IM tek doz + Doksisiklin 2x100 mg oral 14 gün + Metronidazol 2x500 mg oral 14 gün`,B:`Siprofloksasin 500 mg oral tek doz`,C:`Penisilin G 2.4 milyon ünite IM tek doz`,D:`Azitromisin 500 mg oral 3 gün tek başına`,E:`Metronidazol 2 g oral tek doz`},dogru:`A`,aciklama:`PİH polimikrobiyal bir tablodur (N. gonorrhoeae, C. trachomatis, anaeroblar, mikoplazmalar). Güncel kılavuzlarda ayaktan tedavi: 'Seftriakson 500 mg IM tek doz' (gonokok için) + 'Doksisiklin 100 mg oral günde 2 kez 14 gün' (klamidya ve mikoplazma için) + 'Metronidazol 500 mg oral günde 2 kez 14 gün' (bakteriyel vaginozis ve anaeroblar için) kombinasyonudur.`,sik_aciklamalari:{A:`Doğrudur; Seftriakson tek doz IM + Doksisiklin 14 gün + Metronidazol 14 gün standart ayaktan üçlü rejimdir.`,B:`Tek doz florokinolon yetersizdir ve direnç yüksektir.`,C:`Sifiliz ilacıdır, PİH'te polimikrobiyal spektrumu karşılamaz.`,D:`Azitromisin monoterapisi PİH'te yetersizdir.`,E:`Tek doz metronidazol klamidya ve gonokoku kapsamaz.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k13-q11`,kazanim:13,zorluk:`orta`,soru:`Ayaktan PİH tedavisi başlanan bir hasta tedaviye klinik yanıtın (ateş, pelvik hassasiyet ve lökositoz gerilemesi) değerlendirilmesi amacıyla en geç kaç saat sonra kontrole çağrılmalıdır?`,secenekler:{A:`48 - 72 saat sonra`,B:`1 ay sonra`,C:`6 ay sonra`,D:`İlk dozdan 2 saat sonra`,E:`Kontrole gerek yoktur`},dogru:`A`,aciklama:`Ayaktan PİH tedavisi başlanan tüm hastalar 48-72 saat (2-3 gün) içinde mutlaka yeniden muayene edilmelidir. Eğer 72 saat içinde pelvik hassasiyette, ateşte veya genel durumda belirgin klinik düzelme yoksa, tanı yeniden gözden geçirilmeli, hasta derhal hastaneye yatırılmalı, parenteral tedaviye geçilmeli ve olası tubo-ovaryen apse veya cerrahi patolojiler ultrasonla araştırılmalıdır.`,sik_aciklamalari:{A:`Doğrudur; 48-72 saat içinde klinik yanıt değerlendirilmelidir.`,B:`1 ay çok geçtir, apse ve peritonit gelişebilir.`,C:`6 ay sonra geri dönüşümsüz tubal hasar oluşur.`,D:`2 saatte antibiyotik yanıtı değerlendirilemez.`,E:`Kontrolsüz bırakılamaz.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k13-q12`,kazanim:13,zorluk:`zor`,soru:`Parenteral antibiyotik tedavisi alan yatan bir PİH hastasında intravenöz tedaviden oral tedaviye geçiş için aranan temel klinik kriter aşağıdakilerden hangisidir?`,secenekler:{A:`Klinik tablonun belirgin düzelmesi (hastanın afebril olması, karın/serviks hassasiyetinin gerilemesi) ve bu durumun en az 24-48 saat sürmesi`,B:`Kandaki nötrofil sayısının sıfıra inmesi`,C:`Hastanın idrar çıkışının 5 litreyi aşması`,D:`Ultrasonografide overlerin tamamen kaybolması`,E:`Kanda klamidya IgM antikorunun 10 kat yükselmesi`},dogru:`A`,aciklama:`Yatarak parenteral antibiyotik alan PİH hastalarında, ateş düştükten ve abdominal/servikal hassasiyet belirgin geriledikten sonra (en az 24-48 saatlik klinik iyilik hali) hasta oral tedaviye (Doksisiklin ± Metronidazol) geçirilerek taburcu edilebilir ve toplam tedavi süresi mutlaka 14 güne tamamlanır.`,sik_aciklamalari:{A:`Doğrudur; en az 24-48 saat afebril ve klinik stabilite sağlandıktan sonra oral tedaviye geçilip 14 gün tamamlanır.`,B:`Nötrofil sıfırlanması agranülositozdur, istenen bir durum değildir.`,C:`Poliüri kriter değildir.`,D:`Overlerin kaybolması beklenmez.`,E:`Seroloji geçiş kriteri değildir.`},bilgi:[13],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:14,metin:`Epididimit/epididimoorşit etkenlerini, ayırıcı tanısını ve tedavisini açıklayabilmek`,sorular:[{id:`k1-17-q40`,kazanim:14,zorluk:`kolay`,soru:`Epididimit/epididimoorşitin cinsel yolla bulaşan etkenleri hangileridir?`,secenekler:{A:`Candida ve Aspergillus`,B:`HPV ve HSV`,C:`C. trachomatis ve N. gonorrhoeae`,D:`T. pallidum ve H. ducreyi`,E:`Molluscum contagiosum`},dogru:`C`,aciklama:`Epididimit etkenleri C. trachomatis, N. gonorrhoeae ve enterik bakterilerdir.`,sik_aciklamalari:{A:`Mantarlar tipik etken değildir.`,B:`Tipik epididimit etkeni değildir.`,C:`Doğru: CYBH ilişkili etkenlerdir.`,D:`Ülserli hastalık etkenleridir.`,E:`Deri lezyonu yapar; bu nedenle doğru seçenek değildir.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-17-q41`,kazanim:14,zorluk:`orta`,soru:`Gonore dışlanmış ve enterik etiyoloji düşünülen epididimoorşitte önerilen tedavi hangisidir?`,secenekler:{A:`Seftriakson 250 mg tek doz + levofloksasin 500 mg 10 gün`,B:`Metronidazol 2 g tek doz`,C:`Asiklovir`,D:`Flukonazol`,E:`Yalnızca istirahat`},dogru:`A`,aciklama:`Etiyolojik ipuçları (insertif anal seks, cerrahi öykü) tedaviyi yönlendirir.`,sik_aciklamalari:{A:`Doğru: önerilen tedavidir.`,B:`Trikomonas tedavisidir.`,C:`Antiviraldir; bu nedenle doğru seçenek değildir.`,D:`Antifungaldir; bu nedenle doğru seçenek değildir.`,E:`Antibiyotik gereklidir.`},bilgi:[26],benzer_cikmis:[]},{id:`k1-17-q42`,kazanim:14,zorluk:`zor`,soru:`Epididimoorşitte etiyolojinin enterik bakteri olabileceğini düşündüren öykü hangisidir?`,secenekler:{A:`İnsertif anal seks veya yakın zamanda ürolojik cerrahi`,B:`Yalnızca heteroseksüel vajinal ilişki`,C:`Ailede enürezis`,D:`Kabakulak aşısı`,E:`Genç yaş ve tek partner`},dogru:`A`,aciklama:`İnsertif anal seks ve cerrahi/enstrümantasyon öyküsü enterik etkenleri düşündürür.`,sik_aciklamalari:{A:`Doğru: enterik etiyoloji ipuçlarıdır.`,B:`Daha çok CYBH etkenlerini düşündürür.`,C:`İlgisizdir; bu nedenle doğru seçenek değildir.`,D:`Aşı epididimit etiyolojisini belirlemez.`,E:`CYBH etkenlerini düşündürür.`},bilgi:[14,26],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k14-q04`,kazanim:14,zorluk:`orta`,soru:`68 yaşındaki bir hasta tarama sırasında saptanan ve ileri incelemeye alınan bir kişide hekime başvuruyor. Değerlendirmede "Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal eksuda/kanama odakları görülür." bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "Epididimit/epididimoorşit etkenlerini, ayırıcı tanısını ve tedavisini açıklayabilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal eksuda/kanama odakları görülür. Bu nedenle Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir.`,B:`Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve… ilkesinin tam tersi geçerlidir ve Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha… gözlenmez`,C:`Bu tablodan sorumlu temel mekanizma Vajinit ve servisit ayrımı olup "Epididimit/epididimoorşit etkenlerini, ayırıcı tanısını ve…" ile ilişkisizdir`,D:`Bulgular "Epididimit/epididimoorşit etkenlerini, ayırıcı tanısını ve tedavisini…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Vajinit ve servisit ayrımı" ile açıklanamaz`},dogru:`A`,aciklama:`Robbins/Harrison mantığıyla: Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal eksuda/kanama odakları görülür. Doğrudan sonucu "Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Doğru; Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal…`,B:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k14-q05`,kazanim:14,zorluk:`zor`,soru:`Farklı bir hasta komplikasyon gelişen ve mekanizması sorgulanan başka bir hastada ele alınıyor. Öyküde "Vajinit ve servisit ayrımı" vurgulanıyor ve hekim "Epididimit/epididimoorşit etkenlerini, ayırıcı tanısını ve tedavisini açıklayabilmek" kazanımındaki "Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal eksuda/kanama odakları görülür." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir. hiçbir koşulda gözlenmez ve Vajinit ve servisit ayrımı tek belirleyicidir`,B:`Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir. Çünkü Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal…`,C:`Bu süreçte "Vajinit ve servisit ayrımı" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Vajinit ve servisit ayrımı" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Epididimit/epididimoorşit etkenlerini, ayırıcı tanısını ve tedavisini…" yalnızca teorik bir bilgidir`},dogru:`B`,aciklama:`Guyton/Robbins bütünlüğünde: Vajinitte vulvar irritasyon ve eksuda ön planda; servisitte disparoni, postkoital kanama ve servikal eksuda/kanama odakları görülür. sonucu "Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,B:`Doğru; Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir. Çünkü Vajinitte vulvar…`,C:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Vajinit ve servisit ayrımı" bilgisiyle çelişir.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k14-q06`,kazanim:14,zorluk:`orta`,soru:`Epididimoorşit tedavisi: Seftriakson 1x250 mg tek doz + levofloksasin 1x500 mg 10 gün. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Partnerin eş zamanlı tedavisi ile reenfeksiyon önlenir`,B:`Etiyolojik ipucu (insertif anal seks, cerrahi öykü) tedaviyi yönlendirir`,C:`Uygun süre tedavi ile komplikasyon (abse, infertilite) riski azalır`,D:`Anneden bebeğe geçiş bilgisi (ör. HBV, HIV, sifilis) perinatal profilkazi`,E:`Gonore düşünülen hastada kombine tedavi (seftriakson + azitromisin) başlanır`},dogru:`B`,aciklama:`Seftriakson 1x250 mg tek doz + levofloksasin 1x500 mg 10 gün. Etiyolojik ipucu (insertif anal seks, cerrahi öykü) tedaviyi yönlendirir. Bu ilişki Enfeksiyon Hastalıkları fizyolojisinin temel düzeneklerinden biridir: Seftriakson 1x250 mg tek doz + levofloksasin doğrudan Etiyolojik ipucu (insertif anal seks, cerrahi öykü) doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt B seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Trikomoniyazis tedavisi sürecine ait bir özelliktir ve epididimoorşit tedavisi düzeneğini tanımlamaz.`,B:`Doğru; Etiyolojik ipucu (insertif anal seks, cerrahi öykü) tedaviyi yönlendirir çünkü Seftriakson 1x250 mg tek doz + levofloksasin 1x500 düzeneği bu sonucu üretir.`,C:`Yanlış; bu ifade PİH intravenöz rejimleri sürecine ait bir özelliktir ve epididimoorşit tedavisi düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Bulaş yolları sürecine ait bir özelliktir ve epididimoorşit tedavisi düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Gram negatif diplokoklar sürecine ait bir özelliktir ve epididimoorşit tedavisi düzeneğini tanımlamaz.`},bilgi:[26],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k14-q07`,kazanim:14,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Vajinit ve servisit ayrımı mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Tuboovaryan abse, gebelik, bulantı-kusma ve ateş yüksekliği, oral tedaviye yanıtsızlık`,B:`Kondiloma akuminata`,C:`%10 KOH veya Gram boyama ile tomurcuklanan maya hücreleri kandidiyazisi`,D:`Vajinitte vulvar irritasyon ve eksuda ön planda`,E:`Reaktif artrit`},dogru:`D`,aciklama:`Enfeksiyon Hastalıkları düzeneğinde Vajinitte vulvar irritasyon ve eksuda ön planda bilinir. Feragat: serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir. Mekanizma bu sırayla işlediği için beklenen sonuç serviğe ait akıntı üst genital enfeksiyon (PİH) olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt D seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade PİH yatış endikasyonları sürecine ait bir özelliktir ve vajinit ve servisit ayrımı düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Anogenital siğil sürecine ait bir özelliktir ve vajinit ve servisit ayrımı düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Maya (KOH/Gram) sürecine ait bir özelliktir ve vajinit ve servisit ayrımı düzeneğini tanımlamaz.`,D:`Doğru; Vajinitte vulvar irritasyon ve eksuda ön planda. Bu mekanizma serviğe ait akıntı üst genital enfeksiyon (pi̇h) açısından sonucunu doğurur.`,E:`Yanlış; bu ifade Sistemik komplikasyonlar sürecine ait bir özelliktir ve vajinit ve servisit ayrımı düzeneğini tanımlamaz.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k14-q08`,kazanim:14,zorluk:`orta`,soru:`Akut skrotal ağrıyla acil servise başvuran genç bir erkekte Akut Epididimit ile cerrahi bir acil olan Testis Torsiyonunun ayırıcı tanısında kullanılan 'Prehn belirtisi' (Prehn's sign) nasıl yorumlanır?`,secenekler:{A:`Testisin elle yukarı kaldırılmasıyla ağrının hafiflemesi epididimit lehinedir (Pozitif Prehn); torsiyonda ise ağrı hafiflemez veya şiddetlenir`,B:`Testisin kaldırılmasıyla ağrının artması epididimit tanısı koydurur`,C:`Prehn testi sadece kadınlarda uygulanabilen bir testtir`,D:`Kremaster refleksinin kaybolması epididimite özgüdür`,E:`Prehn testi idrarda kan bulunması durumudur`},dogru:`A`,aciklama:`Prehn belirtisi: Skrotum ve etkilenen testisin muayene eden hekim tarafından fiziksel olarak yukarı kaldırılmasıyla epididimit ağrısı hafifler (Pozitif Prehn belirtisi - venöz dönüş rahatlar). Testis torsiyonunda ise kord bükülmüş olduğu için elevasyon ağrıyı dindirmez, hatta artırabilir (Negatif Prehn). Ancak altın standart ayırıcı tanı acil Renkli Doppler USG'dir.`,sik_aciklamalari:{A:`Doğrudur; testisi kaldırmakla ağrının azalması Pozitif Prehn'dir ve epididimiti düşündürür.`,B:`Ağrının artması torsiyona işaret eder.`,C:`Erkek skrotal muayenesidir.`,D:`Kremaster refleksinin kaybı torsiyon lehinedir; epididimitte refleks genellikle korunur.`,E:`Prehn fizik muayene bulgusudur, hematüri değildir.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k14-q09`,kazanim:14,zorluk:`orta`,soru:`Renkli Doppler Ultrasonografide etkilenen tarafta testis ve epididimde KAN AKIMININ ARTMIŞ (hiperemik) izlenmesi öncelikle hangisini desteklerken; KAN AKIMININ HİÇ İZLENMEMESİ (avasküler testis) hangi acil durumu gösterir?`,secenekler:{A:`Kan akımı artışı: Akut Epididimit / Kan akımı yokluğu: Akut Testis Torsiyonu`,B:`Kan akımı artışı: Testis Kanseri / Kan akımı yokluğu: Hidrosel`,C:`Kan akımı artışı: Testis Torsiyonu / Kan akımı yokluğu: Epididimit`,D:`Her iki bulgu da varikosel tanısı koydurur`,E:`Kan akımı yokluğu sadece sperm yokluğunu gösterir`},dogru:`A`,aciklama:`Akut epididimitte enflamasyona bağlı aktif hiperemi gelişir; Doppler USG'de epididim genişlemiş ve vaskülaritesi (kan akımı) belirgin artmıştır. Testis torsiyonunda ise spermatik kordun kendi etrafında dönmesi kan akımını keser; testiste kan akımı izlenmez (avasküler nekroz riski). Bu bulgu acil cerrahi detorsiyon endikasyonudur.`,sik_aciklamalari:{A:`Doğrudur; hiperemi epididimiti, avaskülarite acil testis torsiyonunu gösterir.`,B:`Hidroselde sıvı birikimi vardır.`,C:`Tam tersi bir ifadedir.`,D:`Varikosel pampiniform pleksus dilatasyonudur.`,E:`Doppler kan akımını ölçer, sperm hücresini değil.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k14-q10`,kazanim:14,zorluk:`orta`,soru:`Cinsel yolla bulaşan enfeksiyon riski taşıyan 28 yaşındaki bir erkekte akut epididimit saptandığında başlanması gereken ampirik antibiyotik tedavisi aşağıdakilerden hangisidir?`,secenekler:{A:`Seftriakson 500 mg IM tek doz + Doksisiklin 100 mg oral günde 2 kez, 10-14 gün`,B:`Metronidazol 500 mg tek doz`,C:`Vankomisin 1 g IV tek doz`,D:`Siprofloksasin 250 mg tek doz`,E:`Flukonazol 150 mg tek doz`},dogru:`A`,aciklama:`35 yaş altı cinsel aktif erkeklerde akut epididimite en sık N. gonorrhoeae ve C. trachomatis yol açar. Bu nedenle tedavi: N. gonorrhoeae için 'Seftriakson 500 mg IM tek doz' ve C. trachomatis için 'Doksisiklin 2x100 mg/gün oral 10-14 gün' kombinasyonudur.`,sik_aciklamalari:{A:`Doğrudur; Seftriakson tek doz IM + Doksisiklin 10-14 gün genç erkek epididimitinin standart rejimidir.`,B:`Metronidazol trikomonasa etkilidir, gonore ve klamidyayı tedavi etmez.`,C:`Vankomisin Gram-pozitif ilacıdır.`,D:`Florokinolon direnci nedeniyle gonorede monoterapi olarak önerilmez.`,E:`Flukonazol antifungaldir.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k14-q11`,kazanim:14,zorluk:`zor`,soru:`Insertif (verici) anal cinsel ilişki öyküsü olan genç bir erkekte akut epididimit geliştiğinde, standart gonokok ve klamidya etkenlerine ek olarak hangi patojen grubu da ampirik tedavide mutlaka hedeflenmelidir?`,secenekler:{A:`Enterik Gram-negatif basiller (özellikle Escherichia coli)`,B:`Legionella pneumophila`,C:`Clostridium tetani`,D:`Borrelia burgdorferi`,E:`Brucella melitensis`},dogru:`A`,aciklama:`Verici (insertif) anal ilişki yapan bireylerde rektal florada bulunan enterik koliform bakteriler (özellikle E. coli) üretraya bulaşarak retrograd yolla epididimite yol açabilir. Bu hastalarda N. gonorrhoeae ve C. trachomatis'in yanı sıra enterik bakteriler de düşünülerek Seftriakson 500 mg IM tek doz + Levofloksasin (veya Ofloksasin) 10-14 gün rejimi önerilir.`,sik_aciklamalari:{A:`Doğrudur; anal ilişkide rektal enterik floradan E. coli geçişi sıktır.`,B:`Legionella su sistemlerinden bulaşır, akciğer tutulumu yapar.`,C:`Tetanus kirli yara enfeksiyonudur.`,D:`Borrelia kene ile bulaşır (Lyme hastalığı).`,E:`Brucella pastörize edilmemiş süt ürünleriyle bulaşır.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k14-q12`,kazanim:14,zorluk:`orta`,soru:`Kabakulak (mumps) virüs enfeksiyonu geçiren postpubertal bir erkekte parotit başlangıcından 4-7 gün sonra testis tutulumu (viral orşit) geliştiğinde, bu tablonun bakteriyel epididimitten temel farkı aşağıdakilerden hangisidir?`,secenekler:{A:`İdrar tahlili ve üretral sürüntünün genellikle tamamen normal olması ve antibiyotik tedavisinin etkisiz olması (destek tedavisi verilmesi)`,B:`Testiste masif kangren oluşması ve acil orşiektomi gerekmesi`,C:`Üretradan bol yeşil cerahatli akıntı gelmesi`,D:`Seftriakson verilince 2 saatte tamamen iyileşmesi`,E:`Kabakulak orşitinde testis boyutunun küçülmesi`},dogru:`A`,aciklama:`Kabakulak orşiti primer viral bir enfeksiyondur. Postpubertal erkeklerin yaklaşık %20-30'unda parotitten sonra gelişir. Üretrit bulgusu (akıntı, idrarda lökosit) yoktur; etken virüs olduğu için antibiyotiklerin hiçbir yeri yoktur. Tedavi semptomatiktir (istirahat, skrotal elevasyon, soğuk uygulama, analjezikler).`,sik_aciklamalari:{A:`Doğrudur; viral etken olduğundan idrar/sürüntü sterildir, antibiyotik etkisizdir ve destek tedavisi verilir.`,B:`Testis kangreni nadirdir, ancak atrofi ve kısırlık riski doğurabilir.`,C:`Üretral pürülan akıntı gonorede görülür, kabakulakta görülmez.`,D:`Antibiyotikler virüslere etkisizdir.`,E:`Akut evrede testis ödemli ve büyümüştür; iyileşme sonrasında atrofi gelişebilir.`},bilgi:[14],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:15,metin:`Genital herpes enfeksiyonunun özelliklerini ve tanı yöntemini özetleyebilmek`,sorular:[{id:`k1-17-q43`,kazanim:15,zorluk:`kolay`,soru:`Genital herpesin en sık etkeni hangisidir?`,secenekler:{A:`HSV-2`,B:`HPV 6`,C:`CMV`,D:`EBV`,E:`HBV`},dogru:`A`,aciklama:`Genital herpes genellikle HSV-2 ile oluşur; HSV-1 oranı artmaktadır.`,sik_aciklamalari:{A:`Doğru: en sık etkendir.`,B:`HPV 6 siğil yapar; bu nedenle doğru seçenek değildir.`,C:`CMV genital herpes etkeni değildir.`,D:`EBV genital herpes etkeni değildir.`,E:`HBV hepatit etkenidir.`},bilgi:[27],benzer_cikmis:[]},{id:`k1-17-q44`,kazanim:15,zorluk:`orta`,soru:`Genital herpes enfeksiyonunun özellikleri arasında aşağıdakilerden hangisi yer almaz?`,secenekler:{A:`Ağrısız, tabanı sert tek ülser`,B:`Ağrılı veziküler/ülseratif lezyonlar`,C:`Latent enfeksiyon`,D:`Rekürrens`,E:`Subklinik viral saçılım`},dogru:`A`,aciklama:`Ağrısız, tabanı sert tek ülser sifilitik şankrın özelliğidir.`,sik_aciklamalari:{A:`Doğru: sifilise aittir.`,B:`Herpes özelliğidir; bu nedenle doğru seçenek değildir.`,C:`Herpes özelliğidir; bu nedenle doğru seçenek değildir.`,D:`Herpes özelliğidir; bu nedenle doğru seçenek değildir.`,E:`Herpes özelliğidir; bu nedenle doğru seçenek değildir.`},bilgi:[27],benzer_cikmis:[]},{id:`k1-17-q45`,kazanim:15,zorluk:`zor`,soru:`Genital herpesin ilk atağında görülebilecek ciddi bulgular hangileridir?`,secenekler:{A:`Ciddi ülserasyon ve nörolojik tutulum`,B:`Hiçbir semptom olmaz`,C:`Yalnızca kaşıntı`,D:`Karnabahar görünümlü siğil`,E:`Ağrısız lenfadenopati`},dogru:`A`,aciklama:`İlk atak tekrarlayan ataklardan daha ağırdır; ciddi ülserasyon ve nörolojik tutulum olabilir.`,sik_aciklamalari:{A:`Doğru: ilk atağın ciddi bulgularıdır.`,B:`Semptomatik olabilir.`,C:`Daha ağır bulgular olabilir.`,D:`Siğil HPV bulgusudur.`,E:`Ağrısız LAP sifilisi düşündürür.`},bilgi:[27,28],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k15-q04`,kazanim:15,zorluk:`orta`,soru:`25 yaşındaki bir hasta yıllardır süren yakınmalarla başvuran ve fizik muayenede tipik bulguları saptanan bir hastada hekime başvuruyor. Değerlendirmede "Ağrılı veziküler/ülseratif lezyonlar; latent enfeksiyon, rekürrens, subklinik viral saçılım; genellikle HSV-2, HSV-1 oranı artıyor." bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "Genital herpes enfeksiyonunun özelliklerini ve tanı yöntemini özetleyebilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Ağrılı veziküler/ülseratif lezyonlar; latent enfeksiyon, rekürrens, subklinik viral saçılım;… ilkesinin tam tersi geçerlidir ve Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve… gözlenmez`,B:`Ağrılı veziküler/ülseratif lezyonlar; latent enfeksiyon, rekürrens, subklinik viral saçılım; genellikle HSV-2, HSV-1 oranı artıyor. Bu nedenle İlk atakta ciddi ülserasyon ve nörolojik tutulum olabilir.`,C:`Bu tablodan sorumlu temel mekanizma Anogenital siğil olup "Genital herpes enfeksiyonunun özelliklerini ve tanı…" ile ilişkisizdir`,D:`Bulgular "Genital herpes enfeksiyonunun özelliklerini ve tanı yöntemini…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Genital herpes" ile açıklanamaz`},dogru:`B`,aciklama:`Robbins/Harrison mantığıyla: Ağrılı veziküler/ülseratif lezyonlar; latent enfeksiyon, rekürrens, subklinik viral saçılım; genellikle HSV-2, HSV-1 oranı artıyor. Doğrudan sonucu "İlk atakta ciddi ülserasyon ve nörolojik tutulum olabilir." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Genital herpes" bilgisiyle çelişir.`,B:`Doğru; Ağrılı veziküler/ülseratif lezyonlar; latent enfeksiyon, rekürrens, subklinik viral saçılım; genellikle…`,C:`Yanlış; ders paketindeki "Genital herpes" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Genital herpes" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Genital herpes" bilgisiyle çelişir.`},bilgi:[27,28],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k15-q05`,kazanim:15,zorluk:`zor`,soru:`Farklı bir hasta tedavi seçeneğinin tartışıldığı farklı bir klinik senaryoda ele alınıyor. Öyküde "Anogenital siğil" vurgulanıyor ve hekim "Genital herpes enfeksiyonunun özelliklerini ve tanı yöntemini özetleyebilmek" kazanımındaki "Kondiloma akuminata; yumuşak, karnabahar görünümünde, ağrısız, tek/çok sayıda lezyon; tanıda biyopsi." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur. hiçbir koşulda gözlenmez ve Genital herpes tek belirleyicidir`,B:`Bu süreçte "Genital herpes" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur. Çünkü Kondiloma akuminata; yumuşak, karnabahar görünümünde, ağrısız, tek/çok sayıda lezyon; tanıda biyopsi.`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Anogenital siğil" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Genital herpes enfeksiyonunun özelliklerini ve tanı yöntemini…" yalnızca teorik bir bilgidir`},dogru:`C`,aciklama:`Guyton/Robbins bütünlüğünde: Kondiloma akuminata; yumuşak, karnabahar görünümünde, ağrısız, tek/çok sayıda lezyon; tanıda biyopsi. sonucu "Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Genital herpes" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Genital herpes" bilgisiyle çelişir.`,C:`Doğru; Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur.…`,D:`Yanlış; ders paketindeki "Genital herpes" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Genital herpes" bilgisiyle çelişir.`},bilgi:[28,31],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k15-q06`,kazanim:15,zorluk:`orta`,soru:`Genital herpes: Ağrılı veziküler/ülseratif lezyonlar. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Direnç nedeniyle monoterapi yerine kombine tedavi zorunludur`,B:`Ağrılı ülser + negatif sifilis ve HSV testleri şankroidi destekler`,C:`İlk atakta ciddi ülserasyon ve nörolojik tutulum olabilir`,D:`Hızlı, ucuz bir basamak testi olup BV tanısını destekler`,E:`Sessiz enfeksiyonlar bulaşı sürdürür ve PİH gibi komplikasyonlara yol açar`},dogru:`C`,aciklama:`Enfeksiyon Hastalıkları düzeneğinde Ağrılı veziküler/ülseratif lezyonlar bilinir. İlk atakta ciddi ülserasyon ve nörolojik tutulum olabilir. Mekanizma bu sırayla işlediği için beklenen sonuç İlk atakta ciddi ülserasyon ve nörolojik tutulum olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt C seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Gonokok direnç mekanizmaları sürecine ait bir özelliktir ve genital herpes düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Şankroid klinik sürecine ait bir özelliktir ve genital herpes düzeneğini tanımlamaz.`,C:`Doğru; İlk atakta ciddi ülserasyon ve nörolojik tutulum olabilir çünkü Ağrılı veziküler/ülseratif lezyonlar düzeneği bu sonucu üretir.`,D:`Yanlış; bu ifade Amin kokusu testi (KOH) sürecine ait bir özelliktir ve genital herpes düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Asemptomatik seyir oranları sürecine ait bir özelliktir ve genital herpes düzeneğini tanımlamaz.`},bilgi:[27],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k15-q07`,kazanim:15,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Genital herpes tanısı mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Seftriakson 1x250 mg tek doz + levofloksasin 1x500 mg 10`,B:`CYBH vajinal akıntı, üretral akıntı veya yanma, anorektal akıntı, genital`,C:`Gram (-) diplokok saptanmayan servisit/üretritte en olası etken Chlamydia trachomatis'tir`,D:`Hasta başı ekim ve %10 CO2'li ortam gerekir`,E:`NAAT ile konur`},dogru:`E`,aciklama:`NAAT ile konur. Tedavi ilk atak ve tekrarlayan ataklar için ayrı planlanır. Fizyopatolojik sıra bu yönde ilerlediğinden NAAT ile konur varlığında Tedavi ilk atak ve tekrarlayan ataklar için beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt E seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Epididimoorşit tedavisi sürecine ait bir özelliktir ve genital herpes tanısı düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Klinik sendromlar sürecine ait bir özelliktir ve genital herpes tanısı düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Nongonokokal enfeksiyon sürecine ait bir özelliktir ve genital herpes tanısı düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade N. gonorrhoeae kültürü sürecine ait bir özelliktir ve genital herpes tanısı düzeneğini tanımlamaz.`,E:`Doğru; NAAT ile konur. Bu mekanizma tedavi ilk atak ve tekrarlayan ataklar için ayrı sonucunu doğurur.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k15-q08`,kazanim:15,zorluk:`orta`,soru:`Genital herpes enfeksiyonlarının primer ve rekürren ataklarının tedavisinde viral timidin kinaz enzimi tarafından aktive edilerek viral DNA polimerazı inhibe eden temel antiviral ilaç grubu aşağıdakilerden hangisidir?`,secenekler:{A:`Asiklovir, Valasiklovir ve Famsiklovir`,B:`Oseltamivir ve Zanamivir`,C:`Sofosbuvir ve Daklatasvir`,D:`Ribavirin ve İnterferon-alfa`,E:`Zidovudin ve Lamivudin`},dogru:`A`,aciklama:`Herpes Simpleks Virüs (HSV-1 ve HSV-2) tedavisinde nükleozid analoğu olan Asiklovir, onun ön ilacı olan Valasiklovir ve Pensiklovir ön ilacı olan Famsiklovir kullanılır. Bu ilaçlar önce viral 'timidin kinaz' tarafından monofosfata, ardından konak kinazları tarafından trifosfata dönüştürülerek viral DNA polimerazı seçici olarak inhibe eder.`,sik_aciklamalari:{A:`Doğrudur; HSV tedavisinde kullanılan nükleozid analogları Asiklovir, Valasiklovir ve Famsiklovirdir.`,B:`İnfluenza virüsünün nöraminidaz inhibitörleridir.`,C:`Hepatit C virüsünün direkt etkili antiviralleridir.`,D:`Hepatit C ve RSV tedavisinde kullanılır.`,E:`HIV tedavisinde kullanılan ters transkriptaz inhibitörleridir.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k15-q09`,kazanim:15,zorluk:`zor`,soru:`Genital herpes şüphesi olan bir hastada lezyon tabanından kazınarak alınan hücrelerin Giemsa veya Wright ile boyanmasıyla 'çok çekirdekli dev hücreler' ve 'Cowdry A tipi nükleer inklüzyon cisimcikleri'nin gösterildiği sitolojik test aşağıdakilerden hangisidir?`,secenekler:{A:`Tzanck yayması (Tzanck smear)`,B:`Papanicolaou (Pap) yayması`,C:`Karanlık saha mikroskopisi`,D:`Whiff testi`,E:`Amsel sitogramı`},dogru:`A`,aciklama:`Tzanck yayması, vezikül tabanından bistüri ile kazınarak alınan epitel hücrelerinin Giemsa/Wright ile boyanması testidir. Herpesvirüs (HSV ve VZV) enfeksiyonunda karakteristik 'multinükleer dev hücreler' (akantoliz sonucu kaynaşmış hücreler) ve nükleus içinde eozinofilik Cowdry A inklüzyonları görülür. Hızlıdır ancak HSV ile VZV'yi veya HSV-1 ile HSV-2'yi ayırt edemez (günümüzde NAAT/PCR tercih edilir).`,sik_aciklamalari:{A:`Doğrudur; vezikül tabanından multinükleer dev hücreleri gösteren test Tzanck yaymasıdır.`,B:`Pap smear servikal kanser tarama testidir.`,C:`Karanlık saha sifiliz spiroketlerini gösterir.`,D:`Whiff testi bakteriyel vaginozis için koku testidir.`,E:`Amsel sitogramı diye bir test yoktur, Amsel kriterleri klinik kriterlerdir.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k15-q10`,kazanim:15,zorluk:`orta`,soru:`Aktif genital herpes lezyonlarından virüsün saptanmasında ve HSV-1 ile HSV-2 tip ayrımının yapılmasında günümüzdeki EN DUYARLI VE ÖZGÜL altın standart tanı yöntemi nedir?`,secenekler:{A:`Polimeraz Zincir Reaksiyonu (PCR / NAAT)`,B:`Viral hücre kültürü`,C:`Kanda lökositoz tayini`,D:`Deri prick testi`,E:`İdrar biyokimyası`},dogru:`A`,aciklama:`Lezyonlardan viral DNA'yı çoğaltan Gerçek Zamanlı PCR (NAAT), viral kültürden 3-5 kat daha duyarlıdır, iyileşmekte olan veya ülserleşmiş lezyonlarda bile virüsü yakalayabilir ve HSV-1 ile HSV-2 tip ayrımını kesin olarak yapar. Günümüzde Amerikan ve Avrupa kılavuzlarında genital herpes tanısında altın standarttır.`,sik_aciklamalari:{A:`Doğrudur; PCR/NAAT en yüksek duyarlılık ve özgüllükle tip tayini yapan altın standarttır.`,B:`Viral kültür eskiden standarttı ancak duyarlılığı PCR'a göre oldukça düşüktür (özellikle geç lezyonlarda).`,C:`Lökositoz nonspesifiktir.`,D:`Prick testi alerji testidir.`,E:`İdrar biyokimyası viral etkeni göstermez.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k15-q11`,kazanim:15,zorluk:`zor`,soru:`Yılda 6 veya daha fazla genital herpes reaktivasyon atağı geçiren bir hastada semptomların sıklığını ve viral saçılımı (asemptomatik dökülmeyi) azaltmak amacıyla önerilen 'Süpresif Antiviral Tedavi' yaklaşımı için aşağıdakilerden hangisi DOĞRUDUR?`,secenekler:{A:`Günlük düzenli Valasiklovir (500-1000 mg/gün) veya Asiklovir (2x400 mg/gün) kullanımı atak sıklığını %70-80 azaltır ve partnerlere bulaş riskini düşürür`,B:`Süpresif tedavi virüsü gangliyonlardan tamamen yok ederek hastalığı kalıcı olarak bitirir (kür sağlar)`,C:`Süpresif tedavide sadece antibiyotik göz damlaları kullanılır`,D:`Süpresif tedavi hastanın ömrü boyunca hastanede yatmasını gerektirir`,E:`Günde 1 kez penisilin iğnesi vurulması esastır`},dogru:`A`,aciklama:`Sık rekürrens gösteren (≥6 atak/yıl) genital herpes hastalarında her gün düzenli düşük doz antiviral alınması (Valasiklovir 500-1000 mg tek doz/gün veya Asiklovir 2x400 mg/gün) süpresif tedavidir. Bu tedavi atak sıklığını %70-80 oranında baskılar ve asemptomatik viral saçılımı azaltarak partnere bulaş riskini anlamlı ölçüde düşürür. Ancak virüs duyusal gangliyonlarda latent kaldığı için süpresif tedavi latent virüsü kökten yok edemez (eradikasyon sağlamaz).`,sik_aciklamalari:{A:`Doğrudur; günlük düzenli valasiklovir veya asiklovir atakları ve bulaşı belirgin azaltır.`,B:`Virüs duyusal gangliyonlarda (sakral gangliyon) latent kalır, hiçbir antiviral latent virüsü yok edemez.`,C:`Göz damlası değil oral sistemik nükleozid analogları kullanılır.`,D:`Ayaktan oral tablet tedavisidir, yatış gerektirmez.`,E:`Penisilin bakterilere etkilidir, virüslere etkisizdir.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k15-q12`,kazanim:15,zorluk:`orta`,soru:`Doğum eylemi sırasında genital bölgesinde aktif herpes lezyonları veya lezyon öncüsü prodromal semptomları (yanma, batma) bulunan bir gebede, yenidoğana ölümcül neonatal herpes bulaşını önlemek için yapılması gereken en uygun obstetrik yaklaşım nedir?`,secenekler:{A:`Doğumun acil Sezaryen (C/S) ile gerçekleştirilmesi`,B:`Normal vajinal doğum yaptırılıp bebeğin sadece sabunlu suyla yıkanması`,C:`Doğumun evde suda doğum şeklinde yapılması`,D:`Vajinal doğumu hızlandırmak için yüksek doz oksitosin verilmesi`,E:`Bebeğe doğumdan 3 ay sonra aşı yapılması`},dogru:`A`,aciklama:`Doğum eylemi başladığında annenin genital yolunda aktif lezyon veya prodromal semptom varsa, bebeğin doğum kanalından geçerken enfekte maternal sekresyonlarla teması %30-50 oranında ölümcül neonatal herpese (dissemine herpes, fulminan ensefalit) yol açar. Bu nedenle aktif lezyonu olan gebelerde normal vajinal doğum kesinlikle kontrendikedir ve doğum Sezaryen (C-section) ile gerçekleştirilmelidir.`,sik_aciklamalari:{A:`Doğrudur; neonatal herpesten korunmak için aktif lezyon varlığında sezaryen doğum şarttır.`,B:`Vajinal temas ölümcül dissemine enfeksiyon ve ensefalit yapar; yıkamak korumaz.`,C:`Suda doğum bulaş riskini engellemez.`,D:`Vajinal doğumu zorlamak fötal enfeksiyonu kesinleştirir.`,E:`Neonatal herpes doğumdan hemen sonra gelişir, 3 ay sonra aşı korumaz.`},bilgi:[15],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:16,metin:`Şankroidin (ulkus molle) etkenini, klinik bulanı ve tedavisini açıklayabilmek`,sorular:[{id:`k1-17-q46`,kazanim:16,zorluk:`kolay`,soru:`Şankroidin (ulkus molle) etkeni hangisidir?`,secenekler:{A:`Haemophilus ducreyi`,B:`Treponema pallidum`,C:`HSV-2`,D:`Klebsiella granulomatis`,E:`Chlamydia trachomatis`},dogru:`A`,aciklama:`Şankroid H. ducreyi ile oluşan ağrılı genital ülserdir.`,sik_aciklamalari:{A:`Doğru: şankroid etkenidir.`,B:`Sifilis etkenidir; bu nedenle doğru seçenek değildir.`,C:`Genital herpes etkenidir.`,D:`Granuloma inguinale etkenidir.`,E:`LGV ve üretrit etkenidir.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-17-q47`,kazanim:16,zorluk:`orta`,soru:`Şankroidde Giemsa/Gram boyamada görülen tipik dizilim hangisidir?`,secenekler:{A:`Balık sürüsü ve tren yolu`,B:`Hücre içi diplokok`,C:`Clue cell`,D:`Cowdry A inklüzyonu`,E:`Tomurcuklanan maya`},dogru:`A`,aciklama:`Şankroidde hızla ülserleşen, pürülan tabanlı ağrılı lezyon ve balık sürüsü/tren yolu dizilimi görülür.`,sik_aciklamalari:{A:`Doğru: tipik boyanma görünümüdür.`,B:`Gonoreye aittir; bu nedenle doğru seçenek değildir.`,C:`BV'ye aittir; bu nedenle doğru seçenek değildir.`,D:`Herpese aittir; bu nedenle doğru seçenek değildir.`,E:`Kandidaya aittir; bu nedenle doğru seçenek değildir.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-17-q48`,kazanim:16,zorluk:`zor`,soru:`Ağrılı, pürülan tabanlı genital ülseri olan, sifilis ve HSV testleri negatif hastada önerilen tedavi hangisidir?`,secenekler:{A:`Azitromisin 1 g tek doz veya seftriakson 250 mg tek doz`,B:`Asiklovir 7 gün`,C:`Benzatin penisilin`,D:`Flukonazol`,E:`İmikimod`},dogru:`A`,aciklama:`Tablo şankroidi destekler; tek doz azitromisin veya seftriakson etkilidir.`,sik_aciklamalari:{A:`Doğru: şankroid tedavisidir.`,B:`HSV negatif olduğundan uygun değildir.`,C:`Sifilis negatiftir; bu nedenle doğru seçenek değildir.`,D:`Antifungaldir; bu nedenle doğru seçenek değildir.`,E:`Siğil tedavisidir; bu nedenle doğru seçenek değildir.`},bilgi:[29,30],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k16-q04`,kazanim:16,zorluk:`orta`,soru:`32 yaşındaki bir hasta akut başvuru yapan ve laboratuvar-görüntüleme bulguları birlikte değerlendirilen bir olguda hekime başvuruyor. Değerlendirmede "NAAT ile konur; klinik şüphe varlığında HSV-2'ye spesifik antikor bakılır." bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "Şankroidin (ulkus molle) etkenini, klinik bulanı ve tedavisini açıklayabilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`NAAT ile konur; klinik şüphe varlığında HSV-2'ye spesifik antikor bakılır. ilkesinin tam tersi geçerlidir ve Ağrılı ülser + negatif sifilis ve HSV testleri şankroidi destekler; kesin tanı… gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Şankroid klinik olup "Şankroidin (ulkus molle) etkenini, klinik bulanı ve…" ile ilişkisizdir`,C:`NAAT ile konur; klinik şüphe varlığında HSV-2'ye spesifik antikor bakılır. Bu nedenle Tedavi ilk atak ve tekrarlayan ataklar için ayrı planlanır.`,D:`Bulgular "Şankroidin (ulkus molle) etkenini, klinik bulanı ve tedavisini…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Genital herpes tanısı" ile açıklanamaz`},dogru:`C`,aciklama:`Robbins/Harrison mantığıyla: NAAT ile konur; klinik şüphe varlığında HSV-2'ye spesifik antikor bakılır. Doğrudan sonucu "Tedavi ilk atak ve tekrarlayan ataklar için ayrı planlanır." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Genital herpes tanısı" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Genital herpes tanısı" bilgisiyle çelişir.`,C:`Doğru; NAAT ile konur; klinik şüphe varlığında HSV-2'ye spesifik antikor bakılır. Bu nedenle Tedavi ilk atak ve…`,D:`Yanlış; ders paketindeki "Genital herpes tanısı" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Genital herpes tanısı" bilgisiyle çelişir.`},bilgi:[28,29],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k16-q05`,kazanim:16,zorluk:`zor`,soru:`Farklı bir hasta hastalığın seyri ve prognozunun değerlendirildiği ayrı bir vakada ele alınıyor. Öyküde "Şankroid klinik" vurgulanıyor ve hekim "Şankroidin (ulkus molle) etkenini, klinik bulanı ve tedavisini açıklayabilmek" kazanımındaki "H. ducreyi etken; hızla ülserleşen, eritemli çevreli hassas papül-püstül, pürülan taban; Giemsa/Gram'da balık sürüsü ve tren yolu." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Ağrılı ülser + negatif sifilis ve HSV testleri şankroidi destekler; kesin tanı kültür. hiçbir koşulda gözlenmez ve Genital herpes tanısı tek belirleyicidir`,B:`Bu süreçte "Genital herpes tanısı" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Benzer tabloların tamamı aynı nedene bağlıdır; "Şankroid klinik" ayırıcı tanıda gereksizdir`,D:`Ağrılı ülser + negatif sifilis ve HSV testleri şankroidi destekler; kesin tanı kültür. Çünkü H. ducreyi etken; hızla ülserleşen, eritemli çevreli hassas papül-püstül, pürülan taban; Giemsa/Gram'da balık…`,E:`Bu olguda izlem gerekmez; "Şankroidin (ulkus molle) etkenini, klinik bulanı ve tedavisini…" yalnızca teorik bir bilgidir`},dogru:`D`,aciklama:`Guyton/Robbins bütünlüğünde: H. ducreyi etken; hızla ülserleşen, eritemli çevreli hassas papül-püstül, pürülan taban; Giemsa/Gram'da balık sürüsü ve tren yolu. sonucu "Ağrılı ülser + negatif sifilis ve HSV testleri şankroidi destekler; kesin tanı kültür." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Genital herpes tanısı" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Genital herpes tanısı" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Genital herpes tanısı" bilgisiyle çelişir.`,D:`Doğru; Ağrılı ülser + negatif sifilis ve HSV testleri şankroidi destekler; kesin tanı kültür. Çünkü H. ducreyi…`,E:`Yanlış; ders paketindeki "Genital herpes tanısı" bilgisiyle çelişir.`},bilgi:[28,29],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k16-q06`,kazanim:16,zorluk:`orta`,soru:`Anogenital siğil: Kondiloma akuminata. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Uygun olguda ayaktan tedavi, komplike olguda IV tedavi seçilir`,B:`Etken grubunu bilmek tedavi ile korunma stratejisini (antibiyotik, antiviral, antiparaziter)`,C:`Kandidiyazis vajinitin non-CYBH nedenleri arasında olup tedavisi antifungal ilaçlardır`,D:`Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur`,E:`Genital yakınması olmayan eklem/ağrı tablosunda CYBH akla getirilmelidir`},dogru:`D`,aciklama:`Kondiloma akuminata. Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur. Fizyopatolojik sıra bu yönde ilerlediğinden Kondiloma akuminata varlığında Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt D seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade PİH yatış endikasyonları sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade CYBH etken sınıflaması sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Maya (KOH/Gram) sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,D:`Doğru; Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur çünkü Kondiloma akuminata düzeneği bu sonucu üretir.`,E:`Yanlış; bu ifade Sistemik komplikasyonlar sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k16-q07`,kazanim:16,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Şankroid tedavisi mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Azitromisin 1 g tek doz veya seftriakson 1x250 mg tek`,B:`H. ducreyi etken`,C:`Serum fizyolojik ile direkt bakıda epitel hücrelerine yapışmış, sınırları silinmiş`,D:`PİH endometrit, salpenjit, ooforit, tuboovaryan abse ve pelvik peritoniti kapsar`,E:`C. trachomatis D-K serovarları`},dogru:`A`,aciklama:`Azitromisin 1 g tek doz veya seftriakson 1x250 mg tek doz. Etkin tek doz tedavi ile lezyon hızla iyileşir. Bu ilişki Enfeksiyon Hastalıkları fizyolojisinin temel düzeneklerinden biridir: Azitromisin 1 g tek doz veya seftriakson doğrudan Etkin tek doz tedavi ile lezyon hızla doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt A seçeneğidir.`,sik_aciklamalari:{A:`Doğru; Azitromisin 1 g tek doz veya seftriakson 1x250 mg tek doz. Bu mekanizma etkin tek doz tedavi ile lezyon hızla iyileşir sonucunu doğurur.`,B:`Yanlış; bu ifade Şankroid klinik sürecine ait bir özelliktir ve şankroid tedavisi düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Clue cell (SF) sürecine ait bir özelliktir ve şankroid tedavisi düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Pelvik inflamatuvar hastalık sürecine ait bir özelliktir ve şankroid tedavisi düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Lenfogranüloma venereum sürecine ait bir özelliktir ve şankroid tedavisi düzeneğini tanımlamaz.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k16-q08`,kazanim:16,zorluk:`orta`,soru:`Şankroid (Ulkus molle / Yumuşak şankr) hastalığının etkeni olan bakteri aşağıdakilerden hangisidir?`,secenekler:{A:`Haemophilus ducreyi`,B:`Treponema pallidum`,C:`Klebsiella granulomatis`,D:`Chlamydia trachomatis L serovarları`,E:`Neisseria gonorrhoeae`},dogru:`A`,aciklama:`Şankroid (ulkus molle / yumuşak şankr) etkeni, Gram-negatif, fakültatif anaerob, pleomorfik ve zor üreyen bir kokobasil olan Haemophilus ducreyi'dir.`,sik_aciklamalari:{A:`Doğrudur; Haemophilus ducreyi şankroidin (ulkus molle) bakteriyel etkenidir.`,B:`Treponema pallidum sifiliz (sert şankr) etkenidir.`,C:`Klebsiella granulomatis granüloma inguinale (donovanozis) etkenidir.`,D:`Chlamydia L serovarları lenfogranüloma venereum (LGV) etkenidir.`,E:`Neisseria gonorrhoeae gonore etkenidir.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k16-q09`,kazanim:16,zorluk:`orta`,soru:`Şankroidin (Haemophilus ducreyi) ülser ve lenf bezi özellikleri, Primer Sifilizden (Treponema pallidum) ayırt edilirken aşağıdaki klinik tablolardan hangisi ŞANKROİD lehinedir?`,secenekler:{A:`Ülserin son derece AĞRILI, tabanının YUMUŞAK ve pürülan kirli eksüdayla kaplı olması; lenfadenopatinin (bubo) çok ağrılı olup fluktuasyon göstererek kendiliğinden fistülize olabilmesi`,B:`Ülserin tamamen ağrısız, tabanının sert kıkırdak kıvamında ve temiz olması`,C:`Ülserin hiçbir zaman oluşmaması, sadece döküntü olması`,D:`Lenf bezlerinin lastik kıvamında ve tamamen ağrısız olması`,E:`Ülserin temasla hiç kanamaması ve sert kabuk bağlaması`},dogru:`A`,aciklama:`Şankroid lezyonları; 'Ulkus molle' (yumuşak çıban) adından da anlaşılacağı gibi tabanı yumuşak, kenarları düzensiz ve altı oyuk (undermined), tabanı nekrotik-pürülan eksüdalı ve DOKUNMAKLA ÇOK AĞRILIDIR. Eşlik eden inguinal lenfadenopati (bubo) hastaların %50'sinde görülür, tek taraflı, son derece ağrılıdır ve süpüre olup cilde drene (fistülize) olabilir. Sifilizde ise ülser ve LAP ağrısız ve serttir.`,sik_aciklamalari:{A:`Doğrudur; ağrılı yumuşak kirli tabanlı ülser ve süpüratif fluktuan ağrılı bubo şankroidin özelliğidir.`,B:`Ağrısız sert ülser primer sifiliz şankrıdır.`,C:`Şankroid klasik genital ülseratif hastalıktır.`,D:`Ağrısız lastik kıvamlı LAP primer sifilize aittir.`,E:`Şankroid ülseri temasla çok kolay kanar ve son derece hassastır.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k16-q10`,kazanim:16,zorluk:`zor`,soru:`Haemophilus ducreyi lezyon tabanından yapılan Gram boyamada mikroskopta bakterilerin karakteristik dizilimi aşağıdakilerden hangisi ile tarif edilir?`,secenekler:{A:`Nötrofillerin ve mukusun arasında paralel zincirler halinde 'balık sürüsü' (school of fish) veya 'tren rayı' görünümü`,B:`Lökositler içinde kahve çekirdeği şeklinde diplokoklar`,C:`Üzüm salkımı şeklinde Gram-pozitif koklar`,D:`Uç uca eklenmiş bambu kamışı basilleri`,E:`Çin harfleri şeklinde dizilmiş difteroid basiller`},dogru:`A`,aciklama:`Haemophilus ducreyi, Gram boyamada lökositlerin dışında veya içinde, birbirine paralel dizilerek 'balık sürüsü' (school of fish) veya 'tren rayı / demiryolu izi' (railroad track) görünümü oluşturan küçük Gram-negatif kokobasiller şeklinde izlenir.`,sik_aciklamalari:{A:`Doğrudur; 'balık sürüsü' veya 'tren rayı' dizilimi H. ducreyi için tanımlanmıştır.`,B:`Lökosit içi kahve çekirdeği gonokoktur (Neisseria gonorrhoeae).`,C:`Üzüm salkımı Staphylococcus aureus'tur.`,D:`Bambu kamışı Bacillus anthracis'tir.`,E:`Çin harfleri Corynebacterium diphtheriae'dir.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k16-q11`,kazanim:16,zorluk:`orta`,soru:`CDC rehberlerine göre kesinleşmiş Şankroid (Haemophilus ducreyi) olgusunda önerilen İLK SEÇENEK tedavi rejimlerinden biri aşağıdakilerden hangisidir?`,secenekler:{A:`Azitromisin 1 g oral tek doz VEYA Seftriakson 250 mg IM tek doz`,B:`Metronidazol 500 mg 7 gün`,C:`Asiklovir 5x200 mg 5 gün`,D:`Penisilin G 2.4 milyon ünite IM tek doz`,E:`Flukonazol 150 mg tek doz`},dogru:`A`,aciklama:`Şankroid tedavisinde CDC rehberinde 4 standart rejim bulunur: 1) Azitromisin 1 g oral tek doz; 2) Seftriakson 250 mg IM tek doz; 3) Siprofloksasin 2x500 mg oral 3 gün; 4) Eritromisin baz 3x500 mg oral 7 gün. En pratik ve yüksek kür sağlayan seçenekler tek doz Azitromisin veya Seftriaksondur.`,sik_aciklamalari:{A:`Doğrudur; Azitromisin 1 g oral tek doz veya Seftriakson IM şankroidin birinci basamak rejimidir.`,B:`Metronidazol H. ducreyi'ye etkisizdir.`,C:`Asiklovir viral herpes ilacıdır.`,D:`Penisilin G sifiliz ilacıdır; H. ducreyi beta-laktamaz salgılayabildiğinden penisilinlere dirençlidir.`,E:`Flukonazol antifungaldir.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k16-q12`,kazanim:16,zorluk:`zor`,soru:`Şankroid hastasında gelişen fluktuan, rüptüre olmak üzere olan büyük bir inguinal lenfadenopatinin (bubo) cerrahi yönetiminde İNSİZYON VE DRENAJ YERİNE neden İĞNE ASPİRASYONU tercih edilir?`,secenekler:{A:`İnsizyon ve drenajın kronik iyileşmeyen fistüllere ve sekonder enfeksiyonlara yol açması; iğne aspirasyonunun ise fistül riskini azaltması`,B:`İğne aspirasyonunun genel anestezi gerektirmesi`,C:`İnsizyon yapıldığında bubonun karsinoma dönüşmesi`,D:`Bubonun içinde hiç cerahat bulunmaması`,E:`İnsizyonun lenf sıvısını tamamen tüketmesi`},dogru:`A`,aciklama:`Şankroid bubonlarına bistüri ile açık cerrahi insizyon ve drenaj yapılması kesinlikle önerilmez; çünkü açık insizyon yapıldığında yara kenarları nekrotize olur ve aylarca kapanmayan, akıntılı, ülsere fistül kanalları ve sekonder enfeksiyonlar oluşur. Ağrıyı dindirmek ve spontan rüptürü önlemek için sağlam ciltten girilerek 'iğne aspirasyonu' uygulanır.`,sik_aciklamalari:{A:`Doğrudur; açık insizyon kronik fistül ve nekroza yol açtığı için kapalı iğne aspirasyonu tercih edilir.`,B:`İğne aspirasyonu poliklinikte lokal olarak yapılır, genel anestezi gerektirmez.`,C:`Malign transformasyon yapmaz.`,D:`Bubonun içi yoğun pürülan cerahatle doludur.`,E:`Lenf sıvısını tüketmez.`},bilgi:[16],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:17,metin:`Anogenital siğilin klinik görünümünü ve tedavi seçeneklerini listeleyebilmek`,sorular:[{id:`k1-17-q49`,kazanim:17,zorluk:`kolay`,soru:`Anogenital siğilin (kondiloma akuminata) tipik klinik görünümü hangisidir?`,secenekler:{A:`Yumuşak, karnabahar görünümünde, ağrısız lezyonlar`,B:`Ağrılı veziküller`,C:`Tabanı sert ağrısız tek ülser`,D:`Pürülan tabanlı ağrılı ülser`,E:`Köpüklü sarı-yeşil akıntı`},dogru:`A`,aciklama:`Anogenital siğil tek veya çok sayıda, yumuşak, karnabahar görünümlü ağrısız lezyonlardır.`,sik_aciklamalari:{A:`Doğru: tipik görünümdür.`,B:`Herpese aittir; bu nedenle doğru seçenek değildir.`,C:`Sifilise aittir; bu nedenle doğru seçenek değildir.`,D:`Şankroide aittir; bu nedenle doğru seçenek değildir.`,E:`Trikomonasa aittir; bu nedenle doğru seçenek değildir.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-17-q50`,kazanim:17,zorluk:`orta`,soru:`Aşağıdakilerden hangisi anogenital siğil tedavi seçeneklerinden biri değildir?`,secenekler:{A:`Metronidazol`,B:`Podofilotoksin`,C:`İmikimod`,D:`Kriyoterapi`,E:`Triklorasetik asit`},dogru:`A`,aciklama:`Tedavi podofilotoksin, imikimod, kriyoterapi, TCA ve cerrahi/ablatif yöntemlerdir.`,sik_aciklamalari:{A:`Doğru: metronidazol siğil tedavisi değildir.`,B:`Tedavi seçeneğidir; bu nedenle doğru seçenek değildir.`,C:`Tedavi seçeneğidir; bu nedenle doğru seçenek değildir.`,D:`Tedavi seçeneğidir; bu nedenle doğru seçenek değildir.`,E:`Tedavi seçeneğidir; bu nedenle doğru seçenek değildir.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-17-q51`,kazanim:17,zorluk:`zor`,soru:`Anogenital siğil tanısında kesin tanı/doğrulama için kullanılabilen yöntem hangisidir?`,secenekler:{A:`Biyopsi`,B:`KOH preparatı`,C:`Amin kokusu testi`,D:`Gram boyama`,E:`Karanlık alan mikroskopisi`},dogru:`A`,aciklama:`Anogenital siğil tanısında biyopsi kullanılır; histolojide koilositoz görülür.`,sik_aciklamalari:{A:`Doğru: tanıda biyopsi kullanılır.`,B:`KOH mantar ve BV içindir.`,C:`Amin testi BV içindir.`,D:`Gram boyama bakteriler içindir.`,E:`Karanlık alan sifilis içindir.`},bilgi:[31],benzer_cikmis:[`61384be5d1e3`]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k17-q04`,kazanim:17,zorluk:`orta`,soru:`39 yaşındaki bir hasta ayırıcı tanısı tartışılan ve öyküsü derinleştirilen bir hastada hekime başvuruyor. Değerlendirmede "CYBH vajinal akıntı, üretral akıntı veya yanma, anorektal akıntı, genital ülser ve sistemik belirtilerle kendini gösterir." bulgusuna ulaşılıyor. Bu dersin (Enfeksiyon Hastalıkları – Cinsel Yolla Bulaşan Enfeksiyonlarda Tedavi) kapsamındaki "Anogenital siğilin klinik görünümünü ve tedavi seçeneklerini listeleyebilmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`CYBH vajinal akıntı, üretral akıntı veya yanma, anorektal akıntı, genital ülser ve sistemik… ilkesinin tam tersi geçerlidir ve Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve… gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Anogenital siğil olup "Anogenital siğilin klinik görünümünü ve tedavi…" ile ilişkisizdir`,C:`Bulgular "Anogenital siğilin klinik görünümünü ve tedavi seçeneklerini…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,D:`CYBH vajinal akıntı, üretral akıntı veya yanma, anorektal akıntı, genital ülser ve sistemik belirtilerle kendini gösterir. Bu nedenle Sendromik yaklaşım, etken bilinmeden tedaviye başlamayı (ör. ülserli hastalık) sağlar.`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Klinik sendromlar" ile açıklanamaz`},dogru:`D`,aciklama:`Robbins/Harrison mantığıyla: CYBH vajinal akıntı, üretral akıntı veya yanma, anorektal akıntı, genital ülser ve sistemik belirtilerle kendini gösterir. Doğrudan sonucu "Sendromik yaklaşım, etken bilinmeden tedaviye başlamayı (ör. ülserli hastalık) sağlar." doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Klinik sendromlar" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Klinik sendromlar" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Klinik sendromlar" bilgisiyle çelişir.`,D:`Doğru; CYBH vajinal akıntı, üretral akıntı veya yanma, anorektal akıntı, genital ülser ve sistemik belirtilerle…`,E:`Yanlış; ders paketindeki "Klinik sendromlar" bilgisiyle çelişir.`},bilgi:[3,31],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k17-q05`,kazanim:17,zorluk:`zor`,soru:`Farklı bir hasta tanısal test sonucunun yorumlandığı bağımsız bir olguda ele alınıyor. Öyküde "Anogenital siğil" vurgulanıyor ve hekim "Anogenital siğilin klinik görünümünü ve tedavi seçeneklerini listeleyebilmek" kazanımındaki "Kondiloma akuminata; yumuşak, karnabahar görünümünde, ağrısız, tek/çok sayıda lezyon; tanıda biyopsi." mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur. hiçbir koşulda gözlenmez ve Klinik sendromlar tek belirleyicidir`,B:`Bu süreçte "Klinik sendromlar" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Benzer tabloların tamamı aynı nedene bağlıdır; "Anogenital siğil" ayırıcı tanıda gereksizdir`,D:`Bu olguda izlem gerekmez; "Anogenital siğilin klinik görünümünü ve tedavi seçeneklerini…" yalnızca teorik bir bilgidir`,E:`Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur. Çünkü Kondiloma akuminata; yumuşak, karnabahar görünümünde, ağrısız, tek/çok sayıda lezyon; tanıda biyopsi.`},dogru:`E`,aciklama:`Guyton/Robbins bütünlüğünde: Kondiloma akuminata; yumuşak, karnabahar görünümünde, ağrısız, tek/çok sayıda lezyon; tanıda biyopsi. sonucu "Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur." verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Klinik sendromlar" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Klinik sendromlar" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Klinik sendromlar" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Klinik sendromlar" bilgisiyle çelişir.`,E:`Doğru; Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur.…`},bilgi:[3,31],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k17-q06`,kazanim:17,zorluk:`orta`,soru:`Anogenital siğil: Kondiloma akuminata. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`İlk atakta ciddi ülserasyon ve nörolojik tutulum olabilir`,B:`serviğe ait akıntı üst genital enfeksiyon (PİH) açısından daha risklidir`,C:`Yakınmaların süresine göre akut (gonokok) ve subakut/persistan (klamidya) üretrit ayırımı`,D:`Partnerin eş zamanlı tedavisi ile reenfeksiyon önlenir`,E:`Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur`},dogru:`E`,aciklama:`Kondiloma akuminata. Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur. Bu ilişki Enfeksiyon Hastalıkları fizyolojisinin temel düzeneklerinden biridir: Kondiloma akuminata doğrudan Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt E seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Genital herpes sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Vajinit ve servisit ayrımı sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Üretral akıntı ve üretrit sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Trikomoniyazis tedavisi sürecine ait bir özelliktir ve anogenital siğil düzeneğini tanımlamaz.`,E:`Doğru; Tedavi podofilotoksin, imikimod, kriyoterapi, triklorasetik asit ve cerrahi/ablatif yöntemlerden oluşur çünkü Kondiloma akuminata düzeneği bu sonucu üretir.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k17-q07`,kazanim:17,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Şankroid klinik mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Bulaş genellikle vajinal, anal veya oral mukoza yoluyla`,B:`H. ducreyi etken`,C:`Servisit veya üretritte Gram boyamada intraselüler gram negatif diplokokların görülmesi`,D:`Direkt bakı, nükleik asit amplifikasyon testleri (NAAT) ve kültür kullanılır`,E:`Vajinal akıntı, disparoni, intermenstrüel kanama, pelvik ağrı, ateş`},dogru:`B`,aciklama:`Enfeksiyon Hastalıkları düzeneğinde H. ducreyi etken bilinir. Ağrılı ülser + negatif sifilis ve HSV testleri şankroidi destekler. Mekanizma bu sırayla işlediği için beklenen sonuç Ağrılı ülser + negatif sifilis ve HSV olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt B seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Bulaş yolları sürecine ait bir özelliktir ve şankroid klinik düzeneğini tanımlamaz.`,B:`Doğru; H. Bu mekanizma ağrılı ülser + negatif sifilis ve hsv testleri sonucunu doğurur.`,C:`Yanlış; bu ifade Gram negatif diplokoklar sürecine ait bir özelliktir ve şankroid klinik düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Tanı yöntemleri sürecine ait bir özelliktir ve şankroid klinik düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade PİH klinik ve laboratuvar sürecine ait bir özelliktir ve şankroid klinik düzeneğini tanımlamaz.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k17-q08`,kazanim:17,zorluk:`orta`,soru:`Anogenital siğillerin (Kondiloma aküminata) %90'ından fazlasından sorumlu olan düşük riskli İnsan Papilloma Virüsü (HPV) tipleri aşağıdakilerden hangisidir?`,secenekler:{A:`HPV Tip 6 ve Tip 11`,B:`HPV Tip 16 ve Tip 18`,C:`HPV Tip 31 ve Tip 33`,D:`HPV Tip 45 ve Tip 52`,E:`HPV Tip 1 ve Tip 2`},dogru:`A`,aciklama:`Anogenital siğillerin (kondiloma aküminata) %90'ından fazlası düşük onkojenik riskli HPV Tip 6 ve HPV Tip 11 tarafından oluşturulur. HPV 16 ve 18 ise yüksek onkojenik riskli tipler olup serviks, anüs ve orofarenks kanserlerinin ana etkenidir. HPV 1 ve 2 ise cilt siğillerini (verruca vulgaris/plantaris) yapar.`,sik_aciklamalari:{A:`Doğrudur; genital kondilomların %90'ından HPV 6 ve 11 sorumludur.`,B:`HPV 16 ve 18 yüksek riskli onkojenik tiplerdir, kondilomdan ziyade kanser öncüsüdür.`,C:`Yüksek riskli onkojenik tiplerdir.`,D:`Yüksek riskli tiplerdir.`,E:`Genital olmayan plantar/kutanöz siğil etkenleridir.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k17-q09`,kazanim:17,zorluk:`orta`,soru:`Kondiloma aküminatanın karakteristik makroskopik ve morfolojik klinik görünümü aşağıdakilerden hangisi ile tarif edilir?`,secenekler:{A:`Karnabahar benzeri (karnabaharımsı), eksofitik, parmaksı (papillomatöz) çıkıntılar gösteren vejetatif lezyonlar`,B:`Ortası göbekli (umbilike) parlak inci tanesi papüller`,C:`Zımba ile delinmiş gibi derin nekrotik yaralar`,D:`Geniş tabanlı eritemli büller`,E:`Deri altında kalsifiye sert kistler`},dogru:`A`,aciklama:`Kondiloma aküminata; anogenital bölgede tek tek veya birleşerek geniş plaklar oluşturan, yüzeyi pürtüklü, parmaksı projeksiyonlara sahip, tipik olarak 'karnabahar görünümünde' (cauliflower-like) eksofitik, et renginde veya hiperpigmente lezyonlardır.`,sik_aciklamalari:{A:`Doğrudur; karnabahar benzeri eksofitik papillomatöz görünüm kondilomun klasiğidir.`,B:`Molluscum contagiosum bulgusudur.`,C:`Ektima veya derin ülser bulgusudur.`,D:`Büllöz pemfigoid bulgusudur.`,E:`Kondilom kalsifiye kist değildir.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k17-q10`,kazanim:17,zorluk:`orta`,soru:`Anogenital siğil tedavisinde HASTA TARAFINDAN EVDE UYGULANABİLEN (topikal hasta kontrollü) immün yanıt modülatörü ilaç aşağıdakilerden hangisidir?`,secenekler:{A:`İmikimod %5 krem`,B:`Sıvı nitrojen kriyoablasyonu`,C:`Trikloroasetik asit (TCA) %80 solüsyon`,D:`Elektrokoterizasyon`,E:`Cerrahi eksizyon`},dogru:`A`,aciklama:`Kondilom tedavileri ikiye ayrılır: 1) Hasta kontrollü tedaviler: İmikimod %5 krem (Toll-like reseptör 7 agonisti olarak interferon-alfa salgılatır), Podofiloks (podofillotoksin) ve Sinekateşin merhem; 2) Klinisyen (doktor) tarafından uygulanan tedaviler: Kriyoterapi (sıvı nitrojen), Trikloroasetik asit (TCA / BCA), Elektrokoterizasyon, Lazer ve Cerrahi eksizyon.`,sik_aciklamalari:{A:`Doğrudur; İmikimod %5 krem hasta tarafından evde haftada 3 gece sürülen topikal immün modülatördür.`,B:`Kriyoterapi doktor tarafından klinikte uygulanır.`,C:`TCA kostiktir, doku nekrozu riski nedeniyle sadece doktor tarafından titizlikle lezyona sürülür.`,D:`Elektrokoter poliklinik/ameliyathane cerrahi işlemidir.`,E:`Cerrahi eksizyon hekimce yapılır.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k17-q11`,kazanim:17,zorluk:`zor`,soru:`Gebelikte anogenital siğilleri olan bir kadında sistemik emilim toksisitesi ve teratojenite riski nedeniyle KESİNLİKLE KONTRENDİKE olan topikal tedavi ajanları aşağıdakilerin hangisinde birlikte verilmiştir?`,secenekler:{A:`Podofilin ve Podofiloks (Podofillotoksin)`,B:`Trikloroasetik asit (TCA)`,C:`Sıvı nitrojen kriyoterapisi`,D:`Cerrahi eksizyon`,E:`Elektrokoterizasyon`},dogru:`A`,aciklama:`Podofilin reçinesi ve Podofiloks antimitotiktir (hücre bölünmesinde mikrotübülleri bloke eder). Mukozadan emilerek sistemik fetal toksisite, intrauterin ölüm ve konjenital malformasyonlara yol açabildikleri için GEBELİKTE KESİNLİKLE KONTRENDİKEDİR. Gebelerde siğil tedavisinde güvenli olan yöntemler: TCA (%80-90 konsantrasyonda lokal kimyasal koter), Kriyoterapi veya cerrahi eksizyondur.`,sik_aciklamalari:{A:`Doğrudur; Podofilin ve Podofiloks teratojenik ve fetotoksik olduğu için gebelikte kesin kontrendikedir.`,B:`TCA sistemik emilmez, gebelikte güvenle kullanılır.`,C:`Kriyoterapi gebelikte güvenli bir fiziksel ablasyon yöntemidir.`,D:`Cerrahi gebelikte güvenle yapılabilir.`,E:`Koterizasyon lokal işlemdir, gebelikte uygulanabilir.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-17-cinsel-yolla-bulasan-enfeksiyonlarda-tedavi-k17-q12`,kazanim:17,zorluk:`zor`,soru:`Sekonder sifiliz lezyonu olan 'Kondiloma Lata' ile HPV lezyonu olan 'Kondiloma Aküminata' arasındaki klinik ve mikrobiyolojik ayrım için aşağıdakilerden hangisi DOĞRUDUR?`,secenekler:{A:`Kondiloma lata; geniş tabanlı, düz, ıslak ve son derece bulaşıcı olup karanlık saha mikroskopisinde bol Treponema pallidum içerir; Kondiloma aküminata ise sivri uçlu/karnabahar benzeri olup HPV kaynaklıdır`,B:`Kondiloma lata bir mantar enfeksiyonudur`,C:`Kondiloma aküminatada serolojik RPR/VDRL testleri daima 1:256 pozitif çıkar`,D:`Her iki lezyon da aynı virüsün (HPV tip 16) farklı deri katmanlarındaki varyantıdır`,E:`Kondiloma lata asla genital bölgede görülmez, sadece saçlı deride çıkar`},dogru:`A`,aciklama:`Kondiloma lata sekonder sifilizin anogenital bölgedeki klasik lezyonudur: Geniş tabanlı, düz, gri-beyaz, nemli plaklardır ve spiroketten (T. pallidum) zengin olup olağanüstü bulaşıcıdır (seroloji ve karanlık saha pozitiftir). Kondiloma aküminata ise dar saplı/tabanlı, sivri uçlu, parmaksı karnabahar benzeri HPV (tip 6, 11) siğilleridir ve spiroket içermez.`,sik_aciklamalari:{A:`Doğrudur; kondiloma lata düz ve spiroket zengini (sifiliz), kondiloma aküminata karnabahar benzeri (HPV) lezyondur.`,B:`Kondiloma lata spiroket (Treponema) lezyonudur, mantar değildir.`,C:`Kondiloma aküminatada sifiliz serolojisi negatiftir (ko-enfeksiyon yoksa).`,D:`Lata sifiliz bakterisi, aküminata HPV virüsüdür.`,E:`Kondiloma lata perine, anogenital ve nemli intertrijinöz alanlarda tipiktir.`},bilgi:[17],benzer_cikmis:[]}],ilgili_cikmis:[{id:`61384be5d1e3`,soru:`Kadınlarda servikal Üriner Sistem Enfeksiyonu ve Cinsel Yolla Bulaşan Hastalıklar kansere yol açabilen cinsel yolla bulaşan hastalık hangisidir?`,secenekler:{A:`Klamidya Trachomatis`,B:`Genital Herpes Enfeksiyonları`,C:`Şankroid`,D:`Trikomoniasiz`,E:`Gonore`},cevap:`B`}]}]};export{e as default};